(window.GIM_TS=window.GIM_TS||{})["Beitzah.2"]={"from":48,"a":[["\u0003אם יש בו מום\u0004 קבוע, שבכך הותר להשחט ולהיאכל כחולין — \u0003יעלה\u0004 אותו מן הבור \u0003וישחוט, ואם לאו,\u0004 שאין בו מום, או שהוא מום עובר — \u0003לא ישחוט\u0004 אותו. \u0003ר' שמעון אומר:\u0004 אפילו היה בו מום — אינו יכול לשחוט, כי \u0003כל שאין מומו ניכר מבעוד יום, אין זה מן המוכן\u0004 — ואסור.","ושואלים: \u0003במאי קא מפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005נחלקו]\u0006 ר' יהודה ור' שמעון? \u0003אי נימא\u0004 \u0005[אם נאמר]\u0006 שבשאלה האם \u0003רואין מומין\u0004 ביום טוב \u0003קמפלגי\u0004 \u0005[נחלקו],\u0006 ש\u0003ר' יהודה סבר: רואין מומין ביום טוב, ור' שמעון סבר: אין רואין מומין ביום טוב,\u0004 אם כן \u0003ולפלגו\u0004 \u0005[ושיחלקו]\u0006 בשאלה \u0003ברואין מומין דעלמא\u0004 \u0005[בכלל],\u0006 האם מותר לראות מומים ביום טוב, ולאו דווקא במקרה של בכור שנפל לבור!","ומשיבים: \u0003בכור שנפל לבור אצטריכא ליה\u0004 \u0005[צריך היה לו]\u0006 לומר במיוחד, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 שיש בכך נימוק נוסף \u0003משום צער בעלי חיים\u0004 ובשל נימוק זה \u0003לערים ולסקיה\u0004 \u0005[שיערים\u0006 בכך \u0005ושיעלה אותו],\u0006 ו\u0003כ\u0004דעת \u0003ר' יהושע\u0004 שדעתו בענין אחר (להלן ביצה לז, א) שבעל חיים שנפל לבור ביום טוב, אם יש דרך להערים ולהוציאו — מוציאו משם, לכך \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף כאן נחלקו.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שעיקר המחלוקת הוא בענין היתר העלאתו מן הבור, הרי לשון \u0003\"לא ישחוט\"\u0004 אינה מדוייקת, ו\u0003\"לא יעלה וישחוט\" מבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה ש\u0003עבר ו\u0004כבר \u0003אסקיה\u0004 \u0005[העלה אותו],\u0006 \u0003סלקא דעתך אמינא לשחטיה\u0004 \u0005[יעלה על דעתך\u0006 לומר \u0005שישחטנו],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל אופן לא יעשה כן.","ותוהים על תירוץ זה: \u0003לשחטיה\u0004 \u0005[שישחוט אותו]?!\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003תם הוא\u0004 בלי מום, וכיצד מותר לשחוט בזמן הזה בכור בלי מום! ומשיבים: \u0003לא צריכא, דנפל ביה מומא\u0004 \u0005[לא הוצרכה\u0006 אלא כגון \u0005שנפל בו מום]\u0006 לאחר שנפל. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מוקצה הוא,\u0004 שהרי מערב החג לא היה ראוי לאכילה, שהרי היה תמים, ובשל כך הוא נעשה מוקצה לכל החג!","\u0003אלא\u0004 יש לומר: \u0003דנפל ביה\u0004 \u0005[שנפל בו]\u0006 \u0003מום עובר\u0004 \u0005[מום חולף\u0006 שאפשר שיתרפא\u0005]\u0006 \u0003מערב יום טוב, והשתא הוה ליה\u0004 \u0005[עכשיו\u0006 לאחר שנפל \u0005יש בו]\u0006 \u0003מום קבוע. מהו דתימא\u0004 \u0005[מהו שתאמר]:\u0006 \u0003דדעתיה עלויה\u0004 \u0005[שדעתו עליו]\u0006 עוד מבעוד יום בגלל המום העובר, ולכן עכשיו \u0003ונשחטיה\u0004 \u0005[ושישחטנו]\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שכיון שלא היה ראוי לאכילה מבעוד יום, לכן אינו נחשב כמוכן והריהו מוקצה ואין לשחטו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בכור תם שנפל\u0004 ביום טוב \u0003לבור, ר' יהודה הנשיא אומר: ירד מומחה ויראה, אם יש בו מום\u0004 שודאי נפל בו מאתמול \u0003— יעלה וישחוט, ואם לאו\u0004 \u0005[לא],\u0006 אלא שנפל בו היום — אפילו העלהו, \u0003לא ישחוט. אמר לו ר' שמעון בן מנסיא: הרי\u0004 כבר \u0003אמרו\u0004 חכמים בדורות קודמים לנו ש\u0003אין רואין מומין ביום טוב. כיצד? נולד בו מום\u0004 בבכור \u0003מערב יום טוב, אין מבקרין\u0004 (בודקים) \u0003אותו ביום טוב\u0004 עצמו אם אמנם מום גמור הוא שמתירו לשחיטה. ואם \u0003נולד בו מום\u0004"],["\u0003ביום טוב\u0004 עצמו, \u0003ר' שמעון אומר: אין זה מן המוכן. ושוין\u0004 ר' יהודה ור' שמעון \u0003שאם נולד הוא ומומו עמו,\u0004 כלומר, שנולד הבכור בעל מום — \u0003שזה מן המוכן.\u0004","להלכה, \u0003דרש רבה בר רב הונא:\u0004 בכור אשר \u0003נולד הוא ומומו עמו\u0004 — \u0003מבקרין\u0004 (בודקים) \u0003אותו\u0004 מומחים \u0003ביום טוב לכתחלה\u0004 ואם נמצא שהוא מום קבוע שראוי לשחוט עליו — שוחטים ואוכלים אותו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: אבא תני\u0004 \u0005[אבי היה שונה]\u0006 בענין זה: \u0003אם עבר ובקרו — הריהו מבוקר\u0004 בדיעבד, \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 כי \u0003מבקרין אותו לכתחלה!\u0004","\u0003אמר אביי: כותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003רבה בר רב הונא מסתברא\u0004 \u0005[מסתבר]\u0006 לפסוק להלכה, \u0003מדקתני תלתא בבי\u0004 \u0005[ממה ששנה\u0006 בברייתא \u0005שלושה חלקים],\u0006 אפשר ללמוד שלכל חלק יש דין מיוחד, ושם נאמר: \u0003נולד בו מום מערב יום טוב\u0004 — \u0003אין מבקרין אותו ביום טוב,\u0004 ומכאן נלמד: \u0003לכתחלה הוא דלא\u0004 \u0005[שאין\u0006 מבקרים] \u0003הא\u0004 \u0005[הרי]\u0006 ב\u0003דיעבד שפיר דמי\u0004 \u0005[יפה הדבר],\u0006 שאם בקרו — מבוקר.","\u0003נולד בו מום ביום טוב, ר' שמעון אומר: אין זה מן המוכן.\u0004 כלומר: ש\u0003אפילו דיעבד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא,\u0004 ואף אם ביקרוהו — אסור הוא באכילה. \u0003והדר תני\u0004 \u0005[וחזר ושנה]\u0006 \u0003ושוין\u0004 כולם בדעתם, \u0003שאם נולד\u0004 הוא \u0003ומומו עמו, שזה מן המוכן.\u0004 וכיון שנשנה דין זה כחלק לעצמו נלמד מכאן כי \u0003אפילו לכתחלה נמי\u0004 \u0005[גם כן]\u0006 בודקים אותו, ומותר.","ומקשים: \u0003והא כי אתא\u0004 \u0005[והרי כאשר בא]\u0006 \u0003רב אושעיא\u0004 מארץ ישראל \u0003אתא ואייתי מתניתא בידיה\u0004 \u0005[בא והביא משנה בידו]\u0006 שבה נאמר: \u0003בין שנולד בו מום מערב יום טוב, ובין שנולד בו מום ביום טוב\u0004 עצמו, \u0003חכמים אומרים: אין זה מן המוכן.\u0004","ושואלים: \u0003ואלא\u0004 אם כן \u0003קשיא הך\u0004 \u0005[קשה זו]\u0006 הברייתא ששנינו, שבה נאמר שזה מן המוכן! ומשיבים: אין זו קושיה, \u0003ההיא\u0004 \u0005[אותה\u0006 ברייתא\u0005]\u0006 — שיטת \u0003אדא בר אוכמי היא, דמשבש ותני\u0004 \u0005[שהוא היה\u0006 רגיל \u0005לשבש ולשנות]\u0006 ואין סומכים על הגירסה שמסר.","\u0003אמר רב נחמן בר יצחק: מתניתין נמי דייקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 כשיטה זו שאין מבקרים כל מום לכתחילה. \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בה\u0005],\u0006 \u0003ר' שמעון אומר: כל שאין מומו ניכר מערב יום טוב — אין זה מן המוכן. מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אין מומו ניכר? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003שאין מומו ניכר כלל\u0004 — הרי \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 \u0003צריכא למימר\u0004 \u0005[\u0006וכי \u0005צריך לומר]\u0006 דבר כזה שאם אין מומו ניכר כלל אינו נחשב מן המוכן?","\u0003אלא\u0004 על כרחך יש לומר שהיה בו מום, ומדובר כאן באופן \u0003דלא אתחזי\u0004 \u0005[שלא נראה]\u0006 \u0003לחכם מערב יום טוב אם מום קבוע אם מום עובר. קתני מיהת\u0004 \u0005[שנינו על כל פנים]\u0006 \u0003אין זה מן המוכן\u0004 משמע שבו ביום אין זה מן המוכן כלל. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006 שכן הוא\u0005].\u0006","אגב הדיון בהלכה זו דנים בנושא דומה. \u0003בעי מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003הלל\u0004 את \u0003רבא: יש מוקצה לחצי שבת או אין מוקצה לחצי שבת?\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה הדבר]?\u0006 \u0003אי דאחזי\u0004 \u0005[אם היה ראוי]\u0006 \u0003בין השמשות\u0004 שבין יום שישי לשבת לאכילה או לשימוש אחר — אם כן \u0003אחזי\u0004 \u0005[ראוי\u0006 הוא\u0005]\u0006 לכל השבת. \u0003אי דלא אחזי\u0004 \u0005[אם שלא היה ראוי]\u0006 בין השמשות — אם כן \u0003לא אחזי\u0004 \u0005[אינו ראוי]\u0006 כל היום, שהרי בין השמשות היה מוקצה ואין זו עוד הכנה, ואם כן איך יכול להיות במציאות מוקצה לחצי שבת?","ומסבירים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא כגון \u0003דאחזי\u0004 \u0005[שהיה ראוי]\u0006 \u0003והדר אדחי\u0004 \u0005[וחזר\u0006 ו\u0005נדחה]\u0006 בתוך השבת מפני איזה טעם, \u0003והדר אחזי\u0004 \u0005[וחזר\u0006 ו\u0005נהיה ראוי],\u0006 ובענין זה שאל \u0003מאי\u0004 \u0005[מה\u0006 דינו\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003יש מוקצה\u0004 לחצי השבת.","\u0003איתיביה\u0004 \u0005[הקשה לו]:\u0006 \u0003ושוין שאם נולד\u0004 הוא \u0003ומומו עמו\u0004 — \u0003שזה מן המוכן. ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003נימא\u0004 \u0005[נאמר]\u0006 כן: \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003בכור\u0004 הלא \u0003מעיקרא הוה חזי אגב אמיה\u0004 \u0005[מתחילתו היה ראוי\u0006 לאכילה \u0005אגב אמו]\u0006 שאם היו שוחטים את אמו בעוד הבכור בבטנה מותר היה לאכול את שניהם, ואם כן כאשר \u0003אתיליד ליה\u0004 \u0005[הוא נולד]\u0006 — \u0003אדחי ליה\u0004 \u0005[הריהו נדחה]\u0006 מהיתרו זה, שכיון שנולד שוב אינו ראוי לאכילה עד שיתברר אם יש בו מום, ולאחר מכן כאשר \u0003אחזייה\u0004 \u0005[הראהו]\u0006 \u0003לחכם\u0004 — \u0003אשתרי ליה\u0004 \u0005[\u0006הרי \u0005הותר לו].\u0006 ואם כן, אף שבמשך זמן מסויים בתוך החג היה כמוקצה — אינו מוקצה לכל השבת!","\u0003אמר אביי ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב ספרא:\u0004 כאן מדובר \u0003כגון דיתבי דייני התם\u0004 \u0005[שיושבים דיינים שם]\u0006 ורואים בשעת לידת הבכור, ומיד כשנולד ראו שהוא בעל מום. ואם כן נמצא שלא היה אפילו רגע אחד שבו נדחה מהיתרו הראשון.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 להיפך, ש\u0003אמר\u0004 לו רבא: \u0003אין מוקצה לחצי שבת.\u0004 ואומרים: \u0003לימא מסייע ליה\u0004 \u0005[האם לומר\u0006 שאפשר \u0005לסייע לו]\u0006 ממה ששנינו: \u0003ושוין שאם נולד\u0004 הוא \u0003ומומו עמו\u0004 — \u0003שזה מן המוכן. והא בכור מעיקרא הוה חזי אגב אמיה\u0004 \u0005[והרי בכור מתחילה היה ראוי אגב אמו]\u0006 וכאשר \u0003אתיליד ליה\u0004 \u0005[הוא נולד]\u0006 — \u0003אדחי ליה\u0004 \u0005[נדחה לו]\u0006 ולאחר מכן, כאשר \u0003אחזייה\u0004 \u0005[הראהו]\u0006 \u0003לחכם\u0004 — \u0003אשתרי ליה\u0004 \u0005[הותר לו]\u0006 הרי שאין מוקצה לחצי שבת.","\u0003אמר אביי ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב ספרא:\u0004 אין זו ראיה גמורה, שאפשר לומר \u0003כגון דיתבי דייני התם\u0004 \u0005[שיושבים דיינים שם]\u0006 בשעת לידתו וראו את מומו ולכן לא היה מוקצה כלל.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממקור אחר, ששנינו: \u0003היה\u0004 אדם \u0003אוכל בענבים והותיר\u0004 מאכילתו \u0003והעלן לגג\u0004 את הענבים הנותרים לייבשן כדי \u0003לעשות מהן צמוקין,\u0004 או היה אוכל \u0003בתאנים והותיר והעלן לגג\u0004 לייבשן כדי \u0003לעשות מהן גרוגרות\u0004 (תאנים מיובשות) — \u0003לא יאכל מהן\u0004 בשבת מאותן ענבים וגרוגרות \u0003עד שיזמין\u0004 אותן \u0003מבעוד יום\u0004 לאכילתו. \u0003וכן אתה מוצא באפרסקין ובחבושין ובשאר מיני פירות\u0004 שהניחם לייבש והסיח דעתו מהם.","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה הדבר]?\u0006 \u0003אי דחזו\u0004 \u0005[שראויים הם]\u0006 לאכילה, שכבר התייבשו, אם כן \u0003למה ליה הזמנה\u0004 \u0005[לשם מה להזמין אותם]\u0006 מבעוד יום? הרי על דעת כן הניחם שם, שלכשייתייבשו יאכלם והרי הם כמזומנים כבר. \u0003אי דלא חזו\u0004 \u0005[אם שאינם ראויים]\u0006 לאכילה, שעדיין לא התייבשו — אם כן \u0003כי אזמין להו מאי הוי\u0004 \u0005[כאשר הזמין אותם\u0006 מבעוד יום \u0005מה היה\u0006 על ידי כך\u0005],\u0006 מה הועילה לו הזמנה זו, הלא אינם ראויים!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שמדובר באופן שאינו יכול לעלות על הגג כדי לבודקם, ש\u0003לא ידע אי חזו אי לא חזו\u0004 \u0005[אם ראויים\u0006 הם \u0005אם אינם ראויים]\u0006 והזמנתו היא על תנאי שאכן מוכנים הם, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב כהנא: מוקצה שיבש,\u0004 כלומר: שהגיע לידי יבוש וראוי לאכילה \u0003ואין הבעלים מכירין בו\u0004 שיבש מבעוד יום, אלא למחרת, בשבת, התברר להם שכבר היה יבש מבעוד יום — הרי זה \u0003מותר,\u0004 שהרי לא הקצו מדעתם אלא לזמן שלא יהיה ראוי לאכילה.","\u0003אלא לאו דחזו ואדחו והדר אחזו\u0004 \u0005[האם לא\u0006 מדובר \u0005שהיו ראויים ונדחו וחזרו ונעשו ראויים]\u0006 ועל כן דינם כמוקצה. \u0003ואי אמרת\u0004 \u0005[ואם אתה אומר]\u0006 ש\u0003אין מוקצה\u0004 לחצי שבת, \u0003למה להו\u0004 \u0005[להם]\u0006 \u0003הזמנה?\u0004 ודוחים: \u0003אלא מאי\u0004 \u0005[מה\u0006 אומר אתה\u0005]\u0006 \u0003יש מוקצה\u0004 לחצי שבת? אם כן, \u0003כי אזמין להו מאי הוי\u0004 \u0005[כאשר הוא מזמין להם מה יהיה\u0006 על ידי כך\u0005]\u0006 הרי אין בכך כדי להתיר את המוקצה!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דאחזו ולא אחזו\u0004 \u0005[שהם ראויים ואינם ראויים\u0006 לגמרי\u0005]\u0006 \u0003דאיכא אינשי דאכלי ואיכא אינשי דלא אכלי\u0004 \u0005[שיש אנשים שאוכלים ויש אנשים שאינם אוכלים]\u0006 בהיותם במצב זה. ואז, אם \u0003אזמין\u0004 \u0005[הזמין]\u0006 הרי \u0003גלי דעתיה\u0004 \u0005[גלה דעתו]\u0006 שהוא מאלה שאוכלים אותם, \u0003לא אזמין\u0004 \u0005[הזמין]\u0006 \u0003— לא גלי דעתיה\u0004 \u0005[גלה דעתו]\u0006 ואם כן אין להוכיח מכאן.","\u0003אמר ר' זירא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לפתור את השאלה שלנו \u0003מפולין ועדשים\u0004 שמבשלים בחג. \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003פולין ועדשים מעיקרא\u0004 \u0005[בתחילה]\u0006 בשעת בין השמשות, בהיותם חיים, בלתי מבושלים, \u0003חזו לכוס\u0004 \u0005[ראויים\u0006 \u0005היו לכסוס אותם]\u0006 ללעוס אותם כפי שהם, ולכן לא היו מוקצים, וכאשר \u0003שדינהו\u0004 \u0005[הטילם]\u0006 \u0003ב\u0004תוך ה\u0003קדרה\u0004 לבשלם \u0003— אדחו להו\u0004 \u0005[נדחו להם]\u0006 שהרי בשעת הבישול אינם ראויים לא לכסיסה ולא לאכילה כמבושלים,"],["וכאשר \u0003גמר בשולייהו\u0004 \u0005[נגמר בישולם]\u0006 \u0003חזו להו\u0004 \u0005[ראויים הם],\u0006 ואם כן, אף שהיו במשך זמן מסויים מוקצות לאכילה — אינן נאסרות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שדברים בתוך כדי בישולם נדונים כמוקצה לפי שעה, אם כן \u0003תקשי לך\u0004 \u0005[יקשה לך]\u0006 מה \u0003קדרות דעלמא\u0004 \u0005[\u0006שמבשלים \u0005בכלל],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003סתם קדרות דעלמא\u0004 \u0005[בכלל]\u0006 בשעת \u0003בין השמשות רותחות הן\u0004 ואינן ראויות עדיין לאכילה, \u0003ולאורתא אכלינן מינייהו\u0004 \u0005[ולערב אוכלים אנו מהן]\u0006 ואם כן, אף שהיו בגדר מוקצה בשעה הקובעת (בין השמשות) מכל מקום ודאי לא נאסרו לשבת!","\u0003אלא\u0004 ודאי יש לומר כי כל דבר שתהליך עשייתו עד \u0003גמרו\u0004 (סוף התהליך) נעשה \u0003בידי אדם לא קא מבעיא לן\u0004 \u0005[אינו מסופק לנו]\u0006 שאין לומר עליו שנדחה, והוא הדין לענין הפולים והעדשים. \u0003כי קא מבעיא לן\u0004 \u0005[כאשר נסתפק לנו]\u0006 היה זה בדבר ש\u0003גמרו בידי שמים\u0004 וכגון בתאנים וענבים שמתייבשים בחום השמש, ובעיה זו לא נפתרה.","ולגוף ענין התרת בכורות חוזרים אנו ודנים. \u0003ר' יהודה נשיאה הוה ליה ההוא בוכרא\u0004 \u0005[היה לו בכור אחד]\u0006 שנפל בו מום ביום טוב, ורצה להאכילו לכהנים שהיו בביתו. \u0003שדריה לקמיה\u0004 \u0005[שלח אותו לפני]\u0006 \u0003ר' אמי\u0004 לבדקו, \u0003סבר דלא למחזייה\u0004 \u0005[חשב שלא לראות אותו]\u0006 כדעת ר' שמעון. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זריקא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר לו זאת \u0003ר' ירמיה:\u0004 הלא כלל בידינו שכאשר נחלקו \u0003ר' יהודה ור' שמעון\u0004 — \u0003הלכה כר' יהודה,\u0004 שהתיר לבקרו. \u0003הדר שדריה\u0004 \u0005[חזר ושלחו]\u0006 לבכור להבדק \u0003לקמיה \u0004 \u0005[לפני]\u0006 \u0003ר' יצחק נפחא, סבר דלא למחזייה\u0004 \u0005[חשב שלא לראות אותו]\u0006 ביום טוב, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר לו זאת \u0003ר' זריקא:\u0004 כלל הוא בידינו שכאשר נחלקו \u0003ר' יהודה ור' שמעון — הלכה כר' יהודה. אמר ליה\u0004","\u0005[לו]\u0006 \u0003ר' אבא\u0004 לר' ירמיה: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא שבקתינהו לרבנן למעבד עובדא\u0004 \u0005[הנחת לחכמים לעשות מעשה]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ואת מה בידך?\u0004 כלומר האם יש בידך מסורת שהלכה כר' שמעון? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' זירא: הלכה כר' שמעון\u0004 בענין זה.","מסופר: \u0003אמר מאן דהוא\u0004 \u0005[מי שהוא]\u0006 אדם אחד שלא נתברר לנו שמו, שהיה בבבל: \u0003אזכי ואסק להתם, ואגמרה לשמעתא מפומיה דמרה\u0004 \u0005[\u0006יהי רצון ש\u0005אזכה ואעלה לשם,\u0006 לארץ ישראל, \u0005ואלמד שמועה\u0006 זו \u0005מפי בעליה].\u0006 כלומר: אשאל את ר' זירא עצמו מה דעתו בענין זה. \u0003כי סליק להתם אשכחיה\u0004 \u0005[כאשר עלה לשם,\u0006 לארץ, \u0005מצא]\u0006 את \u0003ר' זירא, אמר ליה\u0004 \u0005[לו] :\u0006 האם \u0003אמר מר\u0004 \u0005[אדוני]\u0006 כי \u0003הלכה כר' שמעון? אמר ליה\u0004 \u0005[לו] :\u0006 \u0003לא,\u0004 לא כך אמרתי, אלא \u0003אנא \"מסתברא\" אמרי\u0004 \u0005[אני \"מסתבר\" אמרתי],\u0006 כלומר: מסתבר לפסוק בכך כר' שמעון, אבל לא שמעתי לפסוק כך כהלכה גמורה.","ומדוע סבור אני כן — \u0003מדקתני במתניתין\u0004 \u0005[ממה ששנינו במשנתנו]\u0006 ש\u0003ר' שמעון אומר: כל שאין מומו ניכר מבעוד יום\u0004 — \u0003אין זה מן המוכן. וקתני לה\u0004 \u0005[ושנה אותה]\u0006 \u0003בברייתא\u0004 אותו דבר \u0003בלשון חכמים\u0004 — \u0003שמע מינה מסתברא כוותיה\u0004 \u0005[למד מכאן\u0006 כי \u0005מסתבר כמותו]\u0006 ולכן פסק החכם בברייתא הלכה כמותו.","ושואלים: ובסופו של דבר \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]\u0006 על הלכה זו, כשיטת מי פוסקים? \u0003אמר רב יוסף: תא שמע, דתליא באשלי רברבי\u0004 \u0005[בוא\u0006 ו\u0005שמע ש\u0006דבר זה \u0005תלוי באילנות גדולים]\u0006 ובמחלוקת של דורות ראשונים. ש\u0003אמר ר' שמעון בן פזי אמר ר' יהושע בן לוי אמר ר' יוסי בן שאול אמר רבי משום קהלא קדישא\u0004 \u0005[בשם הקהל הקדוש]\u0006 ש\u0003בירושלים: ר' שמעון וחבריו אמרו\u0004 ש\u0003הלכה כר' מאיר.\u0004","ומיד תוהים על לשון זו כיצד \u0003אמרו? והא אינהו קשישי מניה טובא\u0004 \u0005[והרי הם זקנים ממנו הרבה]!\u0006 וכיצד יתכן שהקהל הקדוש שבירושלים יאמרו שהלכה ר' מאיר? \u0003אלא\u0004 יש לתקן את הלשון ולומר כי כך אמרו הקהל הקדוש של ירושלים: ר' שמעון בן מנסיא וחבריו שאמרו שאין רואים מומים — \u0003בשיטת ר' מאיר אמרוה.\u0004","ומה עניינה — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 במסכת בכורות (כח, א): \u0003השוחט את הבכור\u0004 לפני שהראהו לחכם והתירו \u0003ואחר כך הראה את מומו\u0004 לחכם, והסכים החכם שהיה זה אכן מום קבוע המתירו בשחיטה — \u0003ר' יהודה מתיר,\u0004 שהרי נתברר שהיה בו מום. \u0003ור' מאיר אומר: הואיל ונשחט שלא על פי מומחה\u0004 — \u0003אסור. אלמא קסבר\u0004 \u0005[מכאן שסבר]\u0006 \u0003ר' מאיר\u0004 כי \u0003ראיית בכור לאו\u0004 \u0005[אינה]\u0006 קלה \u0003כראיית טרפה\u0004 ואיננה רק בדיקה של גוף הבהמה, שכן, \u0003ראיית בכור\u0004 — דווקא \u0003מחיים\u0004 כאשר הבכור חי, ואילו \u0003ראיית טרפה\u0004 יכולה שתיעשה אף \u0003לאחר שחיטה.\u0004","\u0003ומינה\u0004 \u0005[וממנה]\u0006 הסיקו ר' שמעון בן מנסיא וחבריו, כי \u0003ראיית טרפה\u0004 שאין בה אלא לדעת את נתוני הבהמה — רואים אותה \u0003אפילו ביום טוב,\u0004 אולם \u0003ראיית בכור\u0004 שהיא חמורה ועצם הראייה היא כעשיית דין מיוחד שיש לו כללים לעצמו — \u0003מערב יום טוב\u0004 בלבד, שעצם הראייה היא כמתן פסק דין מיוחד, שיש לו כללים לעצמו ואינו רק לצורך ידיעת הנתונים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003אטו התם\u0004 \u0005[וכי שם]\u0006 באותה משנה, בשאלה אם \u0003רואין מומין פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005]\u0006 ר' יהודה ור' מאיר? הלא בכך לא נחלקו, אלא \u0003בקנסא פליגי\u0004 \u0005[ב\u0006ענין \u0005הקנס חלוקים\u0006 הם\u0005]\u0006 והשאלה היתה האם יש לקנוס אדם על שעשה מעשה שלא לפי הנוהג הראוי. ש\u0003אמר רבה בר בר חנה אמר ר' יוחנן:\u0004 אם היה המום \u0003בדוקין שבעין\u0004 \u0005[בעפעפי העין]\u0006 כגון שנעשה בהם סדק הפוסל אותן — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים],\u0006 אף ר' מאיר, ש\u0003אסור, משום\u0004 ש\u0003משתנין\u0004 לאחר השחיטה כשכבר אין הבהמה בחיים, ויתכן שמום עובר ייראה בה כמום קבוע ואף שבאמת אין להתירו, ייראה הוא כמותר.","\u0003כי פליגי\u0004 \u0005[כאשר חלקו]\u0006 הרי זה \u0003במומין שבגוף,\u0004 וכגון שנקצצה אזנו או נשברה ידו, שהם מומים בולטים ואין מראה המום משתנה לאחר המוות, ש\u0003ר' מאיר סבר: גזרינן\u0004 \u0005[גוזרים אנו]\u0006 \u0003מומין שבגוף אטו\u0004 \u0005[משום]\u0006 \u0003מומין שבעין. ור' יהודה סבר: לא גזרינן\u0004 \u0005[אין אנו גוזרים].\u0006","\u0003אמר רב נחמן בר יצחק: מתניתין נמי דיקא\u0004 \u0005[\u0006לשון \u0005המשנה\u0006 במסכת בכורות \u0005גם כן מדוייקת]\u0006 כהסבר זה, \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בה\u0005]:\u0006 \u0003ר' מאיר אומר: הואיל ונשחט שלא על פי\u0004 הוראת \u0003מומחה\u0004 שזהו מום קבוע — \u0003אסור. שמע מינה: קנסא הוא דקא קניס\u0004 \u0005[למד מכאן\u0006 ש\u0005קנס הוא שהוא קונס]\u0006 ולא מטעם אחר, ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","מסופר: \u0003אמי ורדינאה\u0004 \u0005[\u0006מהמקום \u0005וורדינא]\u0006 \u0003חזי בוכרא דבי נשיאה הוה \u0004 \u0005[רואה הבכורות של בית הנשיא היה\u0006\u0005].\u0006 \u0003ביומא טבא לא הוי חזי\u0004 \u0005[ביום טוב לא היה רואה]\u0006 מומי הבכורות. \u0003אתו ואמרו ליה\u0004 \u0005[באו ואמרו לו]\u0006 \u0003לר' אמי. אמר להו\u0004 \u0005[להם]:\u0006 \u0003שפיר קא עביד דלא חזי\u0004 \u0005[יפה הוא עושה שאינו רואה].\u0006 ומקשים: \u0003איני\u0004 \u0005[וכי כן הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' אמי גופיה\u0004 \u0005[עצמו]\u0006 \u0003חזי\u0004 \u0005[היה רואה]!\u0006 ומשיבים: \u0003ור' אמי כי חזי\u0004 \u0005[כאשר היה רואה]\u0006 — \u0003מאתמול,\u0004 מערב יום טוב \u0003הוה חזי\u0004 \u0005[היה רואה]\u0006 מה טיבו של המום, האם הוא קבוע או עובר,"],["\u0003וביום טוב\u0004 עצמו \u0003שיולי קא משייל היכי הוה עובדא\u0004 \u0005[היה שואל כיצד היה מעשה]\u0006 והיה חוקר ודורש כציד נעשה בו מום זה. \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 \u0003דההוא גברא\u0004 \u0005[שאדם אחד]\u0006 שכהן היה \u0003דאייתי בוכרא לקמיה\u0004 \u0005[שהביא בכור לפני]\u0006 \u0003רבא, אפניא דמעלי יומא טבא\u0004 \u0005[\u0006סמוך \u0005לערב יום טוב]\u0006 \u0003הוה יתיב\u0004 \u0005[היה יושב]\u0006 \u0003רבא וקא חייף רישיה\u0004 \u0005[וחופף את ראשו].\u0006 \u0003דלי עיניה וחזייה למומיה\u0004 \u0005[הרים את עיניו וראה את מומו\u0006 של הבכור\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לאותו כהן בעל הבכור: \u0003זיל האידנא ותא\u0004 \u0005[לך עכשיו ובוא]\u0006 \u0003למחר.\u0004","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003למחר, אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003היכי הוה עובדא\u0004 \u0005[כיצד היה\u0006 ה\u0005מעשה]\u0006 שנפל בו מום? \u0003אמר ליה\u0004 \u0005[לו]\u0006 בעל הבכור לרבא: \u0003הוה שדיין שערי בהך גיסא דהוצא, והוה איהו באידך גיסא\u0004 \u0005[היו מושלכות שעורים מצד האחד של גדר קוצים והיה הוא\u0006 הבכור \u0005בצד האחר]\u0006 \u0003בהדי דבעי למיכל\u0004 \u0005[כאשר רצה לאכול]\u0006 \u0003— עייל רישיה ופרטיה הוצא לשפותיה\u0004 \u0005[הכניס את ראשו דרך הגדר וחתך הקוץ את שפתיו]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לבעל הבכור: \u0003דלמא את גרמת ליה\u0004 \u0005[שמא אתה גרמת לו],\u0006 שהנחת בכוונה את השעורים מעבר לגדר? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא.\u0004","ומעירים: \u0003ומנא תימרא דגרמא\u0004 \u0005[ומנין אתה אומר שלגרום\u0006 מום\u0005]\u0006 \u0003אסור — דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר בקרבנות: \u0003\"\u0004כל \u0003מום לא יהיה בו\"\u0004 (ויקרא כב, כא), \u0003אין לי\u0004 איסור מפורש \u0003אלא שלא יהיה בו מום, מניין שלא יגרום לו על ידי דבר אחר,\u0004 כגון \u0003שלא יביא בצק או דבלה ויניח לו על גבי האזן כדי שיבא הכלב ויטלנו\u0004 וינשוך חלק מאזנו ועל ידי כך יפול בו מום — \u0003תלמוד לומר: \"כל מום\"\u0004 (ויקרא כב, כא). \u0003אמר \"מום\" ואמר \"כל מום\"\u0004 והמלה \"כל\" באה לרבות אפילו גרימת מום.","\u0003בהמה שמתה\u0004 — \u0003לא יזיזנה ממקומה\u0004 ביום טוב. \u0003ומעשה ושאלו את ר' טרפון עליה\u0004 וכן \u0003על\u0004 מעשה שהיה ב\u0003חלה\u0004 שהפרישו מן העיסה \u0003שנטמאת,\u0004 ואינה ראויה איפוא לאכילה לשום אדם ואף לא להנאה אחרת (כגון, להאכיל בה את בהמתו, או או להשתמש בה כחומר הסקה) בו ביום, \u0003ונכנס לבית המדרש ושאל, ואמרו לו: לא יזיזם ממקומם.\u0004","מציעים: \u0003לימא תנן סתמא\u0004 \u0005[האם לומר ששנינו\u0006 במשנה \u0005סתם]\u0006 שהיא \u0003לא כ\u0004שיטת \u0003ר' שמעון? דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון אומר: מחתכין את הדלועין\u0004 בשבת \u0003לפני הבהמה,\u0004 שתוכל לאוכלם בקלות, וכן מחתכים \u0003את הנבלה לפני הכלבים. ר' יהודה אומר: אם לא היתה נבלה מערב שבת\u0004 אלא מתה בשבת עצמה — \u0003אסורה.\u0004 ומתוך שחילק ר' יהודה בין מתה בשבת או לפניה, משמע שלדעת ר' שמעון אף אם מתה בשבת מותר להזיזה ואף לחותכה לפני הכלבים, ואם כן משנתנו שאסרה להזיז את הבהמה שמתה ממקומה — הרי זה בניגוד לדעת ר' שמעון!","ומשיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כי משנתנו כשיטת \u0003ר' שמעון,\u0004 מכל מקום \u0003מודה ר' שמעון בבעלי חיים\u0004 שהיו בריאים לחלוטין בשעת בין השמשות \u0003שמתו\u0004 ביום טוב \u0003שאסורין,\u0004 שמתוך שהן בריאות בשעת בין השמשות — אין דעתו עליהם באותה שעה להאכילם לכלבים ולכן הם מוקצה. ומה שאמר בברייתא — בבהמה שהיתה מסוכנת עוד מאתמול דיבר, וכיון שיודע שקרובה היא למות, הריהו חושב עליה ומזמינה להאכלת כלביו.","ושואלים: \u0003הניחא\u0004 \u0005[\u0006דבר \u0005זה נוח]\u0006 \u0003ל\u0004שיטת \u0003מר בר אמימר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא,\u0004 ש\u0003אמר: מודה היה ר' שמעון בבעלי חיים שמתו\u0004 ביום טוב עצמו ולא היו מסוכנים מבעוד יום \u0003שאסורין,\u0004 ואם כן לשיטתו \u0003שפיר\u0004 \u0005[יפה].\u0006 \u0003אלא ל\u0004דעת \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא\u0004 ש\u0003אמר: חלוק היה ר' שמעון אפילו בבעלי חיים שמתו\u0004 פתאום, והוא סבור \u0003שמותרים,\u0004 אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שנמצא סתם משנתנו בניגוד לשיטתו!","ומשיבים: \u0003תרגומה\u0004 \u0005[הסביר אותה\u0006 החכם\u0005]\u0006 \u0003זעירי,\u0004 שמדובר כאן \u0003בבהמת קדשים\u0004 שמתה, שכיון שהיא של קדשים, הריהי אסורה בהנאה, ואסור לתתה לכלבים. ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 שכך הפירוש. \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003עליה ועל החלה שנטמאת,\u0004 מתוך הקשר הדברים אפשר ללמוד: \u0003מה חלה — דקדישא\u0004 \u0005[ש\u0006היא \u0005קדושה],\u0006 \u0003אף בהמה\u0004 מדובר פה \u0003דקדישא\u0004 \u0005[ש\u0006היא \u0005מוקדשת]\u0006 ולא בבהמה של חולין.","ושואלים: לפי פירוש זה, \u0003אלא טעמא דקדישא\u0004 \u0005[הטעם\u0006 דווקא \u0005שהיא קדושה]\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 אם היתה זו בהמה של \u0003חולין\u0004 היתה מותרת בטלטול, אם כן \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא\u0004 ש\u0003אמר: חלוק היה ר' שמעון אף בבעלי חיים שמתו שמותרין,\u0004 ולשיטתו \u0003שפיר\u0004 \u0005[יפה],\u0006 שהרי אפשר לומר שמשנתנו, ממנה משמע כי מותר לטלטל את הבהמה שמתה ביום טוב, כשיטת ר' שמעון היא. \u0003אלא ל\u0004שיטת \u0003מר בר אמימר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא\u0004 ש\u0003אמר: מודה היה ר' שמעון בבעלי חיים שמתו שאסורין,\u0004 אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שכן אינה לא כשיטתו ולא כשיטת ר' יהודה!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה עוסקים אנו];\u0006 שהיתה בהמה זו \u0003מסוכנת\u0004 מבעוד יום, והיתה איפוא דעתו עליה שתמות \u0003ודברי הכל.\u0004 ולכך לשיטת ר' שמעון יש להתיר במסוכנת בחולין, ובבהמת קדשים יש אף לדעתו לאסור משום שאינו יכול להאכילה לכלבים.","\u0003אין נמנין על הבהמה לכתחלה ביום טוב\u0004 שאין מחלקים את הבהמה למנות ולאנשים שונים שהוא כדרך מסחר הנעשה בחול. \u0003אבל נמנין עליה מערב יום טוב, ושוחטין ומחלקין ביניהם\u0004 ביום טוב כפי שסיכמו ביניהם מבעוד יום ולמחרת ישלמו לשוחט כל אחד לפי חלקו.","שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אין נמנין? אמר רב יהודה אמר שמואל: אין פוסקין דמים\u0004 לקצוב סכום ותשלום קבוע לכל מנה \u0003לכתחלה על הבהמה ביום טוב.\u0004 ושואלים: \u0003היכי עביד\u0004 \u0005[כיצד הוא עושה]\u0006 ביום טוב, וכיצד יכול לחלק בלי לקצוב את הדמים? \u0003אמר רב: מביא שתי בהמות ומעמידן זו אצל זו, ואומר\u0004 להם כשאלה: האם \u0003זו\u0004 שוויה \u0003כזו?\u0004 וכאשר הקונים מאשרים את הדבר ומסכימים, יעריכו לאחר החג את הבהמה הזהה לה, ולפיה יקבעו כמה צריכים הם לשלם.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003לא יאמר אדם לחברו\u0004 ביום טוב: \u0003הריני עמך\u0004 שותף לך בבהמה שאתה שוחט \u0003בסלע\u0004 (בשווי של סלע), או \u0003הריני עמך בשתים, אבל אומר לו: הריני עמך למחצה\u0004 מן הבהמה \u0003לשליש ולרביע\u0004 מבלי לקצוב את שוויו של אותו חלק, ולאחר החג קובעים כמה אותו חלק שוה."],["\u0003ר' יהודה אומר: שוקל אדם בשר,\u0004 שהמוכר בשר ביום טוב ורוצה לדעת מהו משקלו כדי לקבוע את מחירו, אינו עושה כן כנגד אבני משקל, כמעשהו בחול, אלא שוקלו \u0003כנגד הכלי או כנגד הקופיץ\u0004 (סכין גדול המיועד לחיתוך בשר) ואחר כך ישקול את הכלי או את הקופיץ ועל פי זה יתברר משקל הבשר. \u0003וחכמים אומרים: אין משגיחין בכף מאזנים כל עיקר,\u0004 כלומר: לא לשקילה ולא לשימוש אחר.","שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \"אין משגיחין \u0003כל עיקר\"? אמר רב יהודה אמר שמואל: אפילו\u0004 כשיש בשר שרוצים \u0003לשמרו מן העכברין\u0004 אין מכניסים אותו בכף מאזנים, מפני שנראה כשוקל. \u0003אמר רב אידי בר אבין: והוא דתליא בתריטא\u0004 \u0005[שתלויה\u0006 כף המאזנים \u0005בתוך הטבעת]\u0006 העשויה למשקל, אבל אם תלויה כף המאזנים לא באופן הראוי לשקילה — מותר להשתמש בה כבכל כלי אחר.","\u0003ואמר רב יהודה אמר שמואל: טבח אומן אסור לשקול בשר ביד\u0004 להעריך כמה משקלו, משום שהאומן יכול לדייק בשקילה כזו, והדבר אסור כשקילה בכלי. \u0003ו\u0004כן \u0003אמר רב יהודה אמר שמואל: טבח אומן אסור לשקול בשר במים,\u0004 שהיו קצבים שהיו קובעים את משקל הבשר באמצעות כלי המכיל מים שהיו בכתליו סימנים הקבועים מעל גובה פני המים, כשכל סימן מורה על משקל מסויים. וכאשר הכניסו את הבשר לאותו כלי, היו פני המים עולים עד לגובה אחד הסימנים, ועל פי זה היו יודעים את משקלו המדוייק. ומאחר ויש בפעולה זו כדי לקבוע מידה מדוייקת — אסור לעשות כן ביום טוב.","\u0003ואמר רב חייא בר אשי: אסור לעשות בית יד בבשר,\u0004 כלומר: אסור לעשות נקב בבשר כדי ליצור בו מקום אחיזה, משום שהוא כמעשה חול. \u0003אמר רבינא: ו\u0004לעשות את הנקב הזה \u0003בידא\u0004 \u0005[ביד]\u0006 ולא בסכין או בשאר כלים — \u0003שרי\u0004 \u0005[מותר],\u0006 שהרי זו דרך שינוי.","\u0003אמר רב הונא: מותר\u0004 לאדם \u0003לעשות סימן בבשר\u0004 כדי שלא יתחלף עם של אחר אפילו ביום טוב, אם זקוק הוא לכך, \u0003כי הא\u0004 \u0005[כמו זה]\u0006 שהיה עושה \u0003רבה בר רב הונא,\u0004 שכשהיה שולח בשר לביתו, היה \u0003מחתך לה אתלת קרנתא\u0004 \u0005[חותך אותו במשולשים]\u0006 לסימן שבשר זה שלו הוא, וכשר.","לגוף הענין מספרים: \u0003ר' חייא ור' שמעון ברבי\u0004 היו \u0003שוקלין מנה כנגד מנה ביום טוב,\u0004 כדי לחלק את הבשר ביניהם. ושואלים: \u0003כמאן\u0004 \u0005[\u0006כדעת \u0005מי]\u0006 עשו? \u0003לא כ\u0004שיטת \u0003ר' יהודה ולא כרבנן\u0004 \u0005[כ\u0006שיטת \u0005חכמים]\u0006 אשר הובאו במשנתנו! \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה — האמר\u0004 \u0005[הרי אמר]\u0006 \u0003שוקל אדם בשר כנגד הכלי או כנגד הקופיץ,\u0004 ומכאן נדייק: \u0003כנגד הכלי — אין\u0004 \u0005[כן]\u0006 \u0003כנגד מידי אחרינא\u0004 \u0005[כנגד דבר אחר]\u0006 \u0003— לא! אי כרבנן\u0004 \u0005[אם כ\u0006שיטת \u0005חכמים]\u0006 — \u0003הא אמרי\u0004 \u0005[הרי אמרו]\u0006 \u0003אין משגיחין בכף מאזנים כל עיקר!\u0004","ומסבירים: \u0003אינהו דעבוד\u0004 \u0005[הם,\u0006 ר' חייא ור' שמעון ברבי, \u0005שעשו]\u0006 מה שעשו כדעת \u0003ר' יהושע. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהושע אומר: שוקלין מנה כנגד מנה ביום טוב. אמר רב יוסף: הלכה כר' יהושע, הואיל ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]\u0006 \u0003בבכורות כותיה\u0004 \u0005[כשיטתו].\u0006","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 שם\u0005]:\u0006 \u0003פסולי המוקדשין\u0004 (קדשים שנפל בהם מום) — \u0003הנאתן להקדש,\u0004 כלומר: כל הנאה הבאה כתוצאה ממכירתם, שייכת להקדש, \u0003ושוקלין מנה כנגד מנה בבכור\u0004 שנפל בו מום. שאף שאסור למכור אותו במשקל וכדרך בשר חולין, מכל מקום מותר לשקול מנה כנגד מנה כדי להעריך את מחירו. משמע שאף במקום שאסרו לשקול כרגיל, מותר לשקול מנה כנגד מנה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: דלמא לא היא\u0004 \u0005[שמא אינה כן]\u0006 ואין הדברים דומים, כי \u0003עד כאן לא\u0004 שמענו ש\u0003אמר ר' יהושע הכא\u0004 \u0005[כאן]\u0006 ביום טוב להתיר את חלוקת הבשר באופן של מנה כנגד מנה, \u0003אלא\u0004 באופן \u0003דליכא\u0004 \u0005[שאין]\u0006 במעשה זה משום \u0003בזיון קדשים, אבל התם דאיכא\u0004 \u0005[שם,\u0006 בבכור, \u0005שיש]\u0006 \u0003בזיון קדשים\u0004 בשקילתו, שמא לכן לא התיר כל שקילה.","וכן: \u0003אי נמי\u0004 \u0005[או גם כן],\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי רבנן התם\u0004 \u0005[אמרו חכמים שם]\u0006 להתיר כן בבכור \u0003אלא משום דלא מחזי כעובדין\u0004 \u0005[שאינו נראה כמעשה]\u0006 של \u0003חול, אבל הכא דמחזי כעובדין\u0004 \u0005[כאן שנראה כמעשים]\u0006 של \u0003חול\u0004 — \u0003לא,\u0004 וחכמים אלה היו אוסרים ביום טוב.","על עצם המעשה (בר' חייא ור' שמעון) שואלים: \u0003למימרא דקפדי אהדדי\u0004 \u0005[האם לומר\u0006 מכאן \u0005שהיו מקפידים זה על זה]\u0006 בדברים כגון אלה, עד שהיו זקוקים לשקול מנה כנגד מנה? \u0003והא הנהו שב בניתא\u0004 \u0005[והרי\u0006 מעשה \u0005בשבעה דגים]\u0006 \u0003דאתו לבי\u0004 \u0005[שבאו לבית]\u0006 \u0003רבי ואשתכח\u0004 \u0005[ונמצאו]\u0006 \u0003חמש מנייהו\u0004 \u0005[מהם]\u0006 \u0003בי\u0004 \u0005[בביתו]\u0006 של \u0003ר' חייא,\u0004 לאחר שנטלם מבית רבי, \u0003ולא קפיד\u0004 \u0005[הקפיד]\u0006 \u0003ר' שמעון ברבי,\u0004 שהיו נוהגים בעצמם כמשפחה אחת!","\u0003אמר רב פפא: שדי גברא בינייהו\u0004 \u0005[הטל אדם ביניהם].\u0006 כלומר: בהכרח יש לומר, שהיה אדם אחר מעורב במעשה. כיצד: \u0003אי\u0004 \u0005[או]\u0006 שהיו אלו שחילקו ביניהם את הבשר מנה כנגד מנה \u0003ר' חייא ור' ישמעאל בר' יוסי, אי\u0004 \u0005[או]\u0006 שהיו אלו \u0003ר' שמעון ברבי ובר קפרא,\u0004 שאף שהיו חברים מכל מקום היו מקפידים בכספים ולכן שקלו זה כנגד זה.","\u0003אין משחיזין את הסכין ביום טוב\u0004 כדרך שעושים בחול, \u0003אבל\u0004 מותר לו לעשות כן בשינוי, ולכן הריהו \u0003משיאה\u0004 (מעבירה ומשחיזה) \u0003על גבי חברתה,\u0004 ועל ידי כך הריהו משחיז את הלהב.","\u0003אמר רב הונא: לא שנו\u0004 שאסור להשחיז את הסכין ביום טוב, \u0003אלא\u0004 כשעושה כן \u0003במשחזת של אבן\u0004 שהיא דרך השחזה רגילה \u0003אבל\u0004 אם עושה כן \u0003במשחזת של עץ\u0004 קשה — \u0003מותר,\u0004 שיש בכך שינוי. \u0003אמר רב יהודה אמר שמואל: הא דאמרת\u0004 \u0005[זו שאמרת]\u0006 כי במשחזת \u0003של אבן אסור — לא אמרן\u0004 \u0005[אמרנו]\u0006 כן \u0003אלא\u0004 כשמתכוון \u0003לחדדה, אבל\u0004 אם התכוון \u0003להעביר\u0004 בכך את \u0003שמנוניתה\u0004 שעלתה עליה ורוצה לגרדה בעזרת האבן — \u0003מותר.\u0004 מכלל הדברים אתה למד שבמשחזת \u0003של עץ — אפילו לחדדה נמי\u0004 \u0005[גם כן]\u0006 \u0003מותר.\u0004","\u0003איכא דמתני לה אסיפא\u0004 \u0005[יש ששונים\u0006 את הערתו זו של רב יהודה \u0005על סוף\u0006 דבריו\u0005]\u0006 של רב הונא, שרב הונא אמר \u0003בשל עץ מותר, אמר רב יהודה אמר שמואל: הא דאמרת\u0004 \u0005[זו שאמרת]\u0006 כי \u0003בשל עץ מותר — לא אמרן\u0004 \u0005[אמרנו\u0006 כן\u0005]\u0006 \u0003אלא\u0004 כשעושה כן כדי \u0003להעביר שמנוניתה\u0004 מעליה, \u0003אבל\u0004 אם עושה כן כדי \u0003לחדדה\u0004 — \u0003אסור. מכלל\u0004 הדברים אתה למד ש\u0003בשל אבן אפילו\u0004 אם לא התכוין אלא \u0003להעביר\u0004 את \u0003שמנוניתה\u0004 מעליה — \u0003אסור.\u0004","\u0003איכא דמתני לה אמתניתין\u0004 \u0005[יש ששונים\u0006 את ההערה הזו \u0005על משנתנו]\u0006 עצמה, ששנינו בה: \u0003אין משחיזין את הסכין ביום טוב, אמר רב יהודה אמר שמואל: לא שנו\u0004 לאסור, \u0003אלא\u0004 כשעושה כן כדי \u0003לחדדה, אבל\u0004 אם מטרת מעשהו כדי \u0003להעביר\u0004 את \u0003שמנוניתה\u0004 — \u0003מותר,\u0004 ו\u0003מכלל\u0004 הדברים למד אתה כי להעבירה \u0003על גבי חברתה\u0004 — \u0003אפילו\u0004 אם כוונתו \u0003לחדדה, נמי\u0004 \u0005[גם כן]\u0006 \u0003מותר.\u0004","\u0003ואיכא דמתני לה אסיפא\u0004 \u0005[ויש שהיה שונה\u0006 הערה זו של רב יהודה \u0005על סופה\u0006 של המשנה\u0005].\u0006 ששנינו: \u0003\"אבל משיאה על גבי חברתה\"\u0004 — \u0003אמר רב יהודה אמר שמואל: לא שנו אלא להעביר שמנוניתה, אבל לחדדה\u0004 — \u0003אסור. מכלל\u0004 הדברים אתה למד כי \u0003במשחזת\u0004 — \u0003אפילו להעביר\u0004 את \u0003שמנוניתה\u0004 — \u0003אסור.\u0004","ושואלים: \u0003מאן\u0004 \u0005[מי הוא]\u0006 ה\u0003תנא\u0004 שסבור \u0003שבמשחזת אסור\u0004 לחלוטין? \u0003אמר רב חסדא:\u0004 תנא זה, דעתו ש\u0003לא כ\u0004שיטת \u0003ר' יהודה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין בין יום טוב לשבת אלא אוכל נפש בלבד\u0004 שמותר להכין ביום טוב ולא בשבת. \u0003ר' יהודה מתיר אף מכשירי אוכל נפש.\u0004 שלדעתו מותר לעשות ביום טוב גם כלים או מכשירים לצורך הכנת אוכל נפש.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב חסדא\u0004: \u0003דרשינן משמך\u0004 \u0005[דורשים משמך]\u0006 כי \u0003הלכה כ\u0004שיטת \u0003ר' יהודה. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003יהא רעוא דכל כי הני מילי מעלייתא תדרשון משמאי\u0004 \u0005[יהא רצון שכל דברים טובים כאלה תדרשו משמי],\u0006 כלומר, מרוצה היה רב חסדא מיחוס דעה זו לו, שאף הוא סבור כן.","מסופר: \u0003אמר רב נחמיה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף: הוה קאימנא קמיה\u0004 \u0005[הייתי עומד לפני]\u0006 \u0003רבא, והוה קא\u0004"],["\u0003מעבר לסכינא אפומא דדקולא \u0004\u0005[והיה מעביר סכין על פי הסל]\u0006 ביום טוב \u0003ואמרי ליה \u0004\u0005[ואמרתי לו]:\u0006 האם \u0003לחדדה קא עביד מר \u0004\u0005[עושה אדוני],\u0006 \u0003או\u0004 כדי \u0003להעביר שמנוניתה? ואמר לי: להעביר שמנוניתה. וחזיתי לדעתיה\u0004 \u0005[וראיתי \u0006בכל זה \u0005את דעתו]\u0006 ש\u0003לחדדה\u0004 הוא עושה כן. כלומר: הבנתי שזו היתה כוונתו, ועם כל זה לא אמר לי את כוונתו כפי שהיא, כי \u0003קסבר:\u0004 \u0005[סבור הוא]\u0006 שזו, שיטת ר' יהודה, \u0003הלכה\u0004 לרבים היא \u0003ואין מורין כן,\u0004 ולכן לא התיר במפורש.","\u0003ו\u0004בדומה לכך \u0003אמר אביי: הוה קאימנא קמיה דמר\u0004 \u0005[היייתי עומד לפני אדוני\u0006 מורי, רבה\u0005]\u0006 \u0003והוה קא מעבר סכינא אשפתא דרחיא\u0004 \u0005[והיה מעביר סכין על שפת\u0006 אבן \u0005הרחיים]\u0006 ביום טוב. \u0003ואמרי ליה\u0004 \u0005[ואמרתי לו]:\u0006 האם \u0003לחדדה קא בעי מר\u0004 \u0005[רוצה אדוני],\u0006 \u0003או\u0004 כדי \u0003להעביר\u0004 את \u0003שמנוניתה? ואמר לי:\u0004 כדי \u0003להעביר שמנוניתה. וחזיתי לדעתיה\u0004 \u0005[וראיתי את דעתו]\u0006 ש\u0003לחדדה קא עביד\u0004 \u0005[הוא עושה],\u0006 \u0003וקסבר\u0004 \u0005[\u0006אלא \u0005שהוא סבר]:\u0006 \u0003הלכה ואין מורין כן. \u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: \u0003מהו להראות סכין לחכם ביום טוב\u0004 כדי שיבדוק אותה אם אינה פגומה, וראויה לשחוט בה? \u0003רב מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב ביזנא שרי\u0004 \u0005[התיר],\u0006 \u0003ורבנן אסרי\u0004 \u0005[וחכמים אסרו],\u0006 שהדבר נראה קצת כמעשה חול. \u0003ורב יוסף אמר: תלמיד חכם רואה\u0004 סכין \u0003לעצמו\u0004 לצרכו שלו. \u0003ומשאילה\u0004 אחר כך \u0003לאחרים\u0004 וגם הם יכולים לשחוט בה. ואז אין הדבר נעשה בפומבי ואינו כדרך חול.","\u0003ואמר רב יוסף: סכין שעמדה,\u0004 כלומר: נעשתה קהה, אף שלא נעשה בה פגם — \u0003מותר לחדדה ביום טוב. והני מילי הוא דפסקא אגב דוחקא\u0004 \u0005[ודברים אלה הם כאשר\u0006 הסכין עדיין \u0005חותכת בדוחק]\u0006 שאז אין החידוד כעושה כלי חדש, אלא רק משפר כלי ישן. אבל אם אינה חותכת כלל — אסור.","\u0003דרש רב חסדא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב יוסף: אחד סכין שנפגמה\u0004 ביום טוב \u0003ואחד שפוד שנרצם\u0004 (שנשבר חודו) \u0003ואחד גריפת תנור וכירים ביום טוב,\u0004 שמוציאים מהם את האפר כדי להכשירם לאפות ביום טוב — \u0003באנו למחלוקת ר' יהודה ורבנן\u0004 \u0005[חכמים]\u0006 בענין זה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין בין יום טוב לשבת, אלא אוכל נפש בלבד. ר' יהודה מתיר אף מכשירי אוכל נפש.\u0004","ומסבירים: \u0003מאי טעמא דתנא קמא\u0004 \u0005[מה טעמו של התנא הראשון]\u0006 שאוסר — \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"אך אשר יאכל לכל נפש \u0003הוא לבדו יעשה לכם\"\u0004 (שמות יב, טז), והדיוק הוא: \u0003\"הוא\"\u0004 שהותרה לכם עשייתו ביום טוב — \u0003ולא מכשיריו. ור' יהודה\u0004 לדעתו מביא ראיה ממה ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לכם\"\u0004 ומשמע: \u0003לכם\u0004 — \u0003לכל צרכיכם,\u0004 והכנת המכשירים אף היא לצורך האדם.","ושואלים: \u0003ותנא קמא\u0004 \u0005[והתנא הראשון]\u0006 \u0003הא כתיב\u0004 \u0005[הרי כתוב]\u0006 \u0003\"לכם\"\u0004 ומה לומד הוא מביטוי זה? \u0003אמר לך\u0004 \u0005[\u0006יכול היה תנא זה \u0005לומר לך]:\u0006 \u0003ההוא\u0004 \u0005[אותו\u0006 ביטוי\u0005]\u0006 כוונתו: \u0003לכם ולא לגויים.\u0004","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 ר' יהודה \u0003נמי\u0004 \u0005[גם כן],\u0006 \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"הוא\"\u0004 ולשון זו בא לכאורה להגביל ולצמצם את הדבר, \u0003אמר לך\u0004 \u0005[\u0006יכול היה ר' יהודה \u0005לומר לך]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 אומנם לשון \u0003\"הוא\"\u0004 שהוא לצמצם, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 לשון \u0003\"לכם\"\u0004 שפירושו לכל צרכיכם, \u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה]\u0006 ואין בכך כל סתירה. כי יש לומר \u0003כאן במכשירין שאפשר לעשותן מערב יום טוב\u0004 ואותם אסרה התורה לעשות ביום טוב, \u0003כאן במכשירין שאי אפשר לעשותן מערב יום טוב\u0004 ואותם מותר לתקן ביום טוב עצמו, שכמו הבישול עצמו אף הם בכלל צורך אוכל נפש.","\u0003אמר רב יהודה אמר שמואל: שפוד שנרצף\u0004 (שנתעקם) — \u0003אסור לתקנו ביום טוב.\u0004 ותוהים \u0003פשיטא\u0004 \u0005[פשוט]\u0006 מובן מאליו, הלא אסור לתקן כלי ביום טוב! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא למקרה מסויים; \u0003אף על גב דמפשיט בידיה\u0004 \u0005[אף על פי שהוא יכול להתיישר בידיו\u0006 של אדם\u0005]\u0006 ואין צורך בכלי מלאכה לשם כך, שבכל זאת אסור.","\u0003ואמר רב יהודה אמר שמואל: שפוד שצלו בו בשר\u0004 — \u0003אסור לטלטלו ביום טוב.\u0004 שהרי צורך יום טוב כבר נעשה בו, והשיפוד עצמו שוב אינו ראוי למלאכה. \u0003רב אדא בר אהבה אמר\u0004 בשם \u0003רב מלכיו: שומטו\u0004 את השפוד הזה \u0003ומניחו בקרן זוית,\u0004 שלא יגרום נזק בהיותו מונח באמצע הבית.","\u0003אמר רב חייא בר אשי אמר רב הונא: והוא שיש עליו\u0004 עדיין \u0003כזית בשר\u0004 אז מטלטל את השפוד אגב הבשר, תוך כדי גרירתו וטלטולו מן הצד, שלא כבימות החול. ואם אין עליו כזית בשר — אסור לטלטלו כלל. \u0003רבינא אמר: אף על פי שאין עליו בשר מותר לטלטלו\u0004 בטלטול גמור, ולהניחו בקרן זוית, \u0003מידי דהוה\u0004 \u0005[כשם שהוא\u0006 הדין\u0005]\u0006 לגבי \u0003קוץ\u0004 המוטל \u0003ברשות הרבים,\u0004 שמותר לטלטלו פחות פחות מארבע אמות ולהזיזו הצידה, באופן שלא יזיק את הרבים, ואף שפוד זה, כיון שיכול לגרום נזק אם לא יניחוהו במקומו — מותר להזיזו ולהניחו בקרן זוית.","כיון שהוזכר שמו של רב מלכיו, שלא נאמרו בשמו הלכות רבות, \u0003אמר רב חיננא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא,\u0004 הלכות שנאמרו בענין \u0003שפוד\u0004 שצלו בו בשר וכבר אין עליו כזית בשר, שמותר להזיזו ולהניחו בקרן זוית. וכן בענין אשה שאף שהיא עשירה ביותר והכניסה לו בנדונייתה מאה \u0003שפחות,\u0004 מכל מקום יכול בעלה לכפות אותה לעשות מלאכה כלשהיא, כדי שלא תבוא בשיעמומה לידי חטא (כתובות סא, ב). ובענין שתי \u0003גומות\u0004 שיער שנמצאו באשה, שאף על פי שאין בהן שיער — גדולה היא, וחולצת — את שלוש ההלכות הללו אמר \u0003רב מלכיו,\u0004 ואילו ההלכות שנאמרו בענין","\u0003בלורית.\u0004 שנאמרה ברייתא בענין ישראל המספר את שערו של כותי (שומרוני), שכשמגיע סביב למקום בלוריתו, חייב הוא להפסיק. וזאת משום שהיו הכותים מותירים את בלוריתם לשם עבודה זרה. ועל זה נאמרה ההלכה שצריך להרחיק שלוש אצבעות מכל צידי מקום הבלורית, שאם יספרו עד למקום הבלורית ממש, נראה הדבר כאילו תיקן את בלוריתו לשם עבודה זרה. ובענין האיסור להניח \u0003אפר מקלה\u0004 על גבי מכה, מפני שנראה הדבר ככתובת קעקע. \u0003ו\u0004בענין איסור אכילת \u0003גבינה\u0004 שעשאה גוי, לפי שהגויים מחליקים את פני הגבינה בשומן חזיר — את ההלכות הללו אמר חכם אחר ששמו \u0003רב מלכיא.\u0004","\u0003רב פפא אמר\u0004 כלל אחר: \u0003מתניתין ומתניתא\u0004 \u0005[\u0006כל הדברים השייכים \u0005למשנה ולברייתא]\u0006 — אותם אמר \u0003רב מלכיא. שמעתתא\u0004 \u0005[הלכות]\u0006 שאינן מן המשנה — אמרן \u0003רב מלכיו. וסימניך\u0004 \u0005[וסימנך]\u0006 לזכור את הדבר: \u0003מתניתין מלכתא\u0004 \u0005[משנתנו מלכה\u0006 היא\u0005],\u0006 והסימן הוא שהמעיר על המשנה נקרא רב מלכיא (כמו מלכה). ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין דברי רב חיננא ורב פפא? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל לענין בעל המאמר בענין \u0003שפחות,\u0004 שלדעת רב חיננא, רב מלכיו אמר הלכה זו, ולדעת רב פפא רב מלכיא אמר הלכה זו, שכן היא קשורה למחלוקת שבמשנה.","\u0003לא יאמר אדם לטבח\u0004 (שוחט) ביום טוב: \u0003שקול לי בדינר בשר.\u0004 שאם מזכיר סכום כסף, נראה כמקח וממכר. \u0003אבל שוחט\u0004 הטבח בהמה \u0003ומחלק ביניהם\u0004 בין קוניו מבלי להזכיר את מחירו.","ושואלים: \u0003היכי עביד\u0004 \u0005[כיצד עושה]\u0006 אדם שרוצה לקחת חלק מבהמה ביום טוב ואינו יכול להזכיר שם דמים? ומשיבים: \u0003כי הא\u0004 \u0005[כמו זה]\u0006"],["\u0003בסורא אמרי\u0004 \u0005[היו אומרים]:\u0006 תן לי את החלק המסויים בבהמה הנקרא \u0003תרטא ופלגו\u0004 \u0005[וחצי]\u0006 \u0003תרטא,\u0004 אבל לא קצבו להם מחיר. \u0003בנרש אמרי\u0004 \u0005[היו אומרים]\u0006 בלשון בה היו מכנים חלקים אלו במקומם: \u0003חלקא ופלגו חלקא\u0004 \u0005[חלק וחצי חלק].\u0006 \u0003בפומבדיתא אמרי\u0004 \u0005[היו אומרים]:\u0006 \u0003אוזיא ופלגו אוזיא. בנהר פקוד ובמתא מחסיא אמרי\u0004 \u0005[היו אומרים]:\u0006 תן לי \u0003רבעא\u0004 \u0005[רבע]\u0006 או \u0003פלגו רבעא\u0004 \u0005[חצי רבע],\u0006 כך שקובע אדם את גודל החלק, אבל אינו מזכיר את מחירו.","\u0003אומר אדם לחברו\u0004 ביום טוב: \u0003מלא לי כלי זה\u0004 ואחר החג אחזיר לך את תוכנו או אשלם תמורתו, \u0003אבל לא במדה,\u0004 שלא יאמר לו למלא מידה מסויימת. \u0003ר' יהודה אומר: אם היה כלי\u0004 זה שהוא נותן בידו כלי \u0003של מדה\u0004 — \u0003לא ימלאנו. מעשה באבא שאול בן בטנית\u0004 שהיה חנוני, \u0003שהיה ממלא מדותיו מערב יום טוב ונותנן ללקוחות ביום טוב\u0004 וכך היה יודע כמה נתן, ולא היה חשש מדידה ביום טוב.","\u0003אבא שאול אומר: אף במועד\u0004 (בחול המועד) הוא \u0003עושה כן, מפני ברורי המדות,\u0004 כלומר, כדי שיתברר יפה כמה השיעור שצריך לתת לקונה, לפי שאז נעלמת רתיחת המשקה, והוא נמדד יפה. \u0003וחכמים אומרים: אף בחול\u0004 ראוי שיהא \u0003עושה כן, מפני מצוי המדות,\u0004 שעל ידי כך ממצה אדם בדיוק את המידה המגיעה לו, ואין נשאר דבר בכלי המידה של המוכר.","שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 לשון: \u0003\"אבל לא במדה\"? אמר רב יהודה אמר שמואל: אבל לא בכלי המיוחד למדה. אבל כלי העומד למדה,\u0004 כלומר: כלי שאפשר לעשות אותו כלי מדידה, אלא שלא השתמש בו עדיין — \u0003ימלאנו.\u0004 ולפי זה \u0003אתא\u0004 \u0005[בא]\u0006 \u0003ר' יהודה למימר\u0004 \u0005[לומר]\u0006 ולחלוק ש\u0003אפילו כלי העומד למדה לא ימלאנו.\u0004","ושואלים: \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003גבי שמחת יום טוב\u0004 שיטת \u0003ר' יהודה לחומרא\u0004 \u0005[להחמיר]\u0006 והוא אוסר, אף שיש בזה חשש ביטול מצוות שמחה, \u0003ורבנן לקולא\u0004 \u0005[ו\u0006שיטת \u0005חכמים להקל]?\u0006 \u0003והא אפכא שמעינן להו\u0004 \u0005[והרי היפך\u0006 הדברים \u0005שומעים אנו אותם],\u0006 \u0003דתנן\u0004 \u0005[\u0006שהרי \u0005שנינו\u0006 במשנתנו\u0005]\u0006 (לעיל ביצה כח, א), \u0003ר' יהודה אומר: שוקל אדם בשר כנגד הכלי וכנגד הקופיץ, וחכמים אומרים: אין משגיחין בכף מאזנים כל עיקר. אלמא\u0004 \u0005[מכאן]\u0006 ששיטת \u0003ר' יהודה לקולא\u0004 \u0005[להקל]\u0006 \u0003ורבנן\u0004 \u0005[ו\u0006שיטת \u0005חכמים]\u0006 \u0003לחומרא\u0004 \u0005[להחמיר],\u0006 ואם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה\u0004 ו\u0003קשיא דרבנן אדרבנן\u0004 \u0005[וקשה\u0006 מדברי \u0005חכמים על\u0006 דברי \u0005חכמים]!\u0006","ומתרצים: מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 שהקל בכלי ששוקלים בו מדובר \u0003ב\u0004כלי \u0003שאינו עומד למדה\u0004 כלל, אולם \u0003הכא\u0004 \u0005[כאן]\u0006 מדובר בכלי ה\u0003עומד למדה\u0004 ולכן מחמיר גם אם לא מדדו בו.","\u0003דרבנן אדרבנן נמי לא קשיא\u0004 \u0005[\u0006מדרבי \u0005חכמים על\u0006 דברי \u0005חכמים גם כן אינו קשה]\u0006 שכן \u0003התם קא עביד כדעבדין\u0004 \u0005[שם הוא עושה כדרך שעושים]\u0006 \u0003ב\u0004יום \u0003חול,\u0004 בדרך שקילה, ולכן אסרו, אולם \u0003הכא לא קא עביד כדעבדין\u0004 \u0005[כאן אינו עושה כפי שעושים]\u0006 \u0003ב\u0004יום \u0003חול,\u0004 שהרי הכלי איננו כלי מדידה ולכן התירו. עד כאן לפי דעת שמואל.","\u0003רבא אמר: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אבל לא במדה\"\u0004 — \u0003שלא יזכור לו שם מדה\u0004 — כגון לא יאמר: מלא לי קב או שני קבים. \u0003אבל כלי המיוחד למדה\u0004 מכל מקום — \u0003ימלאנו, ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' יהודה למימר\u0004 \u0005[לומר]:\u0006 \u0003כלי המיוחד למדה\u0004 — \u0003לא ימלאנו\u0004 אפילו אינו מזכיר שם מדה.","ושואלים: \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003גבי שמחת יום טוב\u0004 שיטת \u0003ר' יהודה לחומרא\u0004 \u0005[להחמיר]\u0006 \u0003ורבנן לקולא\u0004 \u0005[ו\u0006שיטת \u0005חכמים להקל]?\u0006 \u0003והא אפכא שמעינן להו\u0004 \u0005[והרי היפך\u0006 הדברים \u0005שמענו אותם]!\u0006 \u0003דתנן\u0004 \u0005[\u0006שהרי \u0005שנינו\u0006 במשנתנו\u0005]\u0006 (לעיל ביצה כח, א), \u0003ר' יהודה אומר: שוקל אדם בשר כנגד הכלי וכנגד הקופיץ, וחכמים\u0004 אוסרים ו\u0003אומרים: אין משגיחין בכף מאזנים כל עיקר. אלמא\u0004 \u0005[מכאן]\u0006 כי שיטת \u0003ר' יהודה לקולא\u0004 \u0005[להקל]\u0006 \u0003ורבנן לחומרא\u0004 \u0005[ו\u0006שיטת \u0005חכמים להחמיר],\u0006 ואם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה,\u0004 ו\u0003קשיא דרבנן אדרבנן\u0004 \u0005[וקשה מ\u0006דברי \u0005חכמים על\u0006 דברי \u0005חכמים]!\u0006","ומתרצים: מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה לא קשיא\u0004 \u0005[אינו קשה],\u0006 שכן \u0003התם\u0004 \u0005[שם]\u0006 בענין השקילה כנגד כלי מדובר \u0003בשאינו\u0004 שאין הכלי הזה \u0003מיוחד\u0004 למדידה ולכן התיר, אולם \u0003הכא\u0004 \u0005[כאן]\u0006 מדובר בכלי ה\u0003מיוחד\u0004 למדידה ולכן אסר. ואילו \u0003דרבנן אדרבנן נמי לא קשיא\u0004 \u0005[מ\u0006דברי \u0005חכמים על\u0006 דברי \u0005חכמים גם כן אינו קשה],\u0006 שכן \u0003התם קא עביד כדעבדין\u0004 הוא \u0005עושה כמו שעושים]\u0006 \u0003ב\u0004יום \u0003חול\u0004 ולכן אסרו, אולם \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003לא קעביד כדעבדין\u0004 \u0005[כאן אינו עושה כפי שעושים]\u0006 \u0003ב\u0004יום \u0003חול,\u0004 שכן \u0003דעבדי אינשי דמקרבי חמרא במנא דכילא ושתו\u0004 \u0005[שעשויים אנשים להביא\u0006 לחבריהם \u0005יין בכלי המידה ושותים]\u0006 ואם כן, השימוש בכלי זה איננו עניין של מקח וממכר דווקא ולכן התירו.","מובא במשנה \u0003מעשה באבא שאול בן בטנית\u0004 שהיה ממלא מידותיו מבעוד יום. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003אף ב\u0004חול ה\u0003מועד\u0004 היה \u0003עושה כן מפני בטול בית המדרש.\u0004 מאחר שרצה להיות רוב היום בבית המדרש, וכדי שלא יבטל מזמן התורה כדי למדוד כמה מגיע ללקוחותיו היה מודד בלילה שאינו זמן בית המדרש.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הוא כנס שלש מאות גרבי\u0004 (כדי חרס) של \u0003יין,\u0004 שהיה חושב שהם \u0003מברורי המדות,\u0004 כלומר, שלדעתו הרויח על ידי הקצף שעל המשקה שמדד. \u0003וחבריו,\u0004 חנוונים יראי שמים אחרים, \u0003כנסו שלש מאות גרבי שמן ממצוי המדות\u0004 שסברו שמתוך שמדדו בכלי שלהם עבור הלקוחות, שמא לא נתמצתה כל המידה ללקוחות, \u0003והביאום לפני הגזברים\u0004 של בית המקדש \u0003לירושלים,\u0004 לפי שחששו לגזל ולא רצו ליהנות מזה.","\u0003אמרו להם\u0004 הגזברים: \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתם זקוקים לכך\u0004 כי בכל קניה מביא הקונה בחשבון את ההפרש שנוצר על ידי הקצף והשארית שבכלי, ועל דעת כן הוא משלם. \u0003אמרו להם: אף אנו אין רצוננו בכך\u0004 שנרויח מאלה, גם אם אין בדבר גזל מצד הדין.","\u0003אמרו להם\u0004 הגזברים: \u0003הואיל והחמרתם על עצמכם\u0004 — \u0003עשו מהם\u0004 מיין ושמן אלה \u0003צרכי רבים. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003גזל\u0004 אדם \u0003ואינו יודע למי גזל\u0004 — \u0003יעשה בהם צרכי רבים\u0004 ונמצא מחזיר לכל ישראל. ושואלים: \u0003מאי נינהו\u0004 \u0005[מה הם]\u0006 צרכי רבים? \u0003אמר רב חסדא:\u0004 יממן חפירת \u0003בורות, שיחין\u0004 (חפירות מרובעות) \u0003ומערות\u0004 לכנוס בהם מים לעוברי דרכים.","\u0003אדבריה\u0004 \u0005[נתן רשות]\u0006 \u0003רב חסדא לרבנא עוקבא\u0004 לדרוש ברבים, \u0003ודרש\u0004 בלשון זו: \u0003לא ימדוד אדם שעורים ויתן לפני בהמתו ביום טוב, אבל קודר הוא,\u0004 כלומר: עושה בערימה חור על ידי כלי של \u0003קב או קבים ונותן לפני בהמתו ואינו חושש\u0004 למדידה שיש בכך, שאם אינו מקפיד למדוד ממש אין חשש איסור בשימוש בכלי של מידה. \u0003והנחתום מודד תבלין ונותן לתוך קדרתו, כדי שלא יקדיח\u0004 (יקלקל) את \u0003תבשילו,\u0004 שהרי אם יוסיף יתר על המידה יקלקל את התבשיל.","\u0003אמר רב ירמיה בר אבא אמר רב: מודדת אשה קמח ביום טוב ונותנת לתוך עיסתה כדי שתטול חלה בעין יפה,\u0004 שאם יודעת היא את הכמות יכולה היא ליטול חלה כפי המידה הראויה. \u0003ושמואל אמר: אסור,\u0004 שיכולה לתת לפי ההערכה. ומקשים: \u0003והא תנא דבי\u0004 \u0005[והרי שנה\u0006 חכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003שמואל\u0004 ברייתא, שבה נאמר שדבר זה \u0003מותר!\u0004","\u0003אמר אביי: השתא\u0004 \u0005[עכשיו]\u0006 שיודעים אנו ש\u0003אמר שמואל\u0004 ש\u0003אסור, ותנא דבי\u0004 \u0005[ושנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003שמואל\u0004 ברייתא ש\u0003מותר,\u0004"],["\u0003שמואל\u0004 — \u0003הלכה למעשה אתא לאשמועינן\u0004 \u0005[בא להשמיע לנו].\u0006 שהרי ידע שיש ברייתא המתירה, ולכן היה הוא עצמו צריך לומר שאין הלכה כן.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין שונין,\u0004 כלומר, אין מנפין שנית \u0003קמח ביום טוב,\u0004 שיש בכך טרחה יתרה שאינה הכרחית. \u0003משום\u0004 (משמם) של \u0003ר' פפייס ור' יהודה בן בתירה אמרו: שונין. ושוין\u0004 (ומסכימים) גם חכמים האוסרים \u0003שאם\u0004 לאחר שניפו את הקמח מבעוד יום \u0003נפל לתוכן צרור\u0004 (אבן) \u0003או קיסם, ששונין\u0004 ומנפים, כדי לברר את הקיסמים.","\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רבינא\u0004 הלכה זו: \u0003אין שונין קמח ביום טוב, אבל\u0004 אם לאחר הניפוי הראשון \u0003נפל צרור או קיסם — בורר בידו. אמר ליה\u0004 \u0005[לו]\u0006 רבינא: \u0003כל שכן\u0004 ש\u0003אסור\u0004 באופן זה, \u0003דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003כבורר\u0004 ממש באופן האסור במלאכת בורר, ומוטב שינפה את הקמח בנפה ונמצא הקיסם מתברר מעצמו.","\u0003דרש רבא בר רב הונא זוטי\u0004 \u0005[הקטן]\u0006 \u0003אפתחא\u0004 \u0005[על פתחה]\u0006 של \u0003נהרדעא: שונין קמח ביום טוב. אמר להו\u0004 \u0005[להם]\u0006 \u0003רב נחמן\u0004 לתלמידים העומדים לפניו: \u0003פוקו\u0004 \u0005[צאו]\u0006 \u0003ואמרו ליה\u0004 \u0005[לו]\u0006 \u0003לאבא,\u0004 כלומר, לרבא בר רב הונא (שרבא הוא קיצור של ר' אבא): \u0003שקילא טיבותך ושדי אחזרי\u0004 \u0005[נטולה טובתך ומוטלת על הקוצים],\u0006 כלומר, אין צורך בחידושים שחידשת לנו, כי \u0003פוק חזי כמה מהולתא הדרן\u0004 \u0005[צא וראה כמה נפות מסתובבות]\u0006 \u0003בנהרדעא,\u0004 שכל הנשים כבר יודעות שדבר זה מותר.","מסופר: \u0003דביתהו\u0004 \u0005[אשתו]\u0006 של \u0003רב יוסף נהלא קמחא אגבא דמהולתא\u0004 \u0005[היתה מנפה את הקמח על גב הנפה]\u0006 מן הצד ההפוך. \u0003אמר לה: חזי, דאנא רפתא מעליתא בעינא\u0004 \u0005[ראי, שאני לחם מעולה אני רוצה],\u0006 כלומר, רמז לה שאין צורך להפוך, ויכולה לנפות כדרכה. וכן מסופר: \u0003דביתהו\u0004 \u0005[אשתו]\u0006 של \u0003רב אשי נהלא קמחא אגבא דפתורא\u0004 \u0005[היתה מנפה קמח על גבי השלחן]\u0006 כדי לעשות שינוי בדבר ולא לנפות לתוך קערה. \u0003אמר רב אשי: הא דידן\u0004 \u0005[זו שלנו]\u0006 אשתי, \u0003ברתיה\u0004 \u0005[בתו]\u0006 של \u0003רמי בר חמא\u0004 היא, \u0003ורמי בר חמא מרא דעובדא הוה\u0004 \u0005[בעל מעשים היה]\u0006 \u0003ואי לאו דחזיא מבי נשא לא הוה עבדא\u0004 \u0005[ואם לא היתה רואה\u0006 אשתי \u0005מבית אביה\u0006 שכך עושים \u0005לא היתה עושה]\u0006 ואפשר ללמוד ממנה איפוא הלכה למעשה.","\u0003הולך אדם\u0004 ביום טוב \u0003אצל חנוני\u0004 שהוא \u0003רגיל\u0004 לקנות \u0003אצלו ואומר לו: תן לי ביצים ואגוזים במנין\u0004 במספר כזה וכזה, \u0003שכן דרך בעל הבית להיות מונה\u0004 גם \u0003בתוך ביתו\u0004 ואין בכך דרך מקח וממכר, שהרי דרכו של אדם לחשב כמה ביצים ואגוזים הוא צריך לעצמו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 \u0003הולך אדם אצל רועה\u0004 שהוא \u0003רגיל אצלו ואומר לו: תן לי גדי אחד או טלה אחד.\u0004 וכן הולך אדם ביום טוב \u0003אצל טבח\u0004 (קצב) \u0003הרגיל אצלו ואומר לו: תן לי כף\u0004 (כלומר רגל קדמית של בהמה) \u0003אחת, או ירך אחת.\u0004 הולך \u0003אצל פטם\u0004 של עופות שהוא \u0003רגיל אצלו ואומר לו: תן לי תור אחד או גוזל אחד.\u0004 הולך \u0003אצל נחתום\u0004 שהוא \u0003רגיל אצלו ואומר לו: תן לי ככר אחד או גלוסקא\u0004 (עוגה) \u0003אחת.\u0004","","\u0003ואצל חנוני הרגיל אצלו ואומר לו: תן לי עשרים ביצים, או חמשים אגוזים, עשרה אפרסקין, וחמשה רמונים ואתרוג אחד. ובלבד שלא יזכיר לו סכום מדה.\u0004 כלומר, שלא יאמר לו מידה כגון ליטרא או קב אלא יאמר לו לפי מספר, שהוא שינוי מן הדרך שרגילים כרגיל לקנות. \u0003ר' שמעון בן אלעזר אומר: ובלבד שלא יזכיר לו סכום\u0004 ה\u0003מקח,\u0004 כלומר: באיזה סכום כסף הוא קונה, אלא יקח כל צרכו, ולמחר יחשב עמו.","","\u0003המביא כדי יין ממקום למקום\u0004 — \u0003לא יביאם\u0004 כדים כדים \u0003ב\u0004תוך \u0003סל או ב\u0004תוך \u0003קופה\u0004 כדרך שהוא עושה בחול, שנראה הדבר כזלזול ומעשה חולין בחג. \u0003אבל מביא הוא\u0004 חבית אחת או שתים \u0003על כתפו, או\u0004 מחזיקן \u0003לפניו. וכן המוליך את התבן\u0004 להסקה או למאכל בהמה — \u0003לא יפשיל\u0004 (יניח) \u0003את הקופה\u0004 (סל) \u0003לאחוריו,\u0004 כיון שנראה הדבר כמעשה חול, \u0003אבל מביאה הוא בידו\u0004 לפניו בדרך שינוי. \u0003ומתחילין\u0004 לקחת תבן להסקה"],["\u0003בערמת התבן\u0004 אף על פי שלא זימנה לכך מבעוד יום, \u0003אבל לא\u0004 מתחילים לקחת מן \u0003העצים שבמוקצה\u0004 החצר קטנה שמאחורי הבית, ששם מניחים אנשים דברים שונים שאין דעתם להשתמש בהם אלא לאחר זמן.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם בתוספתא\u0005]:\u0006 \u0003אם אי אפשר לשנות,\u0004 אם מצד הכלי או מצד דוחק הזמן — \u0003מותר\u0004 לעשות כדרכו בחול.","ומסופר: \u0003אתקין\u0004 \u0005[התקין]\u0006 \u0003רבא\u0004 תקנה זו \u0003במחוזא\u0004 עירו: \u0003דדרו בדוחקא\u0004 \u0005[\u0006אלה \u0005שנושאים\u0006 כרגיל משא אחד \u0005בקושי]\u0006 ביום חול — ביום טוב יעשו שינוי מכפי שרגילים ואף יקלו על עצמם, ולכן \u0003לדרו ברגלא\u0004 \u0005[שישאו אותו על מוט\u0006 על כתפיהם\u0005].\u0006 \u0003דדרו ברגלא\u0004 \u0005[\u0006אלה האנשים שנוהגים \u0005לשאת במוט]\u0006 \u0003— לדרו באגרא\u0004 \u0005[שישאו אותו במוט בשנים].\u0006 \u0003דדרו באגרא\u0004 \u0005[\u0006אלה \u0005שנושאים\u0006 משא \u0005במוט בשנים]\u0006 — \u0003לדרו באכפא\u0004 \u0005[שישאו במוט\u0006 שמחזיקים בידיהם\u0005]\u0006 כשינוי, אף שאינם מקלים בכך על עצמם. \u0003דדרו באכפא\u0004 \u0005[\u0006אלה \u0005שנושאים\u0006 משא \u0005במוט\u0006 שבידיהם\u0005]\u0006 — \u0003נפרוס סודרא עלויה\u0004 \u0005[שיפרסו סודר עליו],\u0006 \u0003ואם לא אפשר\u0004 מפני דוחק הזמן לעשות שינויים אלה — \u0003שרי\u0004 \u0005[מותר]\u0006 כדרכו. ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003אם אי אפשר לשנות — מותר. אמר ליה\u0004","\u0005[לו]\u0006 \u0003רב חנן בר רבא לרב אשי: אמור רבנן\u0004 \u0005[אמרו חכמים]\u0006 \u0003כמה\u0004 ש\u0003אפשר לשנויי\u0004 \u0005[לשנות]\u0006 — \u0003משנינן ביומא טבא\u0004 \u0005[משנים ביום טוב],\u0006 שלא לנהוג כדרך שעושים בימות החול. ושאלו רב אשי: \u0003והא הני נשי דקא מליין חצבייהו מיא ביומא טבא ולא קא משניין\u0004 \u0005[והרי אותן נשים הממלאות כדיהן מים ביום טוב ואינן משנות]\u0006 \u0003ולא אמרינן להו ולא מידי\u0004 \u0005[ואין אנו אומרים להן דבר],\u0006 ומדוע אין אנו מורים להן לשנות?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003משום\u0004 ש\u0003לא אפשר\u0004 באופן אחר. \u0003היכא ליעבד\u0004 \u0005[כיצד לעשות]?\u0006 \u0003דמליא בחצבא רבה תמלי בחצבא זוטא\u0004 \u0005[\u0006זו \u0005ש\u0006רגילה \u0005למלאות בכד גדול תמלא בכד קטן]\u0006 \u0003— קא מפשא בהלוכא\u0004 \u0005[\u0006הרי \u0005היא\u0006 \u0005מרבה בהילוך],\u0006 שהיא צריכה להביא יותר מכד אחד לביתה, ונמצא שהיא עושה מלאכה יתירה ביום טוב בהילוך יתר.","אם תאמר להיפך \u0003דמליא בחצבא זוטא תמלי בחצבא רבה\u0004 \u0005[הממלאה בכד קטן תמלא בכד גדול]\u0006 — \u0003קא מפשא במשוי\u0004 \u0005[הרי היא מרבה במשא].\u0006 \u0003תכסייה בנכתמא\u0004 \u0005[\u0006אם תאמר \u0005שתכסה\u0006 את הכד \u0005במכסה\u0006 עץ\u0005]\u0006 \u0003— זמנין דנפיל ואתי לאתויי\u0004 \u0005[פעמים ש\u0006הוא \u0005נופל ועשויה להביאו]\u0006 ולטלטלו ביד כדרך משאוי. \u0003תקטריה\u0004 \u0005[תקשור]\u0006 את המכסה לכד \u0003— זמנין דמפסיק, ואתי למקטריה\u0004 \u0005[פעמים ש\u0006הוא \u0005נפסק ותבוא לקשור אותו]\u0006 ותמצא עושה מלאכה אסורה. ש\u0003תפרוס סודרא עלויה\u0004 \u0005[סודר עליו]\u0006 \u0003— זמנין דמטמיש במיא\u0004 \u0005[פעמים ש\u0006הוא נופל \u0005ושורה בתוך המים]\u0006 \u0003ואתי\u0004 \u0005[ותבוא]\u0006 \u0003לידי סחיטה. הלכך\u0004 \u0005[על כן]\u0006 \u0003לא אפשר,\u0004 ולפיכך אין לשנות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא בר רב חנין לאביי,\u0004 הלא \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין מטפחין\u0004 (מוחאים כף) \u0003ואין מספקין\u0004 (מכים יד על ירך) — \u0003ואין מרקדין\u0004 ברגלים ביום טוב, ואת כולם אסרו חכמים גזירה שמא יתקן כלי שיר, \u0003והאידנא דקא חזינא דעבדן הכי ולא אמרינן להו ולא מידי\u0004 \u0005[ועכשיו אנו רואים ש\u0006הנשים \u0005עושות כך ואין אנו אומרים להן דבר]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ולטעמך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003אמר רבא: לא ליתיב איניש אפומא דלחיא\u0004 \u0005[אל ישב אדם על פי הלחי],\u0006 שעושים בקצה המבוי שהתקינו אותו להיות כרשות היחיד, \u0003דלמא מגנדר ליה\u0004 \u0005[שמא יתגלגל ממנו]\u0006 \u0003חפץ ואתי לאתויי\u0004 \u0005[ויבוא להביאו]\u0006 \u0003ארבע אמות ברשות הרבים\u0004 ונמצא עובר על איסור תורה, \u0003והא הני נשי דשקלן חצבייהו, ואזלן ויתבן אפומא דמבואה, ולא אמרינן להו ולא מידי\u0004 \u0005[והרי אלה הנשים שלוקחות את כדיהן, והולכות ויושבות על פי המבוי ואין אנו אומרים להן דבר],\u0006","\u0003אלא\u0004 אנו נוקטים בכלל: \u0003הנח להם לישראל,\u0004 כי \u0003מוטב שיהיו שוגגין ואל יהיו מזידין.\u0004 שאם רואים שהעם נוהג במנהג מסויים שאי אפשר לעקור אותו — מוטב שלא להרבות להוכיחם, כי מסתבר שעל אף התוכחה ימשיכו לעשות כן ויהיה הדבר במזיד, ולכן מוטב שלא ידעו שעושים בכך איסור ויישארו שוגגים בלבד. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בענין טיפוח וריקוד \u0003הנח להם לישראל,\u0004 כי \u0003מוטב שיהיו שוגגין ואל יהיו מזידין.\u0004","ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 שאומרים \"הנח להם לישראל וכו'\" אמורים דווקא \u0003ב\u0004איסורים \u0003דרבנן\u0004 \u0005[שמדברי סופרים],\u0006 \u0003אבל\u0004 אם יש בזה איסור \u0003בדאורייתא\u0004 [\u0005מן התורה]\u0006 — \u0003לא\u0004 אומרים כן. והעירו על סברה זו לאחר זמן: \u0003ולא היא\u0004 (ואינה כן), \u0003לא שנא בדאורייתא ולא שנא בדרבנן, לא אמרינן להו ולא מידי\u0004 \u0005[אינו שונה ב\u0006איסור \u0005מן התורה ואינו שונה ב\u0006איסור \u0005מדברי סופרים אין אומרים להם דבר]\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003תוספת יום הכפורים,\u0004 שחובה להוסיף זמן מסויים מבעוד יום על יום הכיפורים, ולנהוג בו בכל דיני יום הכיפורים, \u0003דאורייתא\u0004 \u0005[שמן התורה]\u0006 \u0003הוא, ואכלי ושתו\u0004 \u0005[ואוכלים ושותים\u0006 אנשים\u0005]\u0006 \u0003עד שחשכה\u0004 ממש \u0003ולא אמרינן להו ולא מידי\u0004 \u0005[ואין אנו אומרים להם דבר]\u0006 משום שאנו יודעים שלא יצייתו בזה.","שנינו במשנה: \u0003ומתחילין בערמת התבן. אמר רב כהנא: זאת אומרת: מתחילין באוצר תחלה.\u0004 כלומר: מותר לכתחלה ליטול ביום טוב דברים מן האוצר (המחסן) אף שהוא מיועד למטרות אחרות, ואין אומרים שהקצה אותו מדעתו. ואם כן \u0003מני\u0004 \u0005[כשיטת מי היא]\u0006 משנה זו — כשיטת \u0003ר' שמעון היא דלית ליה\u0004 \u0005[שאין לו,\u0006 שאינו סובר\u0005]\u0006 דין \u0003מוקצה,\u0004 שלשיטתו אין איסור טלטול ושימוש בשבת וחג בדברים שאדם מקצה מדעתו.","ומקשים: \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של אותה משנה: \u0003אבל לא בעצים שבמוקצה.\u0004 אם כן, \u0003אתאן\u0004 \u0005[הגענו]\u0006 \u0003ל\u0004שיטת \u0003ר' יהודה, דאית ליה\u0004 \u0005[שיש לו,\u0006 שהוא סובר\u0005]\u0006 את דין \u0003מוקצה!\u0004 ומתרצים: \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בארזי ואשוחי עסקינן\u0004 \u0005[בארזים ואשוחים אנו עוסקים]\u0006 שהם עצים יקרים שאין משתמשים בהם להסקה אלא רק לבנינים חשובים, וזה הוא \u0003מוקצה מחמת חסרון כיס,\u0004 כלומר דבר שאדם הקצהו לא מחמת איסור שבו, אלא מחמת חסרון כיס אם ישתמש בו, ובזה \u0003אפילו ר' שמעון מודה\u0004 שיש לאסור את טלטולם משום מוקצה.","ויש שגרסו שמועה זו בשינוי, \u0003איכא דמתני לה אסיפא\u0004 \u0005[יש ששנה\u0006 את ההערה \u0005הזו\u0006 של רב כהנא \u0005על סופה]\u0006 של המשנה: \u0003אבל לא בעצים שבמוקצה. אמר רב כהנא: זאת אומרת, אין מתחילין באוצר תחלה.\u0004 אם כן \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא\u0006 משנתנו\u0005]\u0006 — כשיטת \u0003ר' יהודה היא, דאית ליה\u0004 \u0005[שיש לו,\u0006 שהוא סובר\u0005]\u0006 ענין \u0003מוקצה.\u0004 ומקשים: \u0003אימא רישא\u0004 \u0005[אמור את ראשה\u0006 של המשנה\u0005]\u0006 שנאמר בה כי \u0003מתחילין בערמת התבן,\u0004 אם כן \u0003אתאן\u0004 \u0005[הגענו]\u0006 \u0003ל\u0004שיטת \u0003ר' שמעון דלית ליה\u0004 \u0005[שאין לו,\u0006 שאינו סובר\u0005]\u0006 ענין \u0003מוקצה!\u0004 ומשיבים: \u0003התם בתבנא סריא\u0004 \u0005[שם\u0006 מדובר \u0005בתבן\u0006 שנרקב \u0005ומסריח]\u0006 ואינו ראוי למאכל בהמה, ומן הסתם נועד להסקה.","ושואלים: \u0003תבנא סריא הא חזי לטינא\u0004 \u0005[תבן שהסריח הלא ראוי הוא לטיט]\u0006 לגבל בו לבנים, ומדוע אנו אומרים שלצורך הסקה הכין אותו! ומשיבים: כאן מדובר בתבן \u0003דאית ביה\u0004 \u0005[שיש בו]\u0006 \u0003קוצים,\u0004 ולכן אי אפשר ללוש אותו בתוך הטיט, וודאי נועד להסקה בלבד."],["\u0003אין נוטלין\u0004 (בכל יום טוב שהוא ולאו דווקא בחג הסוכות) \u0003עצים מן הסוכה,\u0004 מפני שהוא כמפרק אותה, \u0003אלא\u0004 נוטל \u0003מן הסמוך לה\u0004 מן העצים שליד דפנותיה.","על המשנה שואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003מן הסוכה\u0004 עצמה ש\u0003לא\u0004 יטול ממנה עצים — \u0003דקא סתר אהלא\u0004 \u0005[\u0006שהרי \u0005הוא סותר\u0006 על ידי כך \u0005אוהל]\u0006 ועושה אב מלאכה של סתירה, ואם כן, \u0003מן הסמוך לה נמי\u0004 \u0005[גם כן]\u0006 הלא \u0003קא סתר אהלא\u0004 \u0005[הוא סותר אהל]!\u0006 ומדוע התירה המשנה לעשות כן?","\u0003אמר רב יהודה אמר שמואל: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"סמוך\"\u0004 — \u0003סמוך לדפנות.\u0004 כלומר, לא מן הדפנות עצמן אלא מן העצים הסמוכים לדפנות, שאינם מהווים חלק מבנין הסוכה. \u0003רב מנשיא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 כי מדובר \u0003בשאין סמוך לדפנות\u0004 אלא מן הסכך עצמו, אולם \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה\u0006 משנתנו\u0005]\u0006 הרי זה \u0003באסורייתא\u0004 \u0005[חבילות\u0006 של קנים\u0005]\u0006 שכיון שלא התירן, אינן נחשבות כחלק מן הסכך, ולכן יכול ליטול מהם.","\u0003תניא\u0004 \u0005[שנה]\u0006 \u0003ר' חייא בר יוסף קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן\u0004 ברייתא זו: \u0003אין נוטלין עצים מן הסוכה\u0004 עצמה \u0003אלא מן הסמוך לה, ור' שמעון מתיר\u0004 ליטול אף ממנה. \u0003ושוין\u0004 (ומסכימים כולם) אף ר' שמעון לגבי \u0003סוכת החג\u0004 (סוכה של מצוה שעושים בחג הסוכות) במשך זמן \u0003החג\u0004 — \u0003שאסורה\u0004 ליטול ממנה. \u0003ואם התנה עליה\u0004 מראש שישתמש בעצים שבה לצרכים אחרים — \u0003הכל לפי תנאו.\u0004","על לשון הברייתא תוהים: \u0003ור' שמעון מתיר? והא קא סתר אהלא\u0004 \u0005[והרי הוא סותר אוהל]\u0006 וכיצד יתיר לסתור ולעשות מלאכה גמורה! ומתרצים: \u0003אמר רב נחמן בר יצחק: הכא\u0004 \u0005[כאן]\u0006 \u0003בסוכה נופלת עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שהסוכה כבר התמוטטה, ואין כאן משום סתירת אהל, אבל יש חשש מוקצה, \u0003ור' שמעון לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 \u0003דלית ליה\u0004 \u0005[שאין לו,\u0006 שאינו סובר\u0005]\u0006 דין \u0003מוקצה,\u0004 ולכן התיר במקום שחכמים אוסרים. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מותר השמן שבנר ושבקערה\u0004 שהדליקו בהם פתילה מבעוד יום וכבתה הפתילה בשבת ונשאר בנר עוד שמן — \u0003אסור\u0004 להשתמש בו משום מוקצה. \u0003ור' שמעון מתיר\u0004 בשימוש.","ודוחים: \u0003מי דמי\u0004 \u0005[האם דומה]\u0006 הדבר? \u0003התם\u0004 \u0005[שם]\u0006 בענין השמן שבנר אפשר לומר כי \u0003אדם יושב ומצפה אימתי תכבה נרו,\u0004 שהרי יודע הוא שהפתילה עשויה לכבות לאחר זמן מסויים, ומראש דעתו להשתמש במותר השמן, אבל \u0003הכא\u0004 \u0005[כאן]\u0006 וכי תאמר ש\u0003אדם יושב ומצפה אימתי תפול סוכתו?\u0004 והלא אינו נביא ולכך אינו עשוי לדעת שעתידה סוכתו ליפול למחרת.","\u0003אמר רב נחמן בר יצחק:\u0004 אכן, \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בסוכה רעועה עסקינן\u0004 \u0005[עוסקים אנו]\u0006 ש\u0003מאתמול\u0004 מערב יום טוב כבר \u0003דעתיה עלויה\u0004 \u0005[דעתו עליה\u0006 שתפול\u0005]\u0006 ולא הסיח דעתו מלהשתמש בעצים שבה.","באותה ברייתא נאמר: \u0003ושוין בסוכת החג בחג שהיא אסורה, ואם התנה עליה\u0004 — \u0003הכל לפי תנאו.\u0004 ושואלים: \u0003ומי מהני\u0004 \u0005[והאם מועיל]\u0006 \u0003בה תנאי?\u0004","\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב ששת משום\u0004 \u0005[משמו]\u0006 של \u0003ר' עקיבא: מנין לעצי סוכה ש\u0004הם \u0003אסורין\u0004 בשימוש לצורך אחר \u0003כל שבעה\u0004 ימים של חג — \u0003שנאמר: \"חג הסכות שבעת ימים לה'\"\u0004 (ויקרא כג, לד), \u0003ותניא\u0004 \u0005[ושנינו\u0006 בברייתא\u0005]\u0006 אחרת להסביר את הדברים; \u0003ר' יהודה בן בתירא אומר: מנין שכשם שחל שם שמים על\u0004 קרבן \u0003החגיגה, כך חל שם ש\u0004מי \u0003ם\u0004 אף \u0003על הסוכה — תלמוד לומר: \"חג הסכות שבעת ימים לה'\"\u0004 (ויקרא כג, לד). למדנו: \u0003מה חג\u0004 (קרבן החג) הוא \u0003לה' — אף סוכה\u0004 היא \u0003לה'.\u0004 וכיון שדין עצי הסוכה כעין הקדש, כיצד יכול להתנות איפוא על ההקדש?","\u0003אמר רב מנשיא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא: סיפא\u0004 \u0005[בסוף],\u0006 בהיתר על ידי התנאי \u0003אתאן\u0004 \u0005[באנו]\u0006 \u0003ל\u0004ענין \u0003סוכה דעלמא\u0004 \u0005[בכלל],\u0006 שאינה סוכת החג, לומר שיכול אדם להתנות שרצונו להשתמש בעצים למטרה אחרת, \u0003אבל סוכה\u0004 של \u0003מצוה\u0004 — \u0003לא מהני\u0004 \u0005[מועיל]\u0006 \u0003בה תנאה\u0004 \u0005[תנאי].\u0006","ושואלים מצד אחר: \u0003וסוכה\u0004 של \u0003מצוה לא\u0004 מועיל בה תנאי? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בתוספתא\u0005]:\u0006 סוכה \u0003שסככה כהלכתה ועטרה בקרמין\u0004 (בבגדים רקומים) \u0003ובסדינין המצויירין, ותלה בה\u0004 לנוי \u0003אגוזים שקדים אפרסקים ורמונים ופרכילי\u0004 (זמורות) \u0003ענבים, יינות שמנים וסלתות\u0004 (בתוך צנצנות זכוכית) \u0003ועטרות שבלים\u0004 (זרים של שבלים) — \u0003אסור להסתפק\u0004 (ליהנות) מכל אלה \u0003עד מוצאי יום טוב האחרון של\u0004 ה\u0003חג. ואם התנה עליהם\u0004 שיהיה רשאי להשתמש בהם — \u0003הכל לפי תנאו.\u0004 משמע שאפילו בסוכה של מצוה, אפשר להשתמש על ידי תנאי!","ומשיבים, \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 דבר זה \u0003באומר\u0004 על כל אלה: \u0003איני בודל מהם כל בין השמשות.\u0004 כלומר, מודיע מראש שעוד בין השמשות של תחילת החג אין כוונתו לבדול מהם ולהקדישם לצורך נוי הסוכה, אלא עתיד הוא להשתמש בהם אף לצורך אחר, שעל ידי כך \u0003לא חלה קדושה עלייהו\u0004 \u0005[עליהם]\u0006 כלל מתחילת החג, ולכן יכול להשתמש בהם כל החג. \u0003אבל עצי סוכה\u0004 עצמם ש\u0003חלה קדושה עלייהו\u0004 \u0005[עליהם]\u0006 מעצם בניינה — \u0003אתקצאי לשבעה\u0004 \u0005[הוקצו\u0006 משימוש כל \u0005שבעת\u0006 הימים\u0005].\u0006","ושואלים: \u0003ומאי שנא מהא דאתמר\u0004 \u0005[ובמה שונה\u0006 הדבר \u0005ממה שנאמר]\u0006 לענין הלכה אחרת: מי ש\u0003הפריש שבעה אתרוגים לשבעת הימים\u0004 של חג, שבכל יום ישתמש באתרוג אחר, \u0003אמר רב: כל אחת ואחת יוצא בה\u0004 כאשר מברך על הלולב והאתרוג \u0003ואוכלה\u0004 אם רוצה \u0003לאלתר\u0004 \u0005[מיד]\u0006 לאחר הברכה. \u0003ורב אסי אמר: כל אחת יוצא בה ואוכלה למחר,\u0004 משום שחלה עליה קדושה עד סוף היום. מכל מקום, לדעת הכל אם חלה קדושה על האתרוג ליום אחד אינה נמשכת ליום השני, ומדוע בסוכה חלה הקדושה כל שבעת הימים!","ומשיבים: יש לחלק בין אתרוג וסוכה, \u0003התם\u0004 \u0005[שם]\u0006 בענין אתרוג \u0003דמפסקו\u0004 \u0005[שמופסקים]\u0006 ה\u0003לילות מימים\u0004 שמצות אתרוג היא רק ביום ולא בלילה, על כן \u0003כל חד וחד יומא\u0004 \u0005[כל יום ויום]\u0006 \u0003מצוה באפי נפשיה\u0004 \u0005[בפני עצמה]\u0006 \u0003הוא,\u0004 ולכן המוקדש ליום אחד אינו מוקדש לשני, אולם \u0003הכא דלא מפסקו\u0004 \u0005[כאן שאין מופסקים]\u0006 \u0003לילות מימים,\u0004 שהרי מצות הסוכה ישנה בלילה כביום, לכן \u0003כולהו יומי כחדא יומא אריכתא דמי\u0004 \u0005[כל\u0006 שבעת \u0005הימים נחשבים כיום אחד ארוך],\u0006 ואין רגע שתתבטל קדושת הסוכה מן העצים עד סוף החג."],["\u0003מביאין עצים\u0004 שנקצצו מבעוד יום \u0003מן השדה\u0004 שאינה גדורה, דווקא \u0003מן המכונס,\u0004 שאם היו כנוסים בערמה מערב יום טוב לצורך זה — מותר להביאם להיסק ביום טוב, אבל עצים מפוזרים הינם מוקצה ואסור להביא מהם. \u0003ו\u0004אם מביא \u0003מן הקרפף\u0004 (כעין חצר גדורה שבה מאחסנים דברים) — יכול להביא \u0003אפילו מן המפוזר,\u0004 מפני שאינו כשדה אלא כחצר המשתמרת, שאין אדם מקצה מדעתו דברים המונחים בה, אפילו כשהם מפוזרים. ומסבירים: \u0003איזהו קרפף\u0004 — \u0003כל שסמוך לעיר,\u0004 אבל אם רחוק מן העיר — נחשב כשדה, אלו \u0003דברי ר' יהודה. ר' יוסי אומר: כל\u0004 מקום שהוא סגור בגדר \u0003שנכנסין לו בפותחת\u0004 (במפתח) ואי אפשר להכנס בלא זה — הרי זה קרפף, \u0003ואפילו\u0004 היה רחוק מן העיר. כל עוד הוא \u0003בתוך תחום שבת.\u0004","\u0003אמר רב יהודה אמר שמואל: אין מביאין עצים אלא מן\u0004 העצים \u0003המכונסין שבקרפף.\u0004 ומקשים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במפורש במשנתנו\u0005]\u0006 \u0003מן הקרפף ואפילו מן המפוזרים!\u0004 ומשיבים: \u0003מתניתין יחידאה\u0004 \u0005[משנתנו\u0006 כדעת \u0005יחיד]\u0006 \u0003היא\u0004 ואין לסמוך עליה, לפי שממקור אחר אנו למדים שדעת הרבים לא היתה כן.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' שמעון בן אלעזר: לא נחלקו בית שמאי ובית הלל על\u0004 העצים \u0003המפוזרים שבשדות שאין מביאין\u0004 אותם ביום טוב אל הבית לצורך הסקה, \u0003ועל\u0004 העצים \u0003המכונסין בקרפף שמביאין. על מה נחלקו\u0004 — \u0003על המפוזרין שבקרפף ועל המכונסין שבשדות, שבית שמאי אומרים: לא יביא, ובית הלל אומרים: יביא.\u0004 משמע שהיתר זה להביא מעצים מכונסים שבשדה הוא לשיטת בית הלל אבל רק כדעתו של תנא יחיד, ר' שמעון בן אלעזר, ורוב החכמים חלקו עליו וסוברים שמן השדה אסור להביא כלל, אפילו לדעת בית הלל.","\u0003אמר רבא: עלי קנים ועלי גפנים, אף על גב דמכנפי להו ומותבי\u0004 \u0005[אף על פי שאוספים אותם\u0006 יחד \u0005ומושיבים,\u0006 מניחים, אותם במקום אחד\u0005],\u0006 \u0003כיון דאי מדלי זיקא מבדר להו\u0004 \u0005[שאם תבוא הרוח תפזר אותם]\u0006 — \u0003כמפוזרים\u0004 כבר \u0003דמו\u0004 \u0005[נחשבים]\u0006 הם \u0003ואסורין,\u0004 שמתוך שחושש שמא יתפזרו מחמת הרוח לא סמכה דעתו עליהם. אולם \u0003ואי אתנח מנא\u0004 \u0005[ואם הניח כלי]\u0006 \u0003מאתמול עלייהו\u0004 \u0005[עליהם]\u0006 שלא יתפזרו ברוח — \u0003שפיר דמי\u0004 \u0005[יפה הדבר],\u0006 ומותר.","במשנה נדונה השאלה \u0003איזהו קרפף. אבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים שאלה זו\u0005]:\u0006 \u0003היכי קאמר\u0004 \u0005[כיצד אמר]\u0006 מה מובן הדברים במשנה, האם כוונתו לומר \u0003כל שסמוך לעיר, והוא דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003פותחת\u0004 (מפתח), שאם לא כן אינו קרפף כלל, \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' יוסי למימר\u0004 \u0005[לומר]:\u0006 \u0003כיון דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003פותחת\u0004 — \u0003אפילו\u0004 אינו סמוך לעיר, אולם עדיין הוא נכלל \u0003בתוך תחום שבת נמי\u0004 \u0005[גם כן],\u0006 ולפי זה ר' יוסי חלק רק להקל על דברי ר' יהודה.","\u0003או דלמא הכי קאמר\u0004 \u0005[שמא כך אמר]\u0006 וכך יש להבין את דברי ר' יהודה: \u0003כל ש\u0004הוא \u0003סמוך לעיר\u0004 — הריהו קרפף, \u0003בין דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003פותחת, בין דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003פותחת, ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' יוסי למימר\u0004 \u0005[לומר]:\u0006 לגבי המרחק — \u0003אפילו\u0004 כשאינו סמוך לעיר, אם הוא \u0003בתוך תחום שבת\u0004 הריהו קרפף, \u0003ודוקא דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003פותחת, אבל לית ליה\u0004 \u0005[אין לו]\u0006 \u0003פותחת\u0004 — \u0003אפילו\u0004 כשהוא \u0003סמוך לעיר, נמי\u0004 \u0005[גם כן]\u0006 \u0003לא,\u0004 שר' יוסי אינו מיקל דווקא, אלא תולה את ההיתר בטעם אחר.","ומביאים ראיה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 \u0003מדקתני\u0004 \u0005[ממה ששנינו\u0006 במשנתנו\u0005],\u0006 \u0003ר' יוסי אומר: כל שנכנסין לו בפותחת ואפילו בתוך תחום שבת.\u0004 שכיון שלא אמר \"אם נכנסין\" אלא \"כל שנכנסין\" משמע שלא בפותחת כל כך תלוי הדבר \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003ר' יוסי תרתי לקולא קאמר\u0004 \u0005[שני\u0006 דברים \u0005להקל אמר].\u0006 וכל דבריו באו להקל מדברי ר' יהודה, ולא להחמיר בשום צד. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא. \u0003אמר רב סלא אמר ר' ירמיה: הלכה כר' יוסי להקל,\u0004 כלומר כך יש להבין, וכדבריו יש לפסוק.","\u0003אין מבקעין עצים לא מן הקורות\u0004 המונחות לצרכי בנין \u0003ולא מן הקורה שנשברה ביום טוב,\u0004 אף שאינה משמשת עוד לכלום. \u0003ואין מבקעין\u0004 עצים \u0003לא בקרדום ולא במגרה\u0004 (במשור) \u0003ולא במגל,\u0004 שכל אלה הם כלי אומנות מובהקים, וכן הדרך לעשות ביום חול \u0003אלא בקופיץ\u0004 (סכין גדולה של קצבים) שיש בכך שינוי גדול מדרך עשייתו בימות החול."],["על לשון המשנה תוהים: \u0003והאמרת רישא\u0004 \u0005[והרי אמרת בתחילה]\u0006 \u0003אין מבקעין\u0004 קורות \u0003כלל\u0004 ולכאורה טעם האיסור הוא משום טירחה יתירה ביום טוב, ואם כן מדוע מפרש בסוף כיצד מבקעים ואף התיר בקופיץ? \u0003אמר רב יהודה אמר שמואל: חסורי מחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך\u0006 יש \u0005לשנותה]:\u0006 \u0003אין מבקעין\u0004 קורות \u0003מן הסואר של קורות\u0004 (מערימת קורות) המונחות לצורך בנין, \u0003ולא מן הקורה שנשברה ביום טוב\u0004 עצמו, משום שהיא בגדר מוקצה. \u0003אבל מבקעין מן הקורה שנשברה מערב יום טוב\u0004 שודאי עומדת להסקה ולא הקצה אותה מדעתו.","אולם אף \u0003כשהן מבקעין\u0004 את הקורה הזו — אין לבוקעה כדרך ביקועה בימות החול, אלא בשינוי, ולכן \u0003אין מבקעין לא בקרדום ולא במגל ולא במגרה אלא בקופיץ.\u0004 ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 כדברי שמואל: \u0003אין מבקעין עצים לא מן הסואר של קורות, ולא מן הקורה שנשברה ביום טוב\u0004 עצמו, \u0003לפי שאינו מן המוכן.\u0004","שנינו במשנה שאף במקרה שמותר לבקע עצים ביום טוב — \u0003לא מבקעים ב\u0004אמצעות \u0003קרדום. אמר רב חיננא בר שלמיא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: לא שנו\u0004 איסור זה \u0003אלא\u0004 כשמבקע \u0003ב\u0004צד \u0003נקבות\u0004 (הרחב) \u0003שלו,\u0004 שהדרך לבקע עצים בצד זה, \u0003אבל\u0004 אם מבקע \u0003ב\u0004צד \u0003זכרות\u0004 (הצר) \u0003שלו,\u0004 שאין דרך לחתוך בו עצים — \u0003מותר.\u0004","ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן הדבר מאליו\u0005]\u0006 שדרך שינוי מותר, הלא \u0003בקופיץ תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 שמותר, וצד זכרות שבקרדום כעין קופיץ הוא! ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלו]\u0006 אמורים ב\u0003קופיץ לחודיה\u0004 \u0005[לחוד,\u0006 לעצמו\u0005]\u0006 שהוא צר משני צידיו, \u0003אבל\u0004 כלי שמצידו האחד הוא \u0003קרדום ו\u0004מצידו השני הוא \u0003קופיץ, אימא\u0004 \u0005[אמור]:\u0006 \u0003מגו דהאי גיסא\u0004 \u0005[מתוך שצד זה]\u0006 הרחב יותר, \u0003אסור\u0004 — \u0003האי גיסא נמי\u0004 \u0005[צד זה,\u0006 הצר יותר \u0005גם כן]\u0006 \u0003אסור,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהצד הצר (צד הקופיץ שבו), מכל מקום מותר.","\u0003ואיכא דמתני לה אסיפא\u0004 \u0005[ויש ששנו את\u0006 ההלכה \u0005הזו על סופה]\u0006 של המשנה. כיצד, נאמר שם: \u0003אלא בקופיץ. אמר רב חיננא בר שלמיא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: לא שנו\u0004 שהותר ביקוע עצים ביום טוב (כשנשברו מאתמול, כאמור) \u0003אלא\u0004 כשמבקע אותם \u0003ב\u0004צד \u0003זכרות\u0004 (הצר) \u0003שלו, אבל\u0004 אם מבקע \u0003ב\u0004צד \u0003נקבות\u0004 (הרחב) \u0003שלו\u0004 — \u0003אסור.\u0004 ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 הלא \u0003ולא בקרדום תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 ומה ההבדל בין קופיץ זה לקרדום? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים \u0003בקרדום\u0004 שהוא רחב משני צידיו, \u0003אבל\u0004 זה שהוא \u0003קופיץ וקרדום\u0004 גם יחד, שצידו האחד רחב והשני צר, \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003מגו דהאי גיסא שרי\u0004 \u0005[מתוך שצד זה,\u0006 הצר, \u0005מותר]\u0006 — \u0003האי גיסא נמי שרי\u0004 \u0005[צד זה,\u0006 הרחב, \u0005גם כן מותר],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא התירו צד אחד משום השני.","\u0003בית שהוא מלא פירות\u0004 ונעול מכל צד \u0003ונפחת\u0004 (נעשה בו חור) מאליו — \u0003נוטל\u0004 פירות \u0003ממקום הפחת\u0004 ואין אומרים שהפירות הם מוקצים, לפי שלא יכול היה לקחתם בלא לעשות חור. \u0003ר' מאיר אומר: אף פוחת\u0004 את הבנין \u0003לכתחלה ונוטל\u0004 ממנו פירות.","על דברי ר' מאיר תוהים: \u0003אמאי\u0004 \u0005[מדוע],\u0006 כיצד התיר לפחות את הבית מלכתחילה כדי ליטול פירות? \u0003והא קא סתר אהלא\u0004 \u0005[והרי הוא סותר אהל]\u0006 ועובר על איסור מלאכה מן התורה! \u0003אמר רב נחומי בר אדא אמר שמואל:\u0004 מדובר כאן \u0003באוירא דליבני\u0004 \u0005[בלבנים\u0006 המונחות \u0005זו על גבי זו]\u0006 בלא חיבור טיט באמצע, שאינן נחשבות כלל כבנין. ומקשים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן: הני ליבני דאייתור מבנינא\u0004 \u0005[אותן לבנים שנשארו מן הבנין]\u0006 — \u0003שרי לטלטולינהו בשבתא\u0004 \u0005[מותר לטלטלן בשבת]\u0006 \u0003הואיל וחזי למזגא עלייהו\u0004 \u0005[וראויות לשבת עליהן],\u0006 ולכן יכול לטלטלן ממקום למקום. אולם אם \u0003שרגינהו\u0004 \u0005[אם סידר אותן\u0006 בשורות זו על זו\u0005]\u0006 — \u0003ודאי אקצינהו\u0004 \u0005[הקצה אותן]\u0006 מדעתו. נמצא שאף לבנים המסודרות זו על גבי זו בלא חיבור טיט, מוקצות הן!","\u0003אמר ר' זירא:\u0004 ר' מאיר מדבר מענין יום טוב ו\u0003ביום טוב\u0004 אכן \u0003אמרו\u0004 להתיר באופן זה, \u0003אבל לא\u0004 התירו \u0003בשבת\u0004 אפילו באופן זה, ורב נחמן מדבר מענין שבת. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 במפורש, \u0003ר' מאיר אומר: אף פוחת\u0004 ביום טוב \u0003לכתחלה\u0004 את לבני הבית \u0003ונוטל\u0004 פירות מתוכו. ודבר זה \u0003ביום טוב אמרו, אבל לא בשבת.\u0004","\u0003אמר שמואל: חותמות שבקרקע,\u0004 כלומר: דלתות של מרתפים ומערות הצמודות לקרקע וקשורות בחבלים — \u0003מתיר\u0004 את הקשר, \u0003אבל לא מפקיע\u0004 את החבל עצמו לחלקיו הקטנים שמהם נשזר, \u0003ולא חותך\u0004 את החבל, שהרי זוהי סתירה ויש איסור סתירת בבנין (של המרתף והמערה) בשבת. חותמות \u0003שב\u0004פתחי ה\u0003כלים,\u0004 כגון חבלים הקושרים את דלתות הארון ונועלים את פיו — \u0003מתיר ומפקיע וחותך\u0004 אם צריך לכך, שאין סתירה בכלים, \u0003אחד\u0004 ב\u0003שבת ואחד\u0004 ב\u0003יום טוב.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 מן הברייתא, ששנינו בה: \u0003חותמות שבקרקע, בשבת\u0004 — \u0003מתיר אבל לא מפקיע ולא חותך,\u0004 שאף שמן התורה הדבר מותר, אסרוהו חכמים. אולם \u0003ביום טוב\u0004 — \u0003מתיר ומפקיע וחותך,\u0004 שאף מדברי סופרים אין לאוסרו, וקשה אם כן לדברי שמואל שאינו מחלק!","ומשיבים: \u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר: אף פוחת לכתחלה ונוטל, ופליגי רבנן עליה\u0004 \u0005[וחלקו חכמים עליו]\u0006 ואסרוהו, \u0003ואנא דאמרי כרבנן\u0004 \u0005[ואני שאמרתי\u0006 את דברי \u0005כ\u0006שיטת \u0005חכמים]\u0006 אומר אני אותם. ושואלים: \u0003ומי פליגי רבנן עליה\u0004 \u0005[והאם חלוקים חכמים עליו]\u0006 \u0003בחותמות שבקרקע? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מודים חכמים לר' מאיר בחותמות שבקרקע, שבשבת מתיר אבל לא מפקיע ולא חותך, וביום טוב מתיר ומפקיע וחותך!\u0004"],["ומשיבים: שמואל \u0003הוא\u0004 ש\u0003אמר\u0004 את דבריו \u0003כי האי תנא\u0004 \u0005[כ\u0006שיטת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חותמות שבקרקע\u0004 — \u0003מתיר, אבל לא מפקיע ולא חותך, אחד שבת ואחד יום טוב. ושבכלי\u0004 — \u0003בשבת מתיר, אבל לא מפקיע ולא חותך,\u0004 ו\u0003ביום טוב\u0004 — \u0003מתיר ומפקיע וחותך.\u0004","ושבים ומקשים: \u0003תרצת לך רישא\u0004 \u0005[תירצת\u0006 על ידי כך \u0005את ראשה]\u0006 תחילת דברי שמואל לגבי חותמות שבקרקע, שמצאנו חכם המתיר בענין זה, שדעתו כדברי שמואל. \u0003אלא סיפא קשיא\u0004 \u0005[הסוף קשה],\u0006 שהרי בברייתא נאמר שבשבת אסור להפקיע אפילו חבלים שבכלים, ואילו שמואל מתיר בכל מקרה!","ומשיבים: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 לגבי כלים כשיטת \u0005מי היא]\u0006 — לא כדעת כל החכמים אלא דעת יחיד היא, ודעת \u0003ר' נחמיה היא,\u0004 ש\u0003אמר: כל הכלים אין ניטלין אלא דרך תשמישן\u0004 המיוחד להם, ולכן אי אפשר לחתוך את החבל לא משום איסור הפקעת החבל (שאכן אין בכך משום סתירה), אלא לחותכו משום שאסור לטלטל לשם כך את הסכין, כיון שתשמישה המיוחד לא לחיתוך חבלים, אלא לחתוך בה דברי מאכל.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 כדעת \u0003ר' נחמיה\u0004 היא, אם כן \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 איסור זה דווקא \u0003בשבת? אפילו יום טוב נמי\u0004 \u0005[גם כן]\u0006 יהא בו דין זה, שהרי אין לחלק באיסור טלטול זה בין שבת ליום טוב! \u0003וכי תימא שניא ליה\u0004 \u0005[ואם תאמר כי שונה לו]\u0006 \u0003לר' נחמיה בין שבות\u0004 (איסור שמדברי סופרים) ב\u0003שבת\u0004 שאסר לטלטל את הכלי אלא לצורכו המיוחד \u0003לשבות יום טוב,\u0004 אולם \u0003ומי שניא ליה\u0004 \u0005[האם\u0006 אכן \u0005שונה\u0006 הדבר \u0005בעיניו]?\u0006","\u0003והתני חדא\u0004 \u0005[הרי שנויה\u0006 בברייתא \u0005אחת]:\u0006 \u0003מסיקים\u0004 ביום טוב \u0003בכלים ואין מסיקין בשברי כלים\u0004 לפי שהם מוקצים משימוש, \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003מסיקין בין בכלים בין בשברי כלים, ותניא אידך\u0004 \u0005[ושנויה\u0006 עוד ברייתא \u0005אחרת]\u0006 האומרת: \u0003אין מסיקין לא בכלים ולא בשברי כלים.\u0004","ואת הסתירה הזו בין הברייתות \u0003משני\u0004 \u0005[מתרצים כך]:\u0006 \u0003לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 הראשונה היא כדעת \u0003ר' יהודה\u0004 הסובר שיש מוקצה, ולכן כלים אינם מוקצים — ויכול להסיק בהם, אולם שברי כלים מוקצים הם, ואסורים בטלטול ולכן אין להסיק בהם. \u0003הא\u0004 \u0005[זו]\u0006 השניה, \u0003ר' שמעון\u0004 היא, שאינו סובר דין מוקצה, ומותר לדעתו לטלטל ולהשתמש גם בשברי כלים. \u0003הא\u0004 \u0005[זו]\u0006 שאוסרת גם בכלים שלמים — כדעת \u0003ר' נחמיה\u0004 היא, המתיר שימוש בכלים רק לצורך תשמישם המיוחד. ולענייננו משמע שר' נחמיה אוסר גם ביום טוב!","ומתרצים: \u0003תרי תנאי\u0004 \u0005[שני תנאים\u0006 הם\u0005]\u0006 \u0003ואליבא\u0004 \u0005[ועל פי שיטתו]\u0006 של \u0003ר' נחמיה,\u0004 ששניהם מסכימים לאסור שימוש בכלים שלא לתפקידם המיוחד, אלא נחלקו אם דין זה חל ביום טוב כבשבת, שיש מי שאוסר ויש מי שמתיר.","\u0003אין פוחתין\u0004 ביום טוב \u0003את הנר,\u0004 כלומר: אין לוקחים חתיכת טיט ועושים בתוכה חלל שישמש כנר לשים בו שמן ופתילה, \u0003מפני שהוא עושה כלי\u0004 על ידי מעשה זה, \u0003ו\u0004כן \u0003אין עושין\u0004 בכלל \u0003פחמין ביום טוב,\u0004 מפני שזו היא מלאכת עבודה. \u0003ואין חותכין את הפתילה\u0004 שאף זה בכלל תיקון כלי. \u0003ר' יהודה אומר:\u0004 אם צריך פתילה בגודל מסויים — \u0003חותכה באור\u0004 (באש) ולא על ידי סכין.","\u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 שסבור ש\u0003פחיתת נר\u0004 עשיית \u0003מנא\u0004 \u0005[כלי]\u0006 \u0003הוא\u0004 גם אם לא נשרף בכבשן? \u0003אמר רב יוסף:\u0004 שיטת \u0003ר' מאיר היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בדיני טומאה: \u0003כלי חרס, מאימתי מקבל טומאה\u0004 — \u0003משנגמרה מלאכתו,\u0004 כלומר משנגמר עיצוב החימר לצורת הכלי, אלו \u0003דברי ר' מאיר. ר' יהושע אומר: משיצרפו\u0004 את הכלי \u0003בכבשן.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ממאי\u0004 \u0005[ממה]\u0006 מסיק אתה שיש כאן שיטה אחת? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[שאמר]\u0006 \u0003ר' מאיר התם\u0004 \u0005[שם]\u0006 לגבי כלים \u0003אלא דחזי לקבולי ביה מידי\u0004 \u0005[שראוי להחזיק בהם דבר]\u0006 שאף שקודם צריפתם בכבשן אינם ראויים להחזיק בהם נוזלים, מכל מקום יכול להחזיק בהם חומרים אחרים, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003למאי חזי\u0004 \u0005[למה ראוי]\u0006 נר זה, ומה שימוש אפשר לעשות בו? ומשיבים: כלי זה ראוי \u0003לקבולי ביה פשיטי\u0004 \u0005[להחזיק בתוכו מעות\u0006 קטנות\u0005].\u0006","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שכך היה נוסח הדברים, \u0003אמר רב יוסף:\u0004 כשיטת \u0003ר' אליעזר בר' צדוק היא\u0004 משנתנו, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אלפסין חרניות\u0004 (קערות שלא נגמרה מלאכתן כעין קדירות חרס שיוצרים אותן ביחד עם המכסה, ומסירים את המכסה לאחר צריפתן) — \u0003טהורות\u0004 מלטמא \u0003באהל המת\u0004 לפי שאין להן בית קיבול, ואין טומאת מת חלה אלא על כלי חרס שיש בו חלל, אולם \u0003טמאות\u0004 הן \u0003במשא הזב\u0004 ובהיסטו, לפי שהן ראויות לשימוש כלשהו, ולענין טומאה זו אף כלי חרס נטמא.","\u0003ר' אליעזר בר' צדוק אומר: אף טהורות במשא הזב, לפי שלא נגמרה מלאכתן,\u0004 כלומר: שלא נגמרה מלאכת עיצוב תבנית הכלי. ומדברים אלה נוכל ללמוד כי כלי חרס שנגמרה מלאכתו וכבר נתעצבה צורתו ככלי גמור, אף שלא נצרף בכבשן — דינו כדין כלי גמור.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: דלמא\u0004 \u0005[שמא]\u0006 לא כן, ונאמר כי \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[שאמר]\u0006 \u0003ר' אליעזר בר' צדוק התם\u0004 \u0005[שם]\u0006 בענין אלפסין חרניות \u0003אלא דחזי לקבולי ביה מידי\u0004 \u0005[שראוי\u0006 להחזיק, \u0005לקבל בתוכו דבר מה],\u0006 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 הנר \u0003למאי חזי\u0004 \u0005[למה\u0006 הוא \u0005ראוי]?\u0006 ומשיבים: \u0003לקבולי ביה פשיטי\u0004 \u0005[לקבל בתוכו מטבעות\u0006 קטנות\u0005].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין פוחתין את הנר ואין עושין אלפסין חרניות ביום טוב. רבן שמעון בן גמליאל מתיר באלפסין חרניות.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003חרניות? אמר רב יהודה: ערניות\u0004 (של עיר, בעצם: עיירה). ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003ערניות\u0004 בלשון בבל? \u0003אמר אביי: צעי חקלייתא\u0004 \u0005[קערות של כפריים]\u0006 שמשתמשים אף בכלי חימר שלא נצרפו ואין מקפידים שתיגמר מלאכתם.","שנינו במשנה: \u0003ואין עושין פחמין\u0004 ביום טוב. ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שאסור לעשות מלאכת עבודה, כי \u0003למאי חזי\u0004 \u0005[למה ראויים]\u0006 הפחמים לצורך אוכל נפש ביום טוב? \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: לא נצרכה אלא למוסרן לאוליירין\u0004 (בלנים) המחממים את המרחץ \u0003לבו ביום,\u0004 שיכולים היינו לחשוב שכיון שהוא לצורך רחיצת החג — מותר.","ושואלים: \u0003ובו ביום מי שרי\u0004 \u0005[האם מותר]\u0006 לחמם מים לרחיצה? והרי גזרו חכמים שלא ירחצו במרחץ ביום טוב ואפילו נתחממו מימיו מבעוד יום, וכל שכן אם נתחממו ביום טוב עצמו! ומתרצים: \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003רבא\u0004 לענין אחר, שאין מדובר שם לרחוץ ממש, אלא \u0003להזיע\u0004 להכנס למרחץ כדי להזיע בלבד, \u0003וקודם\u0004 ה\u0003גזרה\u0004 שאסרו אף על ההזעה במרחץ. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אפשר לפרש שמדובר היה בענין \u0003להזיע וקודם\u0004 ה\u0003גזרה.\u0004","שנינו במשנה \u0003שאין חותכין את הפתילה לשנים,\u0004 ור' יהודה מתיר לחותכה באור (באש). ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה],\u0006 מדוע \u0003בסכין דלא\u0004 \u0005[שאין]\u0006 חותכים פתילה"],["— משום \u0003דקמתקן מנא\u0004 \u0005[ש\u0006על ידי כך \u0005הוא מתקן כלי],\u0006 ואם כן \u0003באור נמי קא מתקן מנא\u0004 \u0005[באש גם כן הוא מתקן כלי]!\u0006 \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא\u0004 לבאר: \u0003חותכה באור בפי שתי נרות.\u0004 כלומר: אין חותך את הפתילה להתקינה לעצמה, אלא מכניס פתילה ארוכה בתוך שני נרות ומדליק את האש באמצע, ועל ידי כך נוצרות אמנם שתי פתילות נפרדות, אך דבר זה נעשה אגב הדלקת שני נרות. \u0003אמר רב נתן בר אבא אמר רב: מוחטין את הפתילה ביום טוב.\u0004 המלה \"מוחטין\" לא היתה מובנת, ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש המלה\u0005]\u0006 \u0003\"מוחטין\"? אמר רב חנינא בר שלמיא: לעדויי חושכא\u0004 \u0005[להסיר את החושך],\u0006 כלומר: מותר להסיר את החלק המפוחם, השרוף, כדי שיאיר אור הנר יותר.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003בר קפרא: ששה דברים נאמרו ב\u0004דיני \u0003פתילה\u0004 ביום טוב, \u0003שלשה\u0004 מהם \u0003להחמיר ושלשה\u0004 אחרים \u0003להקל.\u0004 שלושת הדברים \u0003להחמיר: אין גודלין\u0004 (טווים, פותלים) \u0003אותה לכתחלה ביום טוב, ואין מהבהבין אותה\u0004 (חורכים אותה מעט) \u0003באור\u0004 קודם הדלקתה כדי שתבער יפה, \u0003ואין חותכין אותה לשנים.\u0004 ושלושת הדברים \u0003להקל: ממעכה ביד,\u0004 שאף שאסור לגודלה, מותר מכל מקום לעצב את צורתה כלאחר יד, \u0003ושורה בשמן\u0004 כדי שתבער יפה אחר כך, \u0003וחותכה באור\u0004 (באש) \u0003בפי שתי נרות.\u0004","כיון שהזכרנו דבר בשם רב נתן בר אבא מביאים דברים נוספים שנאמרו בשמו. שמאחר שאין שמו נזכר הרבה, צרפו כמה מדבריו כדי להזכירם. וכך מסרו, \u0003אמר רב נתן בר אבא אמר רב: עתירי\u0004 \u0005[עשירי]\u0006 \u0003בבל, יורדי גיהנם הם.\u0004 לפי שאינם מרחמים על הבריות. \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 שהיה ב\u0003שבתאי בר מרינוס אקלע\u0004 \u0005[\u0006ש\u0005הזדמן]\u0006 \u0003לבבל, בעא מנייהו עסקא\u0004 \u0005[בקש מהם\u0006 לעשות עמו \u0005עסקה],\u0006 כלומר, שילוו לו כסף והוא יתעסק בו ויתן להם מחצית מן הרווחים — \u0003ולא יהבו ליה\u0004 \u0005[נתנו לו].\u0006 ואולם כשביקש מהם \u0003מזוני מיזן\u0004 \u0005[שיזונו אותו במזונות]\u0006 — \u0003נמי לא זינוהו\u0004 \u0005[\u0006ו\u0005גם כן לא זנוהו,\u0006 לא פירנסוהו\u0005],\u0006","\u0003אמר: הני\u0004 \u0005[אלה],\u0006 אותם עשירים, אינם מזרע האבות אלא \u0003מערב רב קאתו\u0004 \u0005[הם באו]!\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ונתן לך רחמים ורחמך\u0004 והרבך כאשר נשבע לאבותיך\" (דברים יג, יח), ודרשו מכאן: \u0003כל המרחם על הבריות\u0004 — \u0003בידוע שהוא מזרעו של אברהם אבינו, וכל מי שאינו מרחם על הבריות\u0004 — \u0003בידוע שאינו מזרעו של אברהם אבינו.\u0004 ואלה, עשירי בבל, שאינם מרחמים — משמע שאינם מבני אברהם יצחק ויעקב.","ועוד \u0003אמר רב נתן בר אבא אמר רב: כל המצפה על שלחן אחרים\u0004 להתפרנס מהם — \u0003עולם חשך בעדו,\u0004 שהכל נראה לו כחושך וכמחוסר תקווה. \u0003שנאמר: \"נדד הוא ללחם איה ידע כי נכון בידו יום חשך\"\u0004 (איוב טו, כג). \u0003רב חסדא אמר: אף חייו אינן חיים,\u0004 כלומר: אין בהם טעם.","ולחיזוק אימרה זו מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003שלשה, חייהן אינם חיים. ואלו הן: המצפה לשלחן חבירו\u0004 להתפרנס ממנו, \u0003ומי שאשתו מושלת עליו, ומי שיסורין מושלין בגופו. ויש אומרים: אף מי שאין לו אלא חלוק אחד\u0004 שאינו יכול לכבסו כראוי, וסובל מחמת הכינים והליכלוך. ומעירים, \u0003ותנא קמא,\u0004 שלא מנה דבר זה, סבור: \u0003אפשר דמעיין במניה\u0004 \u0005[אפשר\u0006 לו \u0005שיבדוק בבגדיו]\u0006 ויוציא מהם את הכינים ולא יסבול כל כך.","\u0003אין שוברין\u0004 ביום טוב \u0003את החרס, ואין חותכין\u0004 את \u0003הנייר לצלות בו מליח.\u0004 שמניח את החרסים השבורים או את חתיכות הנייר לאחר שמרטיבם במים על ברזל השבכה או התנור שצולה עליהם, כדי שלא ישרף הדג מן החום.","\u0003ואין גורפין תנור וכירים\u0004 מן הטיח או דבר אחר שנפל לתוכם ומפריע במלאכת האפייה, \u0003אבל מכבשין\u0004 (לוחצים ומיישרים) את האפר והעפר שבקרקעית התנור, כדי שלא יפריע להסקה אחרת.","\u0003ואין מקיפין\u0004 (סומכים יחד) \u0003שתי חביות\u0004 כדי \u0003לשפות\u0004 (להניח) \u0003עליהן את הקדרה\u0004 שתתבשל על האש שמדליקים בין החביות, \u0003ואין סומכין את הקדרה\u0004 שאינה עומדת ישר \u0003בבקעת\u0004 (בחתיכת עץ) כדי שלא תיפול, \u0003וכן\u0004 אסור לעשות כן \u0003בדלת,\u0004 כדי שלא תתמוטט. \u0003ואין מנהיגין את הבהמה במקל\u0004 ברשות הרבים \u0003ביום טוב, ור' אלעזר בר' שמעון מתיר.\u0004","לגבי ענין שבירת החרס וחיתוך הנייר מסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 האיסור — \u0003משום דקא מתקן מנא\u0004 \u0005[ש\u0006על ידי כן \u0005הוא כמתקן כלי].\u0006","\u0003\"ואין גורפין תנור וכירים\". תני\u0004 \u0005[שנה]\u0006 \u0003רב חייא בר יוסף קמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן: ואם אי אפשר לאפות אלא אם כן גורפו\u0004 — \u0003מותר.\u0004 מסופר: \u0003דביתהו\u0004 \u0005[אשתו]\u0006 של \u0003ר' חייא נפל לה אריחא בתנורא ביומא טבא\u0004 \u0005[אריח,\u0006 חלק של לבינה, \u0005בתוך התנור ביום טוב]\u0006 והפריע לאפיה בו, \u0003אמר לה ר' חייא: חזי, דאנא רפתא מעלייתא בעינא\u0004 \u0005[ראי,\u0006 דעי לך, \u0005שאני לחם מעולה אני רוצה]\u0006 ורמז לה שמותר להוציא את הלבינה משם. כיוצא בו \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לשמעיה\u0004 \u0005[לשמשו]:\u0006 \u0003טוי לי בר אווזא\u0004 \u0005[צלה לי ברווז]\u0006 בתנור \u0003ואזדהר מחרוכא\u0004 \u0005[והזהר מלחרוך\u0006 אותו\u0005],\u0006 שרמז לו שלצורך זה מותר להוציא את כל הדברים המפריעים המצויים בתנור.","ועוד בדברים דומים \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: אמר לן\u0004 \u0005[לנו]\u0006 \u0003רב אחא מהוצל, דמר\u0004 \u0005[שאדוני],\u0006 רב אשי, \u0003שרקין ליה תנורא ביומא טבא\u0004 \u0005[טחים לו\u0006 בטיט את פי \u0005התנור ביום טוב].\u0006 שהיו סותמים בטיט את התנור כדי שיהא הצלי או התבשיל מבושל כל צרכו. וכיצד עושים דבר שיש בו משום מלאכת לישה ביום טוב? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנן ארקתא דפרת סמכינן\u0004 \u0005[אנו על שפת\u0006 נהר \u0005פרת אנו סומכים]\u0006 ואין אנו צריכים לגבל טיט, אלא נוטלים עפר משפת הנהר, ועפר זה כבר מגובל די צורכו, ואין כאן משום מלאכת גיבול ולישה. ומעירים: \u0003והני מילי הוא דצייריה\u0004 \u0005[ודברים אלה\u0006 שמותר, \u0005אמורים\u0006 דווקא \u0005כאשר צרר]\u0006 או סימן את הטיט הזה \u0003מאתמול,\u0004 שאין בו משום מוקצה. \u0003אמר רבינא: וקטמא\u0004 \u0005[ו\u0006לגבל ב\u0005אפר]\u0006 לצורך זה — \u0003שרי\u0004 \u0005[מותר],\u0006 שאין באפר משום גיבול ולישה.","שנינו במשנה: \u0003אין מקיפין שתי חביות\u0004 כדי לשפות עליהן קדירה. \u0003אמר רב נחמן: אבנים\u0004 גדולות \u0003של בית הכסא,\u0004 שאדם יושב עליהן לעשות צרכיו \u0003מותר לצדדן\u0004 ולהעמידן בצורה הראוייה לייעודן \u0003ביום טוב. איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבה לרב נחמן:\u0004 הלא שנינו כי \u0003אין מקיפין\u0004 (מקרבים) \u0003שתי חביות\u0004 כדי \u0003לשפות עליהן את הקדרה,\u0004 ולכאורה נראה שכל העמדת דברים כעין בנין אסורה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 בחביות \u0003משום דקא עביד אהלא\u0004 \u0005[שהוא עושה אהל].\u0006 כלומר: הנחת הקדירה על גבי החביות יוצרת כעין כיסוי, ויצירת הכיסוי היא המחשיבה את הפעולה כעשיית אוהל, ולא העמדת החביות יחד.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה זוטא\u0004 \u0005[הקטן]\u0006 (להבדילו מרבה סתם), \u0003לרב אשי: אלא מעתה\u0004 מי ש\u0003בנה אצטבא ביום טוב\u0004 שהוא מקום מוגבה בלא גג, ש\u0003לא עביד אהלא\u0004 \u0005[עשה אהל],\u0006 \u0003הכי נמי דשרי\u0004 \u0005[כך גם כן תאמר שמותר],\u0006 כיון שלא עשה אהל? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אינו דומה; כי \u0003התם\u0004 \u0005[שם]\u0006 בבנין גמור כאיצטבא \u0003בנין קבע אסרה תורה.\u0004 ובכל אופן שבונה \u0003בנין עראי לא אסרה תורה.\u0004 אולם, \u0003גזרו רבנן\u0004 \u0005[חכמים]\u0006 \u0003על בנין עראי\u0004 לאסור עשייתו ביום טוב, \u0003משום בנין קבע,\u0004 אולם \u0003הכא\u0004 \u0005[כאן]\u0006 בבית הכסא \u0003משום כבודו\u0004 של המשתמש \u0003לא גזרו ביה רבנן\u0004 \u0005[בו חכמים].\u0006","\u0003אמר רב יהודה: האי מדורתא\u0004 \u0005[מדורה זו]\u0006 שעורכים בה את העצים בתבנית כעין בית, אם מסדר \u0003מלמעלה למטה\u0004 שקודם מחזיק בידו את העצים העליונים ומניח תחתם את העצים התחתונים — \u0003שרי\u0004 \u0005[מותר],\u0006 לפי שאין זו דרך בנין. אולם אם עושה כדרכו \u0003מלמטה למעלה\u0004 — \u0003אסור\u0004 משום בנין."],["\u0003וכן ביעתא\u0004 \u0005[ביצה]\u0006 אם רוצה להניח ביצים על פי כלי חלול או שבכה העומדת על גבי גחלים — יאחז את הכלי בידיו ויניח בתחילה את הביצים עליו ורק לאחר מכן יניחנו עם הביצים שעליו על גבי הגחלים, \u0003וכן קדרה\u0004 שמניחים אותה על גבי חביות — יאחז תחילה את הקדרה בידיו מעל גבי החביות ורק לאחר מכן יניח תחתיה את החביות. \u0003וכן פוריא\u0004 \u0005[מיטה]\u0006 מתפרקת שיש בה רגלים לחוד ומכסה לחוד. \u0003וכן חביתא\u0004 \u0005[חביות]\u0006 שמסדרים זו על זו,","שנינו במשנה: \u0003ואין סומכין את הקדרה בבקעת\u0004 (חתיכת עץ) \u0003וכן בדלת.\u0004 ושואלים: \u0003בדלת סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 וכי אפשר לסמוך קדירה בדלת? \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותקן את הלשון: \u0003וכן הדלת\u0004 אין סומכים אותה בבקעת. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין סומכין את הקדרה בבקעת, וכן הדלת, לפי שלא נתנו עצים אלא להסקה\u0004 ואין להשתמש בהם לצורך אחר, שדינם לכל דבר שאינו הסקה כמוקצה. \u0003ור' שמעון\u0004 שאינו סובר שיש איסור מוקצה — \u0003מתיר.\u0004","\u0003ואין מנהיגין את הבהמה במקל ביום טוב, ור' אלעזר בר' שמעון מתיר.\u0004 ושואלים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 ש\u0003ר' אלעזר בר' שמעון כאבוה\u0004 \u0005[כאביו]\u0006 ר' שמעון \u0003סבירא ליה\u0004 \u0005[סבור הוא]\u0006 \u0003דלית ליה\u0004 \u0005[שאין לו,\u0006 שאינו סובר\u0005]\u0006 דין \u0003מוקצה\u0004 ולכן לדעתו מותר ליטול מקל מכל מקום ולהנהיג בו את הבהמה? ודוחים: \u0003לא,\u0004 אין כאן ענין של מוקצה כלל, כי \u0003בהא\u0004 \u0005[\u0006בענין \u0005זה]\u0006 \u0003אפילו ר' שמעון מודה\u0004 לתנא הראשון שיש לאסור, ולא מטעם מוקצה אלא \u0003משום דמחזי כמאן דאזיל לחנגא\u0004 \u0005[שנראה כמי שהולך לשוק]\u0006 והוא דרך חול, לכן צריך לעשותו בשינוי ביום טוב.","\u0003חזרא,\u0004 כלומר: ליטול ענף דק של עץ החיזרא להשתמש בו בתור שפוד, \u0003רב נחמן אסר\u0004 משום מוקצה, כיון שלא עשאו כלי מבעוד יום, \u0003ורב ששת שרי\u0004 \u0005[התיר].\u0006 ומסבירים: \u0003ברטיבא\u0004 \u0005[ב\u0006ענף \u0005רטוב]\u0006 \u0003— כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ש\u0003אסור,\u0004 שהרי אינו ראוי להסקה, ואם כן מוקצה הוא. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 — ביבשתא \u0003[\u0004הרי זה \u0005ב\u0006ענף \u0005יבש].\u0006 \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אסר,\u0004 רב נחמן, \u0003אמר לך: לא נתנו עצים אלא להסקה,\u0004 ולכל צורך אחר הרי הם כמוקצה. \u0003ומאן דשרי\u0004 \u0005[ומי שהתיר]\u0006 \u0003אמר לך:\u0004 כיון שעשוי כל עץ לצלות בו — \u0003מה לי לצלות בו\u0004 כשהוא תחוב בתוך הבשר, \u0003מה לי לצלות בגחלתו?\u0004 והצלייה בגחלתו הלא מותרת ואף מותר לטלטלו לצורך זה!","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בהסבר מחלוקת זו בנוסח אחר: \u0003ביבשתא\u0004 \u0005[ב\u0006ענף \u0005יבש]\u0006 — \u0003כולי עלמא לא פליגי דשרי\u0004 \u0005[הכל אינם חלוקים שמותר],\u0006 \u0003כי פליגי ברטיבתא\u0004 \u0005[כאשר נחלקו\u0006 הרי זה \u0005ב\u0006ענף \u0005רטוב],\u0006 \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אסר,\u0004 סבור שהוא מפני \u0003דלא חזי\u0004 \u0005[שאינו ראוי]\u0006 \u0003להסקה, ומאן דשרי\u0004 \u0005[ומי שמתיר]\u0006 \u0003אמר לך: הא חזי\u0004 \u0005[הרי ראוי]\u0006 הוא על כל פנים \u0003להיסק גדול,\u0004 שאז יתיבש אף עץ זה ויוכל לבעור. ומסכמים; \u0003והלכתא\u0004 \u0005[\u0006ומסקנת \u0005ההלכה]:\u0006 \u0003יבשתא\u0004 \u0005[יבש]\u0006 \u0003— שרי\u0004 \u0005[מותר],\u0006 \u0003רטיבתא\u0004 \u0005[רטוב]\u0006 — אסור.","\u0003דרש רבא: אשה לא תכנס לדיר\u0004 (מחסן) \u0003העצים\u0004 כדי \u0003ליטול מהן אוד,\u0004 כלומר, חתיכת עץ כדי להפך בה את עצי המדורה, משום שלא נעשה אוד זה כלי מבעוד יום ולכן הוא מוקצה. \u0003ואוד שנשבר\u0004 — \u0003אסור להסיקו ביום טוב, לפי שמסיקין בכלים ואין מסיקין בשברי כלים\u0004 ואוד זה דינו ככלי.","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 כי כאן \u0003רבא כר' יהודה סבירא ליה\u0004 \u0005[סבור הוא]\u0006 \u0003דאית ליה\u0004 \u0005[שיש לו,\u0006 שהוא סובר\u0005]\u0006 דין \u0003מוקצה? והא\u0004 \u0005[והרי]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לשמעיה\u0004 \u0005[לשמשו]:\u0006 \u0003טוי לי בר אווזא\u0004 \u0005[צלה לי ברווז]\u0006 \u0003ושדי מעיה\u0004 \u0005[והשלך את מעיו]\u0006 לחתול. והרי לשיטת ר' יהודה אסור לתתם לבעלי חיים, לפי שלא הוכן לצרכם מבעוד יום! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003כיון דמסרחי\u0004 \u0005[שמסריחים]\u0006 בני המעיים אם לא ישתמש בהם — \u0003מאתמול\u0004 מערב יום טוב \u0003דעתיה עלויה\u0004 \u0005[דעתו עליהם]\u0006 שאת בני המעים שיהיו למחרת, יתן לחתולים שבביתו.","\u0003ר' אליעזר אומר: נוטל אדם קיסם\u0004 (חתיכה דקה) ביום טוב מערימה של קש וכיוצא בו \u0003שלפניו,\u0004 כדי \u0003לחצוץ\u0004 (לנקות) \u0003בו\u0004 בין \u0003שיניו. ומגבב\u0004 (אוסף) קש \u0003מן החצר ומדליק\u0004 בו. \u0003שכל מה שבחצר\u0004 — \u0003מוכן הוא\u0004 לכל צורך. \u0003וחכמים אומרים: מגבב\u0004 רק \u0003משלפניו\u0004 מדברים המונחים בבית, שבודאי מוכנים לכל צורך \u0003ומדליק,\u0004 אבל לא מן החצר, שדברים אלו המפוזרים בחצר טירחה גדולה לאוספם ובוודאי לא חשב עליהם לשם כך מבעוד יום ולכך הם מוקצה.","הלכה אחרת אמרו: \u0003אין מוציאין את האור\u0004 (אש) \u0003לא מן העצים\u0004 שמשפשפים זה בזה, \u0003ולא מן האבנים\u0004 שמקישים זו בזו, \u0003ולא מן העפר\u0004 החם \u0003ולא מן הרעפים\u0004 שמקישים אותם אלה באלה, \u0003ולא מן המים\u0004 הנמצאים בתוך כלי זכוכית עגול, וכתוצאה ממיקודם את קרני השמש נוצרת אש. \u0003ו\u0004כן \u0003אין מלבנין את הרעפים\u0004 בחום לוהט כדי שאפשר יהיה \u0003לצלות בהן\u0004 אחר כך.","\u0003אמר רב יהודה:\u0004"],["\u0003אוכלי\u0004 (מאכלי) \u0003בהמה,\u0004 כגון קש ועלי קנים — \u0003אין בהן משום תקון כלי\u0004 ומותר לקוטמם בשבת, ולעשות בהם כל צרכו.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב כהנא לרב יהודה\u0004 ממה שנאמר בברייתא: \u0003מטלטלין\u0004 בשבת \u0003עצי בשמים\u0004 כדי \u0003להריח בהן, ולהניף\u0004 (לנפנף) \u0003בהן לחולה\u0004 לעשות לו רוח, \u0003ומוללו\u0004 (לוחצו בין אצבעותיו, כדי למצות את ריחו) \u0003ומריח בו.\u0004 אבל \u0003לא יקטמנו\u0004 (יחתכנו מן הענף, כדי ליצור בענף מקום לח המדיף ריח חזק) כדי \u0003להריח בו, ואם קטמו\u0004 — \u0003פטור\u0004 מעונש מן התורה \u0003אבל אסור\u0004 לעשות כן. ואם נתכוון \u0003לחצוץ\u0004 (לנקות) \u0003בו\u0004 את \u0003שניו\u0004 — \u0003לא יקטמנו, ואם קטמו\u0004 — \u0003חייב חטאת,\u0004 שעבר על איסור מלאכה בשבת. ומשמע שיש בכך איסור, אף שחלק מעצי הבשמים משמשים למאכל בהמה, וזהו שלא כשיטת ר' יהודה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה לרב כהנא: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 מה שנאמר לו \u0003\"פטור אבל אסור\" קא קשיא לי\u0004 \u0005[קשה לי,\u0006 בעיני\u0005]\u0006 ואינו מסתבר כלל, \u0003חייב חטאת מבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006 ואין נראה כלל שאפשר להבין את הדברים כמשמעם, \u0003אלא\u0004 ודאי יש להבין את הדברים כך: \u0003כי תניא\u0004 \u0005[כאשר שנויה\u0006 הברייתא\u0005]\u0006 \u0003ההיא\u0004 הרי זה \u0003ב\u0004עצים \u0003קשין\u0004 שהם כקורות ובהם יש חשש מלאכה. ומקשים: וכי ענפים \u0003קשין בני מלילה\u0004 ביד \u0003נינהו\u0004 \u0005[הם]?\u0006","ומשיבים: \u0003חסורי מחסרא והכי קתני\u0004 \u0005[חסרה\u0006 הברייתא \u0005וכך יש לשנותה]:\u0006 עץ בשמים — \u0003מוללו ומריח בו, קוטמו ומריח בו. במה דברים אמורים\u0004 — \u0003ב\u0004עצים \u0003רכין, אבל בקשין\u0004 — \u0003לא יקטמנו, ואם קטמו\u0004 — \u0003פטור אבל אסור.\u0004 ואם נתכוון \u0003לחצוץ בו\u0004 את \u0003שיניו\u0004 — \u0003לא יקטמנו, ואם קטמו\u0004 — \u0003חייב חטאת.\u0004","בדומה לכך \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003קוטמו ומריח בו, ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003לא יקטמנו להריח בו. אמר ר' זירא אמר רב חסדא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שמותר — \u0003ב\u0004עצים \u0003רכין, הא\u0004 \u0005[זה]\u0006 שאסור — \u0003בקשין.\u0004","על עיקר הדבר \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב אחא בר יעקב: בקשין אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא? מאי שנא מהא דתנן\u0004 \u0005[במה שונה זה ממה ששנינו\u0006 במשנה\u0005]:\u0006 \u0003שובר אדם את החבית לאכול ממנה גרוגרות, ובלבד שלא יתכוין\u0004 במעשה זה כדי \u0003לעשות כלי\u0004 ויוכל להשתמש בחבית לאחר מכן. והרי מלאכת שבירה זו של העץ לצורך הרחה בו אין בה יותר מלאכה מאשר בשבירת החבית! \u0003ועוד:\u0004 והרי יודעים אנו כי \u0003רבא בר רב אדא ורבין בר רב אדא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003כי הוינן בי\u0004 \u0005[כאשר היינו בביתו]\u0006 של \u0003רב יהודה, הוה מפשח ויהיב לן אלותא אלותא\u0004 \u0005[היה שובר ונותן לנו מקלות מקלות\u0006 של עצי בשמים\u0005],\u0006 \u0003אף על גב דחזיא לקתתא דנרגי וחציני\u0004 \u0005[אף על פי שהיו ראויים\u0006 מתוך שהיו קשים \u0005לקתות של קרדומות ושל גרזינים].\u0006","ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 כשיטת \u0003ר' אליעזר, הא\u0004 \u0005[זו]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: נוטל אדם\u0004 בשבת או בחג \u0003קיסם משלפניו לחצוץ בו שיניו, וחכמים אומרים: לא יטול\u0004 קיסם \u0003אלא מאבוס של בהמה,\u0004 שמתוך שהוא ראוי למאכל בהמה, הריהו כמוכן לכל צורך שהוא. \u0003ושוין\u0004 (ומסכימים) \u0003שלא יקטמנו, ואם קטמו לחצוץ בו שיניו\u0004 או \u0003ולפתוח בו הדלת\u0004 כעין מפתח, אם עשה זאת \u0003בשוגג בשבת\u0004 — \u0003חייב\u0004 להביא קרבן \u0003חטאת\u0004 כדרך מי שעושה עבירה חמורה בשוגג, עשה זאת \u0003במזיד ביום טוב\u0004 — הרי זה \u0003סופג\u0004 (מקבל) \u0003את הארבעים\u0004 (ארבעים מלקות), כדין מי שחילל יום טוב במלאכה, אלו \u0003דברי ר' אליעזר.\u0004","\u0003וחכמים אומרים: אחד זה\u0004 אם עשה כן בשבת \u0003ואחד זה\u0004 אם עשה כן ביום טוב, גם אם קטם בידו לצורך מפתח, \u0003אינו\u0004 אסור \u0003אלא משום שבות\u0004 מדברי חכמים. ולכן, \u0003ר' אליעזר דקאמר התם\u0004 \u0005[שאמר שם]\u0006 שהקוטם בשוגג בשבת קיסם כדי לעשותו כלי (מפתח וכדומה) שהוא \u0003חייב חטאת,\u0004 אם כן \u0003הכא\u0004 \u0005[כאן]\u0006 בקוטם כדי להריח, הרי זה \u0003פטור אבל אסור.\u0004 ואילו \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003דקא אמרי התם\u0004 \u0005[שהם אומרים שם]\u0006 בקוטם כדי לעשותו כלי שהוא \u0003פטור אבל אסור, הכא\u0004 \u0005[כאן]\u0006 בקוטם כדי להריח סבורים כי \u0003מותר לכתחלה.\u0004","ושואלים: \u0003ולית ליה\u0004 \u0005[\u0006וכי \u0005אין לו,\u0006 אינו מקבל\u0005]\u0006 \u0003ר' אליעזר הא דתנן\u0004 \u0005[\u0006הלכה \u0005זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003שובר אדם את החבית\u0004 כדי \u0003לאכול ממנה גרוגרות, ובלבד שלא יתכוין לעשות כלי?\u0004 הרי שכשאינו מתכוון בכך כדי לעשות כלי מותר לכתחילה ולדבריו שם פטור אבל אסור! ומשיבים: \u0003אמר רב אשי: כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 שמתירה, הרי זה \u0003במוסתקי\u0004 בחבית שהיתה שבורה קודם, והיו חלקיה מדובקים בכעין זפת, שכאשר שובר אותה לצרכו לא שבר כלי שלם, ובודאי שאין בכך משום עשיית כלי.","שנינו במשנה כי \u0003מגבב\u0004 (אוסף) אדם קש \u0003מן החצר\u0004 ביום טוב. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מגבב מן החצר ומדליק,\u0004 משום \u0003שכל מה שבחצר מוכן הוא, ובלבד שלא יעשה צבורין צבורין\u0004 \u0005[ערימות ערימות].\u0006 \u0003ור' שמעון מתיר\u0004 אפילו בכך. ושואלים: \u0003במאי קמפלגי\u0004 \u0005[במה\u0006 באיזה ענין \u0005חלוקים הם],\u0006 מה טעם מחלוקתם? \u0003מר\u0004 \u0005[חכם זה,\u0006 חכמים שאסרו\u0005]\u0006 \u0003סבר: מחזי דקא מכניף\u0004 \u0005[\u0006משום \u0005נראה שהוא אוסף]\u0006 \u0003למחר וליומא אחרינא\u0004 \u0005[וליום אחר],\u0006 ולכן יש לאסור, שלא יראה כמכין מיום טוב לחול. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' שמעון שהתיר\u0005],\u0006 \u0003סבר: קדרתו מוכחת עליו\u0004 שהרי רואים עוד שהוא מביא את הדברים לבשל, וממילא בטל החשד שכוונתו לאחר יום טוב.","שנינו במשנה ש\u0003אין מוציאין\u0004 ביום טוב \u0003את האור\u0004 (אש) בכל דרך מחדש. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 ומסבירים: \u0003משום דקא מוליד\u0004 \u0005[שהוא מוליד]\u0006 דבר חדש \u0003ביום טוב,\u0004 והרי זה כמעשה יצירה, ואסור.","נאמר במשנה ש\u0003אין מלבנין\u0004 (מחממים) \u0003את הרעפים\u0004 כדי לצלות עליהם. ושואלים: \u0003מאי קא עביד\u0004 \u0005[מה הוא עושה\u0006 בכך\u0005]\u0006 הלא כוונתו לצורך אכילה, ומה שונה זה מדרך צלייה אחרת? \u0003אמר רבה בר בר חנה אמר ר' יוחנן: הכא\u0004 \u0005[כאן]\u0006 \u0003ברעפים חדשים עסקינן\u0004 \u0005[עוסקים אנו],\u0006 וטעם האיסור — \u0003מפני\u0004"],["\u0003שצריך לבדקן\u0004 אם אינם מתפוצצים בשעת חימומם, ואם אכן יתפוצצו אלה תוך כדי ליבונם, נמצא שטרח ביום טוב שלא לצורך. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003מפני שצריך לחסמן\u0004 (להקשות אותם) על ידי חימום יתר בפעם הראשונה ובלא חיסום זה עדיין אינם ראויים למלאכתם, וממילא יש בכך משום יצירת כלי ואסור לעשות כן ביום טוב.","אגב כך מביאים: \u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]:\u0006 תרנגולת ש\u0003דרסה\u0004 אדם ברגליים \u0003או שטרפה\u0004 (זרקה) על ה\u0003כותל, או שרצצתה\u0004 (דרסה אותה) \u0003בהמה\u0004 והיא \u0003מפרכסת\u0004 אבל אינה יכולה לעמוד, אם \u0003שהתה מעת לעת\u0004 בחייה \u0003ושחטה\u0004 — \u0003כשרה\u0004 אם לא נמצא מום אחר הגורם לה להיות טריפה. \u0003אמר ר' אלעזר בר ינאי משום ר' אלעזר בן אנטיגנוס: צריכה בדיקה\u0004 לאחר שחיטה שמא אירע בה מום.","על דבר זה \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' ירמיה מר' זירא: מהו לשחטה ביום טוב? מי מחזקינן רעותא\u0004 \u0005[האם מחזיקים אנו\u0006 שיש בה \u0005פגם]\u0006 \u0003ביום טוב, או לא?\u0004 כלומר, האם מותר לסמוך על כך שאין בסתם תרנגולת פגם, או שמא זו כיון שטעונה בדיקה ויש בה חשש, אין אנו שוחטים אותה שמא תימצא טריפה ונמצא שעשה מלאכה שלא לצורך.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תנינא\u0004 \u0005[\u0006הלא \u0005למדנו]:\u0006 \u0003אין מלבנין את הרעפים\u0004 כדי \u0003לצלות בהן. והוינן בה: מאי קא עביד\u0004 \u0005[והיינו עוסקים בה,\u0006 דנין בשאלה: \u0005מה הוא עושה\u0006 בכך\u0005]?\u0006 \u0003ואמר רבה בר בר חנה אמר ר' יוחנן: הכא\u0004 \u0005[כאן]\u0006 \u0003ברעפים חדשים עסקינן\u0004 \u0005[עוסקים אנו],\u0006 ואסרו לעשות כן \u0003מפני ש\u0004עדיין הוא \u0003צריך לבדקן\u0004 ויתכן שבחימומם יתפוצצו ויוכח שאינם ראויים למלאכתם ונמצא שעשה מלאכה שלא לצורך. משמע שאין נכנסים לספק בדבר שעלול להיות בו פגם ביום טוב, וכשם שאסורה ברעפים כך יש לאסור אף בחשש טריפות.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 אם מכאן אין זו ראיה, \u0003אנן\u0004 \u0005[אנחנו]\u0006 \u0003מפני שצריך לחסמן\u0004 כדי שיהיו נחשבים ככלי גמור \u0003מתנינן לה\u0004 \u0005[שונים אנו אותה]\u0006 ואין לאיסור עשיית כלי ולדבר הטעון בדיקה כלום, ולכן אין לאסור את שחיטתה ביום טוב.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 אנשים אחדים שעשו יחד מלאכת בישול אחת בשבת ומתחייבים כולם, כיצד; \u0003אחד מביא את האור\u0004 (האש), \u0003ואחד מביא את העצים, ואחד שופת\u0004 (מניח) \u0003את הקדרה\u0004 על הכיריים, \u0003ואחד מביא את המים\u0004 לקדירה \u0003ואחד נותן בתוכו\u0004 של התבשיל \u0003תבלין, ואחד מגיס\u0004 (בוחש) בקדירה — \u0003כולן חייבין\u0004 משום בישול. ועל כך תוהים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא אחרת\u0005]\u0006 שבה נאמר: \u0003אחרון חייב וכולן פטורין!\u0004 ומתרצים: \u0003לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הא דאייתי אור מעיקרא\u0004 \u0005[כאן,\u0006 ששנינו שכולם חייבים, מדובר כ\u0005שהביא אש מתחילה],\u0006 מפני שכל אחד מהן עשה מעשה של תיקון בבישול זה, אולם \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שרק האחרון חייב, מדובר באופן \u0003דאייתי אור\u0004 \u0005[שהביא אש]\u0006 \u0003לבסוף,\u0004 שכל האחרים לא עסקו קודם כלל בתיקון תבשיל והמלאכה עצמה החלה רק משעת הבאת האש.","ושואלים: \u0003בשלמא כולהו קא עבדי\u0004 \u0005[נניח כולם עשו]\u0006 \u0003מעשה\u0004 שיש בו מלאכת עבודה, ולכן הם שותפים במלאכת האיסור ובחילול השבת, \u0003אלא\u0004 ה\u0003שופת את הקדרה מאי קא עביד\u0004 \u0005[מה עשה]\u0006 מלאכת איסור בכך? \u0003אמר ר' שמעון בן לקיש: הכא\u0004 \u0005[כאן]\u0006 \u0003בקדרה חדשה עסקינן\u0004 \u0005[עוסקים אנו]\u0006 \u0003ומשום\u0004 אותו איסור שיש ב\u0003לבון רעפים נגעו בה.\u0004 שאינו עובר משום בישול האוכל שבקדירה, אלא משום תיקון הקדרה עצמה, כדרך שאסרו בליבון רעפים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003תנור וכירים חדשים\u0004 — \u0003הרי הן ככל הכלים הנטלין\u0004 בשבת \u0003בחצר\u0004 ומותר לטלטל אותם, שהרי ראויים הם להניח בהם דברים. \u0003אבל אין סכין אותם\u0004 ב\u0003שמן, ואין טשין\u0004 (משפשפים) \u0003אותן במטלית, ואין מפיגין אותם בצונן\u0004 להתיז עליהן נוזלים קרים, כדי שלא יתחממו מדי — שכל אלה יש בהם משום מלאכה של תיקון כלי, ואסור לעשותה ביום טוב. \u0003ואם בשביל לאפות\u0004 בתנור ביום טוב עצמו עושה את כל אלה — \u0003הרי זה מותר.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003מולגין את הראש ואת הרגלים.\u0004 כלומר: מותר לשפוך מים רותחים על ראשה ורגליה של בהמה כדי להשיר את השערות מעליהם, \u0003ומהבהבין\u0004 (חורכים) \u0003אותן באור\u0004 (באש) לשם כך, \u0003אבל אין טופלין\u0004 (מורחים) \u0003אותם בחרסית, ולא באדמה, ולא בסיד\u0004 לשם הסרת השערות, שיש בכך משום טירחה יתירה, והרי זה נראה כדרך עיבוד. \u0003ואין גוזזין אותן\u0004 את השערות הללו \u0003במספרים,\u0004 שנראה כאילו עושה מלאכת גזיזה ורצונו בצמר עצמו.","וכן \u0003אין גוזזין את הירק,\u0004 כלומר: את ראשי העלים הדבוקים בו \u0003בתספורת\u0004 (במספריים המיוחדים) \u0003שלו. אבל מתקנין את הקונדס ואת העכביות\u0004 שהם צמחים מרים שאינם נאכלים אלא לאחר בישול מרובה, ומכינים אותם לאכילה למרות הטירחה הרבה שבכך. \u0003ומסיקין ואופין בפורני\u0004 (בתנור גדול של נחתום) \u0003ומחמין\u0004 (ומחממים) \u0003חמין באנטיכי\u0004 (מין מיחם גדול) אבל \u0003אין אופין בפורני חדשה\u0004 — \u0003שמא תפחת,\u0004 כי אולי לא היה תנור זה עשוי כראוי ובהדלקת האש בתוכו יישבר ונמצא טורח ביום טוב שלא לצורך.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא \u0003כיוצא בו: אין נופחין במפוח\u0004 ללבות את האש, משום שהוא כדרך מלאכת חול, \u0003אבל נופחין\u0004 באש \u0003בשפופרת\u0004 בדרך שינוי. \u0003ואין מתקנין את השפוד ואין מחדדין אותו.\u0004ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא \u0003: אין מפצעין\u0004 (שוברים) \u0003את הקנה\u0004 כדי לעשות מעין שפוד \u0003לצלות\u0004 עליו \u0003מליח, אבל מפצעין את האגוז במטלית\u0004 שעוטפים סביבו בשעה שמכים עליו \u0003ואין חוששין שמא תקרע\u0004 המטלית על ידי כך, שגם אם נקרעה אין בכך משום מלאכת איסור.","\u0003ועוד אמר ר' אליעזר\u0004 להקל: \u0003עומד אדם על המוקצה,\u0004 כגון פירות שמפני טעם כלשהו הקצה אותם קודם משימושו,"],["\u0003ערב שבת ב\u0004שנת ה\u0003שביעית\u0004 שבשנה זו אין מעשרים, ואפשר למחרת ליטול מן הפירות ולאוכלם בלא תיקון נוסף, \u0003ואומר: מכאן\u0004 מפירות אלה \u0003אני אוכל למחר. וחכמים אומרים:\u0004 לא יאכל \u0003עד שירשום\u0004 (יסמן) בתוך ערימת הפירות מבעוד יום \u0003ויאמר\u0004 במפורש: \u0003מכאן ועד כאן\u0004 אני לוקח.","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003תינוקות שטמנו תאנים\u0004 לעצמם בשדה \u0003מערב שבת\u0004 כדי לאכול מהן בשבת, \u0003ושכחו ולא עשרו\u0004 — לא יאכלום בשבת, לפי שאכילת שבת נחשבת תמיד כאכילת קבע המחייבת במעשר, ואפילו \u0003למוצאי שבת לא יאכלו, אלא אם כן עשרו. ותנן נמי\u0004 \u0005[ושנינו\u0006 במשנה \u0005גם כן]:\u0006 \u0003המעביר תאנים בחצרו\u0004 כדי \u0003לקצות\u0004 (לעשות אותן קציעות – תאנים מיובשות) — \u0003בניו ובני ביתו אוכלין מהן\u0004 בינתיים אכילת \u0003עראי ופטורים\u0004 מן המעשר, שכן ראיית הפירות את פני החצר אינה קובעת את הפירות למעשר ואינה כדין בית.","ועל סמך שני מקורות אלה \u0003בעא מניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן: שבת, מהו שתקבע מוקצה למעשר בדבר שלא נגמרה מלאכתו?\u0004 האם נאמר שעצם העובדה שהמאכל מוכן לשבת עושה אותו כמאכל קבע וכמי שנגמרה מלאכתו, או לא? \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003כיון דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וקראת לשבת ענג\"\u0004 (ישעיהו נח, יג), לומר שכל אכילה בשבת נחשבת כעונג ואינה כאכילת ארעי, ולכך \u0003קבעה\u0004 השבת את הדברים \u0003ואפילו בדבר שלא נגמרה מלאכתו\u0004 שייחשב כגמור וראוי לאכילת קבע, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003בדבר שנגמרה מלאכתו\u0004 — \u0003קבעה\u0004 השבת, אולם \u0003בדבר שלא נגמרה מלאכתו\u0004 — לא קבעה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן לרבא: \u0003שבת קובעת, בין בדבר שנגמרה מלאכתו, בין בדבר שלא נגמרה מלאכתו. אמר ליה\u0004 \u0005[לו]\u0006 רבא והקשה: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שתהא \u0003שבת דומיא\u0004 \u0005[בדומה]\u0006 לדין ה\u0003חצר, מה חצר\u0004 — \u0003אינה קובעת\u0004 שיחשב מאכל הנמצא בה כסעודת קבע לענין מעשר \u0003אלא בדבר שנגמרה מלאכתו, אף שבת\u0004 — \u0003לא תקבע\u0004 (תחשיב כאכילת קבע) \u0003אלא בדבר שנגמרה מלאכתו! אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: אין אני אומר זאת בגלל סברה שהעלתי אני בדעתי שאתה יכול להציג כנגדה סברה אחרת, אלא \u0003לימוד ערוך הוא בידינו: שהשבת קובעת, בין בדבר שנגמרה מלאכתו, בין בדבר שלא נגמרה מלאכתו.\u0004","\u0003אמר מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 מעין זה במשנתנו, \u0003ועוד אמר ר' אליעזר: עומד אדם על המוקצה ערב שבת בשביעית\u0004 ואומר מכאן מכאן אני אוכל. \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום שהוא פרי \u0003שביעית, דלאו בר עשורי הוא\u0004 \u0005[שאינו בן מעשר],\u0006 שאין חובה לעשרו באותה שנה, \u0003הא\u0004 \u0005[אולם]\u0006 \u0003בשאר שני שבוע\u0004 \u0005[שנות השמיטה]\u0006 \u0003— הכי נמי\u0004 \u0005[כך גם כן\u0006 תאמר\u0005]\u0006 ש\u0003אסור\u0004 לאוכלם בלא לעשר, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 שה\u0003שבת קבעה\u0004 אותם למעשר ואסור לאוכלם בלעדיו?","ודוחים: \u0003לא\u0004 משם אין ראיה, \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 \u0003כיון\u0004 ש\u0003אמר: \"מכאן אני אוכל למחר\"\u0004 אם כן מיד \u0003קבע ליה\u0004 \u0005[לו]\u0006 סעודה \u0003עלויה\u0004 \u0005[עליהם]\u0006 והרי בכך גילה דעתו שאינו רוצה לעשות בהם תיקון נוסף. ושואלים: \u0003אי הכי מאי אריא\u0004 \u0005[אם כך מה שייך]\u0006 מדוע נאמרה הלכה זו דווקא ב\u0003שבת,\u0004 שהרי אז אין יחוד בשבת, \u0003אפילו\u0004 אם אמר כך \u0003ב\u0004יום \u0003חול נמי\u0004 \u0005[גם כן],\u0006 שהרי מאחר שיחדם לסעודתו — נעשו כגמורים וחייבים במעשר! ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]:\u0006 ש\u0003טבל\u0004 אין אומרים עליו שהוא מוקצה במהותו כיון שאסור לתקנו ולאוכלו, אלא \u0003מוכן הוא אצל שבת, ש\u0004כן \u0003אם עבר\u0004 על דברי חכמים \u0003ותקנו\u0004 — \u0003מתוקן.\u0004"],["ומקשים: כיצד יכול אתה לומר שעצם העובדה שהחליט לאכול מן הפירות כבר נחשבת כעושה אותם קבע, \u0003והלא\u0004 אף אם אמר שיאכל מהם למחר, מכל מקום \u0003מותרו,\u0004 הפירות שנשארו ולא אכלם, \u0003חוזר\u0004 מן הסתם לערימה. \u0003ושמעינן ליה\u0004 \u0005[ושמענו אותו]\u0006 את \u0003ר' אליעזר\u0004 ש\u0003אמר\u0004 במפורש: \u0003כל היכא\u0004 \u0005[היכן]\u0006 ש\u0003מותרו חוזר\u0004 — \u0003לא קבע\u0004 למעשר בכל מקרה!","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 במסכת מעשרות: \u0003הנוטל זיתים מן המעטן\u0004 (כלי גדול שבו מאכסנים את הזיתים לפי שעה), טרם מיצוי שמנם — \u0003טובל אחת אחת\u0004 מהן \u0003במלח ואוכל\u0004 בלא לעשרם קודם לכן, ואף על פי שאוכלם במלח, אין הדבר מחשיבם כאכילת קבע, כיון שאוכלם אחד אחד. \u0003ואם טבל ונתן לפניו\u0004 זיתים אחדים, כגון \u0003עשרה\u0004 — הרי זה \u0003חייב\u0004 במעשר, שנראה שהכין לעצמו סעודה שלימה מהם, ובכך נקבעו למעשר. ואילו \u0003ר' אליעזר אומר:\u0004 האוכל \u0003מן המעטן\u0004 ה\u0003טהור\u0004 — \u0003חייב\u0004 במעשר, ואם אוכל \u0003מן המעטן\u0004 ה\u0003טמא\u0004 — \u0003פטור\u0004 מן המעשר, \u0003מפני שהוא מחזיר את המותר\u0004 למעטן.","\u0003והוינן בה\u0004 \u0005[היינו עוסקים,\u0006 מתקשים, \u0005ב\u0006שאלה \u0005זו]:\u0006 \u0003מאי שנא רישא ומאי שנא סיפא\u0004 \u0005[במה שונה ההתחלה ובמה שונה הסוף],\u0006 כלומר: מה ענין טומאה וטהרה לכאן? \u0003ואמר ר' אבהו: רישא\u0004 \u0005[בראש\u0006 מדובר\u0005]\u0006 \u0003במעטן טהור וגברא\u0004 \u0005[ואיש]\u0006 \u0003טמא\u0004 שכשנוגע בהם הריהו מטמאם, \u0003דלא מצי מהדר ליה\u0004 \u0005[שאינו יכול להחזירו]\u0006 את הזיתים שנותרו, שאם יחזירם — הלא יטמא את כל הזיתים שבמעטן. ומכיון שכך, הריהו נוטל מלכתחילה רק כפי המידה שרוצה לאכול, ודי בכך כדי להחשיבם כאכילת קבע, ולכן חייב לעשרם.","אולם \u0003סיפא\u0004 \u0005[בסוף\u0006 מדובר\u0005]\u0006 \u0003במעטן טמא וגברא\u0004 \u0005[ואיש]\u0006 \u0003טמא,\u0004 שאף שטימא את הזיתים במגעו, \u0003דמצי מהדר ליה\u0004 \u0005[שיכול\u0006 עדיין \u0005להחזירו]\u0006 למעטן, שהרי הזיתים שבתוכו טמאים בגללו, ואינו מוסיף בכך כל טומאה. ומכיון שכך, אף מלכתחילה אינו מדייק ליטול בדיוק כפי המידה אותה הוא רוצה לאכול, ולכן אין בכך כדי לקובעם למעשר. ולענייננו למדנו, שכל שיכול להחזיר, הרי לדעת ר' אליעזר אינו נקבע עד גמר מלאכה!","ומשיבים: \u0003מתניתין נמי\u0004 \u0005[משנתנו גם כן]\u0006 מדברת \u0003במוקצה טהור וגברא\u0004 \u0005[ואיש]\u0006 \u0003טמא, דלא מצי מהדר ליה\u0004 \u0005[שאינו יכול להחזיר אותם].\u0006 ומקשים: \u0003והלא מוחזרין ועומדין הן!\u0004 שהרי כאן אין צורך שיקח אותם לביתו ויחזיר את השאר, אלא מדובר שלוקח כל מה שהכין לעצמו באמירה מפורשת מבעוד יום, ונמצא המותר שלא לקח מוחזר ועומד.","\u0003אלא אמר רב שימי בר אשי\u0004 יש לדחות מה שאמרנו, וכך יש להבין: \u0003ר' אליעזר קא אמרת\u0004 \u0005[אומר אתה]?\u0006 לשיטתו אין זו קושיה כי \u0003ר' אליעזר לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 שהרי הוא ש\u0003אמר\u0004 כי הפרשת \u0003תרומה\u0004 גדולה היא עצמה כבר \u0003קבעה\u0004 פירות אלו להיחשב כאילו נגמרה מלאכתם, ואסור לאוכלם אפילו באופן ארעי אלא אם כן הפריש מהם את שאר המעשרות, ואסור לאוכלו קודם לכן. \u0003וכל שכן\u0004 שעצם ביאת יום ה\u0003שבת\u0004 קובעת למעשר. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003פירות שתרמן\u0004 (הרים מהם תרומה גדולה) \u0003עד שלא נגמרה מלאכתן, ר' אליעזר אוסר לאכול מהן עראי\u0004 בלא לעשר שהתרומה כבר קבעתם, \u0003וחכמים מתירין.\u0004","ומציעים פתרון אחר לשאלת רבא; \u0003תא שמע מסיפא\u0004 \u0005[בוא\u0006 ו\u0005שמע\u0006 פתרון לענין \u0005מסופה\u0006 של משנתנו\u0005],\u0006 ששנינו בה, \u0003וחכמים אומרים:\u0004 אף בשמיטה שאין צורך בהפרשת תרומות ומעשרות מן הפירות, אמירה מבעוד יום אין בה כדי להכינם לשבת, \u0003עד שירשום\u0004 (יסמן את הפירות אותם הוא מכין) \u0003ויאמר\u0004 במפורש: \u0003\"מכאן ועד כאן\".\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 ש\u0003ערב שבת\u0004 בשנת \u0003השביעית דלאו בר עשורי\u0004 \u0005[שלא בן מעשר]\u0006 \u0003הוא, הא\u0004 \u0005[הרי]\u0006 \u0003בשאר שני שבוע\u0004 \u0005[שנות שמיטה]\u0006 ש\u0003בני עשורי נינהו\u0004 \u0005[עישור הם],\u0006 שהם חייבים במעשר — \u0003אסורים. מאי טעמא\u0004 \u0005[מה טעמם\u0006 הדבר\u0005]\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 שה\u0003שבת\u0004 עצמה \u0003קבעה?\u0004 וכיון שדעת חכמים היא אין מקום לדחות על פי שיטות מיוחדות, כשל ר' אליעזר.","ודוחים: \u0003לא,\u0004 משם אין ראיה, כי \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003כיון\u0004 ש\u0003אמר: \"מכאן ועד כאן אני אוכל למחר\"\u0004 — בכך \u0003קבע ליה\u0004 \u0005[לו]\u0006 את הסעודה ולא בשל השבת. ושואלים: \u0003אי הכי, מאי אריא\u0004 \u0005[אם כך, מה שייך,\u0006 מדוע דווקא\u0005]\u0006 כשזה \u0003שבת, אפילו ב\u0004יום \u0003חול נמי\u0004 \u0005[גם כן]\u0006 שייכת הלכה זו! ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 כפי שאמרנו לעיל; ש\u0003טבל\u0004 אין אומרים עליו שהוא מוקצה במהותו, כיון שאסור לתקנו ולאוכלו, אלא \u0003מוכן הוא אצל שבת, ש\u0004כן \u0003אם עבר\u0004 על דברי חכמים \u0003ותקנו — מתוקן. \u0004","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממקום אחר, ששנינו: \u0003היה אוכל באשכול\u0004 ענבים, שאינו נחשב לגמר מלאכה, שהלא מיועד הוא לסחיטה, \u0003ונכנס מגנה,\u0004 שבה אפשר לאכול פירות עראי בלי לעשר, אל ה\u0003חצר, ר' אליעזר אומר: יגמור\u0004 לאכול את האשכול, כיון שאין בחצר כדי לקבוע את הפירות למעשר אם לא נגמרה מלאכתם קודם לכן, ו\u0003ר' יהושע אומר: לא יגמור,\u0004 שלדעתו יש בחצר כדי לקבוע את הפירות למעשר אף שלא נגמרה מלאכתם.","וכן אם \u0003חשכה\u0004 לו \u0003בלילי שבת\u0004 באמצע אכילת האשכול, ואכילת שבת הלא כאכילת קבע היא, \u0003ר' אליעזר אומר: יגמור,\u0004 כיון שאף בשבת אין כדי לקבוע למעשר פירות שלא נגמרה מלאכתם קודם, ו\u0003ר' יהושע אומר: לא יגמור,\u0004 שיש לדעתו בשבת כדי לקבוע את הפירות למעשר אף אם לא נגמרה מלאכתם קודם לכן. הרי שר' אליעזר סובר שאין בשבת כדי לקבוע למעשר, ואילו ממשנתנו נראה שר' אליעזר מסכים שכניסת השבת קובעת!","ומשיבים: \u0003התם כדקתני טעמא\u0004 \u0005[שם כפי ששנינו\u0006 במפורש את \u0005הטעם]\u0006 ש\u0003ר' נתן אומר: לא כשאמר ר' אליעזר \"יגמור\"\u0004 הכוונה ש\u0003בחצר\u0004 עצמה \u0003יגמור, אלא\u0004 התכוון לומר: \u0003יצא חוץ לחצר ויגמור. ולא כשאמר ר' אליעזר \"יגמור\",\u0004 כוונתו היתה ש\u0003בשבת\u0004 עצמה \u0003יגמור, אלא ממתין למוצאי שבת ו\u0004אז \u0003יגמור.\u0004 ואם כן אין סתירה בין דבר זה למשנתנו.","ולפסק ההלכה בענין זה, \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן: אחד שבת, ואחד\u0004 הרמת \u0003תרומה\u0004 מן הפירות, \u0003ואחד חצר\u0004 שנכנסו הפירות לתוכה, \u0003ואחד מקח\u0004 (קניה), אם מכרן לחבירו — \u0003כולן אין קובעין\u0004 למעשר \u0003אלא בדבר שנגמרה מלאכתן.\u0004 ומעירים: שבכל אחד מהפרטים שהזכיר יש חידוש הלכה. כיצד?","\u0003שבת — לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003הלל, דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המעמר\u0004 (אוסף) \u0003פירות ממקום למקום לקצור, וקדש עליהם היום\u0004 שנכנסה בינתיים השבת, \u0003אמר ר' יהודה: הלל לעצמו אוסר.\u0004 כלומר: הלל לבדו היה אוסר בכגון זה לאוכלן עד שיפריש מהם מעשר, שלדעתו כניסת השבת היא עצמה גורמת לפירות שיחשבו כגמורים. והשמיענו ר' יוחנן שאין הלכה כהלל."],["מה שאמר \u0003חצר\u0004 שאינה קובעת למעשר בלא שנגמרה מלאכתם של הפירות, הרי זה \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' יעקב. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003המעביר תאנים בחצרו לקצות\u0004 (לעשות מהן קציעות – תאנים מיובשות) — \u0003בניו ובני ביתו אוכלין מהן\u0004 באופן \u0003עראי, ופטורים מן המעשר. ותני עלה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005עליה]\u0006 בהקשר למשנה זו: \u0003ר' יעקב מחייב, ור' יוסי בר' יהודה פוטר.\u0004 ובא ר' יוחנן להשמיענו שאין הלכה כר' יעקב.","מה שאמר שהרמת \u0003תרומה\u0004 גדולה מן הפירות אינה קובעת למעשר — \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' אליעזר. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003פירות שתרמן\u0004 (הרים מהם תרומה גדולה) \u0003עד שלא נגמרה מלאכתן, ר' אליעזר אוסר לאכול מהן עראי, וחכמים מתירין.\u0004","ומה שאמר ש\u0003מקח\u0004 (קניית פירות) אינה קובעת אותם למעשר \u0003— כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003הלוקח תאנים מעם הארץ, במקום שרוב בני אדם דורסין,\u0004 כלומר: שהם מייבשים את התאנים ועושים מהן דבילה, הרי במקום כזה לא נגמרה מלאכת התאנים לפני כן, ולכן \u0003אוכל מהן עראי, ומעשרן\u0004 כשנגמרה מלאכתם רק \u0003דמאי,\u0004 ככל דבר הנקנה מעם הארץ שמעשרים אותו מספק בלבד.","ומעירים: \u0003שמע מינה תלת\u0004 \u0005[למד ממנה\u0006 מברייתא זו \u0005שלושה\u0006 דברים בהלכה\u0005];\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]:\u0006 כי \u0003מקח אינה קובעת אלא בדבר שנגמרה מלאכתו,\u0004 וכל שלא נגמרה מלאכתו, אפילו מכרו — אין המכר מחייבו במעשר. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]:\u0006 ש\u0003רוב עמי הארץ מעשרין הן,\u0004 ולכן אינו מעשר ודאי כי אם דמאי. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 דבר אחר: כי \u0003מעשרין דמאי מעמי הארץ אפילו בדבר שלא נגמרה מלאכתו.\u0004","ופסק ר' יוחנן כשיטה זו, \u0003ולאפוקי מהא דתנן\u0004 \u0005[ולהוציא מזה ששנינו\u0006 במשנה\u0005]:\u0006 \u0003המחליף פירות עם חבירו\u0004 שדבר זה דינו כמקח, אם הכוונה היא \u0003זה לאכול וזה לאכול, זה לקצות וזה לקצות,\u0004 או \u0003זה לאכול וזה לקצות\u0004 — \u0003חייב.\u0004 ואילו \u0003ר' יהודה אומר:\u0004 זה שנטל \u0003לאכול\u0004 — \u0003חייב\u0004 שהרי עבורו נגמרה המלאכה, זה שנטל \u0003לקצות\u0004 — \u0003פטור\u0004 שהרי עבורו עדיין לא נגמרה מלאכתם ויכול לאכול מהם עראי. ופסק ר' יוחנן שלא כדעת תנא קמא, שעצם המקח אינו מחייב במעשר עד שתגמר מלאכתו.","","\u0003משילין\u0004 (משליכים) \u0003פירות\u0004 שהיו מונחים על גג בית לייבוש \u0003דרך\u0004 ה\u0003ארובה ביום טוב,\u0004 אם הוצרך להורידם משם מפני הגשם וכיוצא בכך, משום שאין בכך טירחה יתירה, \u0003אבל לא\u0004 עושים כן \u0003בשבת. ומכסים פירות בכלים מפני הדלף\u0004 מי גשמים הנוטפים מן הגג ומקלקלים אותם, \u0003וכן\u0004 מכסים \u0003כדי יין וכדי שמן\u0004 מאותו טעם. \u0003ונותנין כלי תחת הדלף בשבת\u0004 כדי לקלוט את המים בתוכו ולא יתקלקל הבית.","תחילה דנים בכמה צדדים לשוניים. \u0003אתמר\u0004 \u0005[נאמר]\u0006 שחלקו בכך \u0003רב יהודה ורב נתן, חד תני\u0004 \u0005[אחד\u0006 מהם \u0005שונה]\u0006 כפי שאנו שונים \u0003\"משילין\", וחד תני\u0004 \u0005[ואחד\u0006 מהם \u0005שונה]\u0006 \u0003\"משחילין\".\u0004","\u0003אמר מר זוטרא: מאן דתני\u0004 \u0005[מי ששונה]\u0006 לשון \u0003\"משילין\" לא משתבש\u0004 \u0005[טועה]\u0006 שיש סמוכין לדבר, \u0003ומאן דתני\u0004 \u0005[ומי ששונה]\u0006 לשון \u0003\"משחילין\" לא משתבש\u0004 \u0005[טועה],\u0006 שיש לכך ראיה. והוא מסביר: \u0003מאן דתני\u0004 \u0005[מי ששונה]\u0006 לשון \u0003\"משילין\" לא משתבש\u0004 \u0005[טועה],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"כי ישל זיתך\"\u0004 (דברים כח, מ), כלומר: יפול. \u0003ומאן דתני\u0004 \u0005[ומי ששונה]\u0006 לשון \u0003\"משחילין\" לא משתבש\u0004 \u0005[טועה],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 המביאה את רשימת המומים הפוסלים בבכור: \u0003השחול והכסול.\u0004 ומסבירים: \u0003שחול\u0004 — \u0003שנשמטה ירכו, כסול\u0004 — \u0003שאחד מירכותיו גבוהה מחברתה.\u0004 נמצא שמובן שורש האותיות ש.ח.ל מורה על היות הדבר מושלך או שמוט.","\u0003אמר רב נחמן בר יצחק: מאן דתני\u0004 \u0005[מי ששונה\u0006 במשנתנו\u0005]\u0006 לא \"משילין\" אלא \u0003\"משירין\" לא משתבש\u0004 \u0005[טועה],\u0006 \u0003ומאן דתני\u0004 \u0005[ומי ששונה]\u0006 לשון \u0003\"משחירין\" לא משתבש\u0004 \u0005[טועה].\u0006 \u0003ומאן דתני\u0004 \u0005[ומי ששונה]\u0006 לשון \u0003\"מנשירין\" לא משתבש\u0004 \u0005[טועה].\u0006 ומסביר: \u0003מאן דתני\u0004 \u0005[מי ששונה]\u0006 לשון \u0003\"משירין\" לא משתבש\u0004 \u0005[טועה],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' ישמעאל אומר: נזיר לא יחוף\u0004 \u0005[ירחץ]\u0006 את \u0003ראשו\u0004 בסיוע \u0003אדמה\u0004 (המשמשת כעין סבון) \u0003מפני שמשיר\u0004 על ידי כך \u0003את השער,\u0004 והנזיר הלא צווה לגדל פרע שער ראשו. הרי ש\"משיר\" משמעו לשון נפילה. \u0003ומאן דתני\u0004 \u0005[ומי ששנה]\u0006 לשון \u0003\"משחירין\"\u0004 אף הוא \u0003לא משתבש\u0004 \u0005[טועה].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003השחור\u0004 שהוא סוג של תער \u0003ו\u0004כן \u0003הזוג\u0004 (מהמספריים) \u0003של ספרים, אף על פי שנחלקו\u0004 שהרי הם מורכבים משני סכינים צמודים — \u0003טמאין.\u0004 ולענייננו נלמד ש\"שחור\" לשון חיתוך והפלה הוא. \u0003ומאן דתני\u0004 \u0005[ומי ששונה],\u0006 לשון \u0003\"מנשירין\" לא משתבש\u0004 \u0005[טועה]\u0006 אף הוא, \u0003דתנן\u0004 \u0005[\u0006שכן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שנשרו כליו במים\u0004 בשבת — \u0003מהלך בהם\u0004 ויתייבשו מאליהם \u0003ואינו חושש\u0004 לכך שעשויים אנשים לחשוד שכיבסם בשבת. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003מהא דתנן\u0004 \u0005[מזו ששנינו\u0006 במשנה\u0005] :\u0006איזהו לקט — \u0003הנושר בשעת קצירה.\u0004 הרי שלשון \"נושר\", משמעות נפילה לה.","","","ולבירור עצם הדברים. \u0003תנן\u0004 [\u0005שנינו במשנה\u0006]: \u0003משילין פירות דרך ארובה ביום טוב.\u0004 ושואלים: היות וטעם ההיתר הוא משום שאין בפעולה זו טירחה יתירה, מסתבר איפוא שאין הדבר בלתי מוגבל, ואם כן \u0003עד כמה?\u0004 מה כמות הפירות שמותר להעביר כך? \u0003אמר ר' זירא אמר רב אסי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' אסי אמר ר' יוחנן: כאותה\u0004 כמות \u0003ששנינו\u0004 בנושא אחר: \u0003מפנין\u0004 בשבת \u0003ארבע וחמש קופות\u0004 (סלים) \u0003של תבן ושל תבואה\u0004 מן המחסן \u0003מפני האורחים\u0004 שיוכלו לשבת שם, \u0003ומפני בטול בית המדרש\u0004 אם אין די מקום ישיבה לתלמידים.","את הראיה הזו דוחים: \u0003ודלמא שאני התם\u0004 \u0005[ושמא שונה שם]\u0006 \u0003דאיכא\u0004 \u0005[שיש]\u0006 בכך \u0003בטול בית המדרש, אבל הכא דליכא\u0004 \u0005[אבל כאן שאין]\u0006 \u0003בטול בית המדרש\u0004 — \u0003לא\u0004 יתירו לטלטל כמות רבה כל כך. ומצד אחר, \u0003אי נמי: התם היינו טעמא\u0004 \u0005[או גם כן זהו הטעם]:\u0006 ש\u0003ארבע וחמש קופות שרי\u0004 \u0005[מותר]\u0006 \u0003— משום שבת דחמירא\u0004 \u0005[ש\u0006היא \u0005חמורה]\u0006 \u0003ולא אתי לזלזולי ביה\u0004 \u0005[יבואו לזלזל בה],\u0006 \u0003אבל יום טוב דקיל\u0004 \u0005[ש\u0006הוא \u0005קל]\u0006 \u0003ואתי לזלזולי ביה\u0004 \u0005[ויבואו לזלזל בו]\u0006 — \u0003כלל כלל לא.\u0004","\u0003אי נמי לאידך גיסא\u0004 \u0005[או גם כן\u0006 אפשר לטעון \u0005לצד אחר]:\u0006 \u0003התם היינו טעמא\u0004 \u0005[שם זהו הטעם]\u0006 שמותר רק ארבע וחמש קופות, משום \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003הפסד ממון\u0004 בכך, \u0003אבל הכא דאיכא\u0004 \u0005[כאן שיש]\u0006 \u0003הפסד ממון\u0004, בכך, שהרי אם לא כן יתקלקלו הפירות, אם כן \u0003אפילו טובא נמי\u0004 \u0005[הרבה גם כן]\u0006 מותר לטלטל."],["ושאלה נוספת בענין זה: \u0003התם תנן\u0004 \u0005[שם\u0006 בשבת \u0005שנינו\u0006 במשנה\u0005]\u0006 \u0003\"אבל לא\u0004 יפנה \u0003את האוצר\", ואמר שמואל: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אבל לא את האוצר\"\u0004 — כוונתו: \u0003אבל לא יגמור\u0004 לפנות \u0003את האוצר כולו,\u0004 וטעמו: \u0003דלמא אתי לאשויי\u0004 \u0005[שמא יבוא להשוות]\u0006 את ה\u0003גומות\u0004 הנמצאות בקרקע המחסן, ודבר זה הוא מלאכה האסורה מן התורה. ואם כן \u0003הכא מאי\u0004 \u0005[כאן מה\u0006 הדין\u0005]?\u0006","וצדדי השאלה: \u0003התם\u0004 \u0005[שם]\u0006 \u0003בשבת הוא\u0004 ש\u0003אסור משום דחמיר\u0004 \u0005[שחמור]\u0006 עונשה, \u0003אבל יום טוב דקיל\u0004 \u0005[\u0006שהוא \u0005קל]\u0006 \u0003— שפיר דמי\u0004 \u0005[יפה הדבר]\u0006 שאין חוששים עד כדי כך ויכול להשיל כמות גדולה יותר של פירות. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בשבת \u0003דאיכא\u0004 \u0005[שיש]\u0006 בכך משום \u0003בטול בית המדרש, אמרת\u0004 \u0005[אומר אתה]\u0006 כי \u0003לא\u0004 הותר הטלטול יותר מחמש קופות, אולם \u0003הכא\u0004 \u0005[כאן]\u0006 בהשלת פירות מן הגג ביום טוב \u0003דליכא\u0004 \u0005[שאין]\u0006 בכך משום \u0003בטול בית המדרש\u0004 — \u0003לא כל שכן\u0004 שאסור.","ושאלה נוספת: \u0003והכא תנן\u0004 \u0005[וכאן\u0006 במשנתנו \u0005שנינו]:\u0006 \u0003משילין פירות דרך\u0004 ה\u0003ארובה ביום טוב, ואמר רב נחמן: לא שנו אלא באותו הגג\u0004 להוריד במישרין דרך הארובה, \u0003אבל מגג לגג\u0004 — \u0003לא. ותניא נמי הכי\u0004 \u0005[ושנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אין מטלטלין מגג לגג אפילו כשגגותיהן שוין\u0004 ואין בכך טירחה כפולה של העברה והרמה כאחד.","ויש לשאול: \u0003התם מאי\u0004 \u0005[שם\u0006 בשבת \u0005מה\u0006 הדין\u0005]?\u0006 האם לומר \u0003כל שכן\u0004 שאין לעשות כן ב\u0003שבת\u0004 משום \u0003דחמירא\u0004 \u0005[ש\u0006היא \u0005חמורה],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 נאמר לצד אחר: \u0003הכא\u0004 \u0005[כאן]\u0006 ביום טוב \u0003הוא\u0004 ש\u0003אסור\u0004 להעביר מגג לגג, \u0003משום יום טוב דקיל\u0004 \u0005[ש\u0006הוא \u0005קל]\u0006 \u0003ואתי\u0004 \u0005[ויבואו]\u0006 אם כן \u0003לזלזולי ביה\u0004 \u0005[לזלזל בו],\u0006 \u0003אבל שבת דחמירא\u0004 \u0005[ש\u0006היא \u0005חמורה]\u0006 \u0003ולא אתי לזלזולי\u0004 \u0005[יבואו לזלזל]\u0006 \u0003בה — שפיר דמי\u0004 \u0005[יפה הדבר]\u0006 ויכול להעביר אף מבית לבית.","\u0003או דלמא\u0004 \u0005[שמא]\u0006 נאמר להיפך: \u0003מה הכא\u0004 \u0005[כאן]\u0006 ביום טוב \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003הפסד פירות, אמרת\u0004 \u0005[אומר אתה]\u0006 ש\u0003לא\u0004 מעביר מגג לגג, ואם כן \u0003התם\u0004 \u0005[שם]\u0006 בשבת \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003הפסד פירות\u0004 — \u0003לא כל שכן.\u0004","ובעיה נוספת: \u0003הכא\u0004 \u0005[כאן]\u0006 בענין הכנסת הפירות הנמצאים על הגג לבית, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 אם אין ארובה המקשרת בין הגג לבית וצריך להכניסם בדרך אחרת, \u0003לא ישלשלם בחבל בחלונות, ולא יורידם דרך סולמות, התם מאי\u0004 \u0005[שם\u0006 בשבת \u0005מה\u0006 הדין\u0005]?\u0006 האם נאמר כי \u0003ביום טוב\u0004 דווקא \u0003הוא\u0004 ש\u0003אסור\u0004 משום \u0003דליכא\u0004 \u0005[שאין]\u0006 במה שמונחים הפירות על הגג משום \u0003בטול בית המדרש, אבל\u0004 ב\u0003שבת דאיכא\u0004 \u0005[שיש]\u0006 בהותרת הקופות במקום משום \u0003בטול בית המדרש — שפיר דמי\u0004 \u0005[יפה הדבר]\u0006 ויוכל להעבירם אף דרך חלונות וסולמות\u0005.\u0006","\u0003או דלמא\u0004 \u0005[שמא]:\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 ביום טוב \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003הפסד פירות אמרת\u0004 \u0005[אמרת]\u0006 ש\u0003לא, אבל התם\u0004 \u0005[שם]\u0006 בשבת \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003הפסד פירות\u0004 — \u0003לא כל שכן\u0004 שאסור לשלשל דרך חלונות או סולמות. לכל השאלות הללו לא נמצאה תשובה, והושארו ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","שנינו במשנה ש\u0003מכסין את הפירות\u0004 בכלי מפני הדלף. \u0003אמר עולא: ואפילו אוירא דלבני\u0004 \u0005[שורת לבנים]\u0006 העשויה להתקלקל מן הגשם. שאין הכוונה דווקא לפירות, אלא לכל דבר העשוי להתקלקל. \u0003ר' יצחק אמר:\u0004 דווקא \u0003פירות הראויין\u0004 לאכילה, אולם לא לבנים וכדומה. ומעירים: \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003ר' יצחק לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 בענין זה. שכן \u0003אמר ר' יצחק: אין כלי\u0004 ואפילו זה שמצד עצמו מותר בטלטול \u0003ניטל\u0004 (מותר בטלטול) \u0003בשבת אלא ל\u0004צורך \u0003דבר\u0004 דבר שהוא עצמו \u0003ניטל בשבת,\u0004 אבל לא לצורך מוקצה. ולכן אסור לדעתו לטלטל כלי כדי להגן על הלבנים מפני הדלף, מאחר שהם עצמם אסורים בטלטול.","ומנסים להביא ראיה, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתו\u0005]:\u0006 \u0003מכסין את הפירות בכלים,\u0004 ונדייק: \u0003פירות — אין\u0004 \u0005[כן],\u0006 אולם \u0003אוירא דלבני\u0004 \u0005[שורת הלבנים]\u0006 — \u0003לא!\u0004 ודוחים: אין מכאן ראיה, כי יתכן ש\u0003הוא הדין\u0004 ש\u0003אפילו אוירא דלבני\u0004 \u0005[שורת הלבנים]\u0006 מותר לכסותה, אולם \u0003ואיידי דתנא רישא\u0004 \u0005[מתוך ששנה בראש\u0006 המשנה\u0005]\u0006 \u0003משילין פירות\u0004 ושם מדובר בפירות דווקא — \u0003תנא סיפא נמי\u0004 \u0005[שנה בסוף גם כן]\u0006 בלשון \u0003מכסין את הפירות.\u0004","ומביאים ראיה אחרת: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003וכן\u0004 מותר לכסות ביום טוב \u0003כדי יין וכן כדי שמן\u0004 מפני הדלף, משמע שרק לצורך דבר הראוי לאכילה הותר הטלטול, אולם לא לצורך דבר האסור בטלטול וכגון לבנים! ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים],\u0006 \u0003ב\u0004כדים שיש בהם פירות של \u0003טיבלא\u0004 \u0005[טבל]\u0006 שאינם ראויים לאכילה בחג ואסורים בטלטול, ויתכן שהוא הדין אם כן אף בלבנים.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר\u0006 לומר\u0005],\u0006 \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך\u0006 לומר\u0005]\u0006 כי \u0003כדי יין וכדי שמן דהתירא\u0004 \u0005[של היתר]\u0006 הם, \u0003הא תנא ליה רישא\u0004 \u0005[הרי\u0006 כבר \u0005שנה בראש]\u0006 \u0003פירות,\u0004 ומה חידש כשהוסיף גם כדים?","ומשיבים: אף ב\u0003כדי יין וכדי שמן\u0004 מדובר בשל היתר, ואף על פי כן \u0003אצטריכא ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]\u0006 במפורש, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003להפסד מרובה\u0004 של הפירות, שעשויים הם להירקב — \u0003חששו,\u0004 אולם \u0003להפסד מועט\u0004 של היין שבתוך הכדים, שאף אם תחדור רטיבות לתוך הכד, עדיין אין בכך כדי לגרום הפסד ליין — \u0003לא חששו\u0004 ולא התירו לכסות את הכדים, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 גם באלה.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003נותנין כלי תחת הדלף בשבת.\u0004 הרי שנוטלים כלי לצורך דבר שאינו ניטל (הדלף עצמו)! ומשיבים: מדובר שם \u0003בדלף\u0004 צלול שהוא \u0003ראוי\u0004 לפחות לשתיית הבהמות.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת ממה ששנינו: \u0003פורסין מחצלת על גבי לבנים בשבת\u0004 מפני דלף גשמים. והלא לבנים אלה מוקצות הן למלאכתן, ומכאן שמותר לטלטל כלי לצורך דבר שאינו ניטל! ודוחים: כאן מדובר בלבנים \u0003דאייתור מבנינא\u0004 \u0005[שנשארו מבנין],\u0006 \u0003דחזי למזגא עלייהו\u0004 \u0005[שראויות לשכב עליהן]\u0006 ואין בהן איפוא משום מוקצה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת, שנינו: \u0003פורסין מחצלת על גבי אבנים בשבת!\u0004 ומשיבים: שם מדובר לא באבנים סתם אלא \u0003באבנים מקורזלות\u0004 (מעוגלות בצורה מיוחדת) \u0003דחזיין\u0004 \u0005[שראויות\u0006 הן\u0005]\u0006 \u0003לבית הכסא\u0004 לצורך קינוח ואינם מוקצה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממקום אחר: \u0003פורסין מחצלת על גבי כורת דבורים בשבת, בחמה\u0004 — \u0003מפני החמה\u0004 היתירה, ו\u0003ב\u0004ימות ה\u0003גשמים מפני הגשמים, ובלבד שלא יתכוין לצוד\u0004 את הדבורים הללו באמצעות כיסוי זה. הרי שמטלטלים מחצלת לצורך דבר שהוא עצמו אסור בטלטול! ומשיבים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 מדובר באופן \u0003דאיכא\u0004 \u0005[שיש]\u0006 בכוורת זו \u0003דבש,\u0004 ולצורך הדבש מותר לטלטל כלי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב עוקבא ממישן לרב אשי: התינח\u0004 \u0005[נניח\u0006 דבר זה\u0005]\u0006 \u0003בימות החמה, דאיכא\u0004 \u0005[שיש]\u0006 \u0003דבש,\u0004 אולם \u0003בימות הגשמים\u0004 שאין דבש, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003לא נצרכא\u0004 \u0005[נצרכה]\u0006 הלכה זו \u0003אלא לאותן שתי חלות\u0004 שמשאירים בכוורת לסיפוקן של הדבורים עצמן בימות הגשמים. ומקשים: \u0003אותן שתי חלות\u0004 הלא \u0003מוקצות הן,\u0004 שהרי ברור שרצונו שישארו רק לצורך הדבורים! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003שחשב עליהם\u0004 מבעוד יום לאוכלן, ולא איכפת לו מדבורי הכוורת.","ושואלים: אם כן \u0003אבל לא חשב עליהן מאי\u0004 \u0005[מה\u0006 יהא הדין\u0005]\u0006 — \u0003אסור. אדתני\u0004 \u0005[עד ש\u0006הוא \u0005שונה]\u0006 \u0003ובלבד שלא יתכוין לצוד, לפלוג ולתני בדידה\u0004 \u0005[שיחלק וישנה בתוך\u0006 הלכה זו \u0005עצמה]\u0006 חלוקת ביניים: \u0003במה דברים אמורים — כשחשב עליהן, אבל\u0004 אם \u0003לא חשב עליהן אסור!\u0004","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך\u0006 באמת \u0005אמר]:\u0006 \u0003אף על פי שחשב עליהן\u0004 עדיין היתר זה איננו היתר גורף, ויש להגבילו — \u0003ובלבד שלא יתכוין לצוד.\u0004","ושואלים עוד: \u0003במאי אוקימתא\u0004 \u0005[במה העמדת,\u0006 הסברת את הברייתא הזו\u0005]\u0006 — \u0003כ\u0004שיטת \u0003ר' יהודה, דאית ליה\u0004 \u0005[שיש לו,\u0006 שהוא סובר\u0005]\u0006 דין \u0003מוקצה,\u0004 אם כן \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של הברייתא\u0005]:\u0006 \u0003ובלבד שלא יתכוין לצוד,\u0004 ומשמע שאף על פי שבכך ודאי ניצודות הן, מכל מקום מאחר שלא לכך היתה כוונתו — מותר, הרי בכך \u0003אתאן\u0004 \u0005[הגענו]\u0006 \u0003ל\u0004שיטת \u0003ר' שמעון,\u0004 ש\u0003אמר: דבר שאין מתכוין מותר!\u0004","ודוחים: \u0003ותסברא\u0004 \u0005[וכי סבור אתה]\u0006 שדבר זה פשוט לדעת \u0003ר' שמעון? והא\u0004 \u0005[והרי]\u0006 \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מודה ר' שמעון\u0004 שאף בדבר שאינו מתכוון, \u0003ב\u0004מקרה של \u0003\"פסיק רישיה\u0004 \u0005[חתוך ראשו]\u0006 \u0003ולא ימות\",\u0004 כלומר: במקום שהמלאכה הנעשית היא תוצאה הכרחית מן הדבר שאותו אדם עושה, מודה ר' שמעון שאין לומר שאין העושה מתכוון לאותה תוצאה. ואף כאן, מאחר שכתוצאה מכיסוי זה ודאי הדבורים ניצודות — אי אפשר לומר שהדבר תלוי רק בכוונתו.","אלא, \u0003לעולם כולה\u0004 כשיטת \u0003ר' יהודה היא, והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]\u0006 \u0003— דאית ביה כוי\u0004 \u0005[שיש בה חלונות].\u0006 כלומר: שאינו מכסה לגמרי את הכוורת אלא משאיר בה פתחים. \u0003ולא תימא\u0004 \u0005[תאמר]\u0006 \u0003ל\u0004שיטת \u0003ר' יהודה \"ובלבד שלא יתכוין לצוד\"\u0004 שמלשון זה משמע כי העיקר תלוי בכוונת העושה,"],["\u0003אלא אימא\u0004 \u0005[אמור]\u0006 בלשון זו: \u0003ובלבד שלא יעשנו מצודה\u0004 (מלכודת), שאין הדבורים יכולות לצאת ממנה. ושואלים: אם כן \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שהרי אסור לצוד בשבת! ומשיבים: יש בכך חידוש, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 דבר ש\u0003במינו נצוד,\u0004 כלומר: בעל חי שרגילים לצוד אותו — \u0003אסור\u0004 לצודו, אולם \u0003שלא במינו נצוד,\u0004 כלומר: בעל חי שאין רגילים לצודו — \u0003מותר\u0004 אפילו לכתחלה, שהרי אין זו דרך ציד, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלכתחילה אסור אף באלה.","\u0003רב אשי אמר\u0004 הסבר אחר: \u0003מי קתני\u0004 \u0005[האם שנינו]\u0006 באותה ברייתא \u0003בימות החמה\u0004 (בקיץ) \u0003ובימות הגשמים\u0004 (בחורף)? הלא \u0003בחמה\u0004 בשעת החמה \u0003מפני החמה ובגשמים\u0004 בשעת הגשמים \u0003מפני הגשמים קתני\u0004 \u0005[שנינו]\u0006 ומדובר שם \u0003ביומי\u0004 \u0005[בימי]\u0006 \u0003ניסן וביומי\u0004 \u0005[ובימי]\u0006 \u0003תשרי —\u0004 באביב ובסתיו, \u0003דאיכא\u0004 \u0005[שיש]\u0006 בהם \u0003חמה ואיכא\u0004 \u0005[ויש]\u0006 בהם לפעמים \u0003גשמים, ואיכא\u0004 \u0005[ויש]\u0006 גם \u0003דבש.\u0004 ואפשר לומר כי לצורך הדבש מכסים את הכוורת וכפי שתירצו בתחילה.","שנינו במשנה כי \u0003נותנין כלי תחת הדלף\u0004 (מי גשמים הדולפים מן הגג) \u0003בשבת. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003אם נתמלא הכלי\u0004 בדלף — \u0003שופך\u0004 את תוכנו, \u0003ו\u0004אף \u0003שונה\u0004 שופך שנית, אם צריך, \u0003ואינו נמנע\u0004 מכך.","מסופר: \u0003בי רחיא\u0004 \u0005[בית הרחיים]\u0006 של \u0003אביי\u0004 שבחלקם היו עשויים או מתוקנים בטיט, \u0003דלוף\u0004 \u0005[דלף\u0006 מים\u0005]\u0006 עליהם ונתגלה הדבר בשבת והיה חשש שיגרם להם נזק, ולא היה להם די כלים כדי לקלוט את כל המים, \u0003אתא לקמיה\u0004 \u0005[בא\u0006 אביי \u0005לפני]\u0006 \u0003רבה\u0004 לשאול מה לעשות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003זיל עייליה לפוריך להתם\u0004 \u0005[לך והכנס את מיטתך לשם]\u0006 לבית הרחיים, \u0003דלהוי\u0004 \u0005[שיהיו]\u0006 מים אלה \u0003כגרף של רעי\u0004 \u0005[כמו כלי של צואה]\u0006 שמותר להוציאו מפני המיאוס, \u0003ואפקיה\u0004 \u0005[ו\u0006אז \u0005תוציאם\u0006 החוצה\u0005].\u0006","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003אביי\u0004 ועיין בדבר \u0003וקא קשיא ליה\u0004 \u0005[והיה קשה לו]:\u0006 \u0003וכי עושין\u0004 פעולה כלשהי שבשבילה ייחשב דבר \u0003גרף של רעי לכתחלה?\u0004 ומספרים: \u0003אדהכי נפל בי רחיא\u0004 \u0005[בינתיים עד\u0006 שהיה מחשב בדבר \u0005נפל בית הרחיים]\u0006 של \u0003אביי. אמר: תיתי לי דעברי אדמר\u0004 \u0005[יבוא לי,\u0006 מגיע לי, \u0005על שעברתי על דברי אדוני,\u0006 רבה\u0005].\u0006","\u0003אמר שמואל: גרף של רעי\u0004 או \u0003עביט\u0004 (כלי) \u0003של מימי רגלים\u0004 — \u0003מותר להוציאן\u0004 בשבת \u0003לאשפה, וכשהוא מחזירו\u0004 — \u0003נותן בו מים ומחזירות\u0004 שאם לא כן אסור לטלטלו, שהרי ריחו רע, והוא כמוקצה מחמת מיאוס.","\u0003סבור מינה\u0004 \u0005[חשבו\u0006 לפסוק \u0003מכאן]\u0004 שלהוציא בשבת \u0003גרף של רעי אגב מנא\u0004 \u0005[הכלי]\u0006 — \u0003אין\u0004 \u0005[כן],\u0006 מותר להוציאו אולם להוציא את הרעי \u0003בפני עצמו\u0004 — \u0003לא.\u0004 ומספרים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003דההוא עכברתא דאשתכח בי אספרמקי\u0004 \u0005[שעכבר\u0006 מת \u0005אחד שמצאו באוצר הבשמים]\u0006 של \u0003רב אשי\u0004 בשבת, \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב אשי: נקטה בצוציתה ואפקוה\u0004 \u0005[אחזוה בזנבה והוציאוה].\u0006","\u0003כל\u0004 דבר \u0003שחייבין עליו,\u0004 כלומר: שמקור החובה שלא לעשותו בשבת, הוא \u0003משום שבות\u0004 (איסור מדברי סופרים), או \u0003משום רשות\u0004 — דבר שאינו מצוה אף שהיה בו צד מסויים של מצוה או דבר שהוא \u0003משום מצוה\u0004 ובכל זאת אסרו לעשותו \u0003בשבת\u0004 — \u0003חייבין עליו\u0004 שלא לעשותו אף \u0003ביום טוב.\u0004","\u0003ואלו הן\u0004 הדברים שאסרו חכמים \u0003משום שבות: לא עולין באילן, ולא רוכבין על גבי בהמה, ולא שטין על פני המים, ולא מטפחין\u0004 (מוחאים כפים) \u0003ולא מספקין\u0004 (יד על ירך) \u0003ולא מרקדין.\u0004","\u0003ואלו הן\u0004 הדברים שאסרו, אף על פי שיש בהן \u0003משום רשות\u0004 וקרובים הם להיחשב כמצוה: \u0003לא דנין\u0004 בשבת, \u0003ולא מקדשין\u0004 את האשה, \u0003ולא חולצין\u0004 את היבמה, \u0003ולא מיבמין\u0004 אותה.","\u0003ואלו הן\u0004 הדברים שיש בהן \u0003משום מצוה\u0004 ואסרום: \u0003לא מקדישין\u0004 דברים למקדש, \u0003ולא מעריכין\u0004 שהוא מין הקדש שיש לו ערך קבוע (ויקרא פרק כז) \u0003ולא מחרימין\u0004 חרמים, שהם הקדש ממין אחר, \u0003ולא מגביהין\u0004 (מפרישין) \u0003תרומה ומעשר\u0004 מן הפירות.","\u0003כל אלו\u0004 אף \u0003ביום טוב אמרו, קל וחומר\u0004 שלא יעשה כן \u0003בשבת.\u0004 כללו של דבר: \u0003אין בין יום טוב לשבת אלא\u0004 מלאכת \u0003אוכל נפש בלבד,\u0004 שהכנתו מותרת ביום טוב ואסורה בשבת.","את טעמי הדברים מסבירים: \u0003לא עולין באילן\u0004 — \u0003גזרה שמא יתלוש\u0004 מן הענפים או העלים ועובר בכך על איסור \"קוצר\".","\u0003ולא רוכבין על גבי בהמה\u0004 — \u0003גזרה שמא יצא חוץ לתחום\u0004 ברכיבה עליה. ושואלים: אם כן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי איסור היציאה חוץ \u0003לתחומין דאורייתא\u0004 \u0005[מן התורה]?\u0006 שהרי אם איסור תחומין לא היה אלא מגזירת חכמים, לא היו הם גוזרים אגב גזירה זו, גזירה נוספת שלא לרכב בשל כך על גבי בהמה, ודבר זה הלא שנוי במחלוקת! \u0003אלא,\u0004 ה\u0003גזרה\u0004 היא \u0003שמא יחתוך זמורה\u0004 כדי לזרז את הבהמה בהילוכה, ודבר זה אסור משום \"קוצר\".","\u0003ולא שטין על פני המים\u0004 — \u0003גזרה שמא יעשה חבית של שייטין\u0004 (כלי עזר המסייע ללימוד שחיה).","\u0003ולא מטפחין ולא מספקין ולא מרקדין,\u0004 כל אלה — \u0003גזרה שמא יתקן כלי שיר\u0004 ללוות אותו בשעת מחיאת הכפיים או הריקוד.","שנינו במשנה \u0003ואלו הן משום רשות: לא דנין.\u0004 ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 בכל אלה \u0003מצוה קעביד\u0004 \u0005[הוא עושה]\u0006 ואינם רשות בלבד! ומשיבים: \u0003לא צריכא, דאיכא דעדיף מיניה\u0004 \u0005[לא נצרכה\u0006 אלא \u0005שיש\u0006 אחד \u0005שעדיף ממנו]\u0006 ויכול אותו אדם לדון בכך, ולכן אומרים שאין בכך מצוה אלא רשות.","שנינו במשנה: \u0003ולא מקדשין.\u0004 ושואלים: ומדוע היא רשות? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מצוה קעביד\u0004 \u0005[עושה],\u0006 שהלא הוא נושא אשה כדי לקיים מצות \"פרו ורבו\"! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה"],["\u0003דאית ליה\u0004 \u0005[שיש לו]\u0006 כבר \u0003אשה ובנים,\u0004 ואם כן קיים כבר את המצוה וכשמקדש אשה נוספת אינו אלא רשות.","שנינו: \u0003לא חולצין ולא מיבמין.\u0004 ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מצוה קא עביד\u0004 \u0005[הוא עושה]\u0006 ולא רשות בלבד! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא למקרה \u0003דאיכא\u0004 \u0005[שיש]\u0006 עוד אח \u0003גדול\u0004 ממנו, וכלל הוא: \u0003מצוה בגדול ליבם,\u0004 ורק אם האח הגדול אינו נמצא חלה החובה על האח האחר.","ומסבירים: \u0003וכלהו טעמא מאי\u0004 \u0005[וכל אלה טעמם מה]\u0006 — \u0003גזירה שמא יכתוב\u0004 את הדברים על גבי שטר (לדין — פסק דין, לקידושין — שטר אירוסין, לחליצה — שטר חליצה וליבמה — כתובה).","שנינו במשנה: \u0003ואלו הן משום מצוה: לא מקדישין ולא מעריכין ולא מחרימין.\u0004 ומסבירים: טעם האיסור בכל אלה — \u0003גזרה משום מקח וממכר,\u0004 שהרי כל אלה נראים קצת כמסחר, שהוא מעביר קנין לאחר ואסור.","עוד שנינו במשנה: \u0003ולא מגביהין תרומות ומעשרות.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא! \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף: לא נצרכא\u0004 \u0005[נצרכה]\u0006 \u0003אלא ליתנה לכהן בו ביום,\u0004 שהיינו חושבים שכיון שהוא מפריש כדי לתת לכהן הרי זה כשאר הכנה של אוכל ויש להתירו, לכך אסרוהו במפורש.","ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה\u0006 אמורים\u0005]\u0006 דווקא ב\u0003פירי דטבילי\u0004 \u0005[\u0006ב\u0005פירות שנעשו טבל]\u0006 וחלה עליהם חובת הפרשה \u0003מאתמול, אבל פירי דטבילי האידנא\u0004 \u0005[פירות שנעשו טבל עכשיו],\u0006 \u0003כגון עיסה\u0004 שנעשתה בחג עצמו והינה נחשבת כטבל \u0003ל\u0004ענין \u0003אפרושי מינה\u0004 \u0005[להפריש ממנה]\u0006 \u0003חלה,\u0004 שכל עוד לא נעשתה העיסה לא חלה חובת הפרשה — \u0003מפרשינן ויהבינן\u0004 \u0005[מפרישים אנו ונותנים אנו]\u0006 אותה \u0003לכהן\u0004 גם ביום טוב.","על לשון המשנה שואלים: \u0003והני\u0004 \u0005[ו\u0006כל \u0005אלה]\u0006 שאמרנו, \u0003משום רשות איכא\u0004 \u0005[יש]\u0006 בהם, ואילו \u0003משום שבות ליכא\u0004 \u0005[אין]\u0006 בהם, \u0003והני\u0004 \u0005[ו\u0006כל \u0005אלה]\u0006 שאמרנו, \u0003משום מצוה איכא\u0004 \u0005[יש]\u0006 בהם, ואילו \u0003משום שבות ליכא\u0004 \u0005[אין]\u0006 בהם? הלא אין הדבר כן!","\u0003אמר ר' יצחק:\u0004 אכן כולם אסורים משום שבות, ושלושה סוגי שבות הם; זו שאיסור גמור היא ואין בה משום מצוה כלל, וזו שהיא של רשות ויש בה צד כלשהו של מצוה, וזו שהיא שבות שיש בה משום מצוה גמורה, והתנא בלשון \u0003לא מבעיא\u0004 \u0005[נצרכה]\u0006 \u0003קאמר\u0004 \u0005[אמר]\u0006 וסידר את הדברים. וכך יש להבין: \u0003לא מבעיא\u0004 \u0005[נצרכה]\u0006 לומר ב\u0003שבות גרידתא\u0004 \u0005[סתם]\u0006 שאין בה מצוה כלל, ש\u0003אסור, אלא אפילו שבות\u0004 של \u0003רשות\u0004 שיש בה צד כלשהו של מצוה, \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור. ולא מבעיא\u0004 \u0005[נצרכה]\u0006 לומר ב\u0003שבות\u0004 של \u0003רשות\u0004 ש\u0003אסור, אלא אפילו שבות\u0004 של \u0003מצוה\u0004 גמורה \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור.\u0004","שנינו במשנה: \u0003כל אלו ביום טוב אמרו,\u0004 וכל שכן בשבת, ואין הבדל בין יום טוב לשבת אלא אוכל נפש בלבד, \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 לכך, ממה שלמדנו במשנה: \u0003משילין\u0004 פירות הנמצאים על הגג לייבוש וחוששים שיתקלקלו מן הגשמים \u0003דרך\u0004 ה\u0003ארובה\u0004 שבגג לתוך הבית \u0003ביום טוב, אבל לא בשבת,\u0004 הרי שיש הבדל נוסף בין יום טוב לשבת!","\u0003אמר רב יוסף:\u0004 דבר זה \u0003לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הא [זו]\u0004 משנתנו שאינה מכלילה את דין השלת הפירות כזה שיש לגבי איסורו הבדל בין שבת ליום טוב — כשיטת \u0003ר' אליעזר\u0004 היא, \u0003הא\u0004 \u0005[זו]\u0006 המשנה הקודמת שלדבריה יש אף בכך הבדל שבחג התירו ובשבת אסרו — כשיטת \u0003ר' יהושע\u0004 היא.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אותו ואת בנו\u0004 כלומר, ששתי בהמות אם ובנה \u0003שנפלו לבור\u0004 ורוצים להעלות אותן משום צער בעל חיים, וכיון שאין לעשות מלאכה כזו שלא לצורך אוכל נפש — יש להעלותם לשם שחיטה. אולם כיון שהן בכלל איסור \"אותו ואת בנו\", ואסור לשחטם באותו יום, אם כן מה יעשו? \u0003ר' אליעזר אומר: מעלה את הראשון על מנת לשוחטו ו\u0004אכן \u0003שוחטו, והשני עושה לו פרנסה\u0004 (נותן לו אוכל) \u0003במקומו כדי שלא ימות\u0004 שם.","ואילו \u0003ר' יהושע אומר: מעלה את הראשון על מנת לשוחטו ואינו שוחטו, וחוזר ומערים\u0004 ואומר שרוצה לשחוט את השני \u0003ומעלה\u0004 את \u0003השני.\u0004 ולבסוף \u0003רצה\u0004 — \u0003זה שוחט, רצה\u0004 — \u0003זה שוחט.\u0004 ואם כן רואים שר' יהושע סבור שיש להקל ביום טוב בדבר שיש בו הפסד ממוני וצער לבעליו, ואם כן אף לענין הפירות הוא סבור כן ולדעתו מותר להשילם דרך ארובה בחג. אבל לר' אליעזר אין חילוק בין שבת וחג אלא לענין אוכל נפש בלבד ואף במקום הפסד לא התירו.","\u0003אמר\u0004 \u0005[לו]\u0006 \u0003אביי: ממאי\u0004 \u0005[ממה]\u0006 מסיק אתה שיש דמיון בין הדברים? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[שאמר]\u0006 \u0003ר' אליעזר התם\u0004 \u0005[שם]\u0006 שמשאירים את הבהמה בבור \u0003אלא\u0004 כש\u0003אפשר בפרנסה, אבל הכא\u0004 \u0005[כאן]\u0006 בפירות ש\u0003לא אפשר בפרנסה\u0004 — \u0003לא,\u0004 ויתיר להשילם!","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אתה יכול לומר להיפך: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[שאמר]\u0006 \u0003ר' יהושע התם\u0004 \u0005[שם]\u0006 בשתי בהמות, \u0003אלא\u0004 משום ש\u0003אפשר לאערומי\u0004 \u0005[להערים],\u0006 ויכול הרואה לחשוב שאין כוונתו דווקא כדי להציל את ממונו, אלא יכול להיות שהוציא את הראשון לאכילה ומשלא מצא חן בעיניו, הוציא את השני. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 ש\u0003לא אפשר לאערומי\u0004 \u0005[להערים],\u0006 שהדבר ברור שכל כוונתו להציל את הפירות — \u0003לא,\u0004 ואם כן אין ראיה לדברי רב יוסף.","\u0003אלא אמר רב פפא:\u0004 יש לדחות הסבר זה ולתרץ באופן אחר: \u0003לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 כשיטת \u0003בית שמאי, הא\u0004 \u0005[זו]\u0006 כשיטת \u0003בית הלל.\u0004","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003בית שמאי אומרים אין מוציאין לא את הקטן\u0004 (התינוק) שאינו יכול להלך \u0003ולא את הלולב, ולא את ספר תורה לרשות הרבים\u0004 ביום טוב לפי שאינם צורכי אוכל נפש, \u0003ובית הלל מתירין.\u0004 הרי שהתירו בית הלל גם דברים אחרים ביום טוב!","ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003לא\u0004 כן \u0003היא, עד כאן לא\u0004 שמענו כי \u0003קא אמרי\u0004 \u0005[שאמרו]\u0006 \u0003בית שמאי התם\u0004 \u0005[שם]\u0006 \u0003אלא\u0004 לענין איסור \u0003הוצאה\u0004 מרשות לרשות, \u0003אבל\u0004 לענין \u0003טלטול לא\u0004 אמרו כן. את הטענה הזו דוחים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003טלטול לאו\u0004 \u0005[לא]\u0006 \u0003צורך הוצאה הוא?\u0004 שהרי כל עיקר הגזירה ההיא בדבר טלטול מוקצה — אינה אלא משום חשש הוצאה, ואם כן אין בכך כדי לדחות את הסברו של רב פפא.","\u0003הבהמה והכלים\u0004 דינם ביום טוב \u0003כרגלי הבעלים,\u0004 שלכל מקום שמותר לבעליהם ללכת — מותר אף להביא אותם לשם. \u0003המוסר בהמתו לבנו או לרועה\u0004 — \u0003הרי אלו כרגלי הבעלים\u0004 ולא כרגלי הרועה או הבן.","\u0003כלים המיוחדין לאחד מן האחין שבבית\u0004 ואין לאחים האחרים חלק בהם — \u0003הרי אלו כרגליו,\u0004 ובמקום שהוא רשאי ללכת אף הם מותרים להטלטל. \u0003ושאין מיוחדין\u0004 — \u0003הרי אלו כמקום שהולכין\u0004 כולם. ואם עירב רק אחד מהם וקנה שביתה במקום אחר, אין מוליכים את הכלים אלא למקום שכולם יכולים להלך בו.","\u0003השואל כלי מחבירו מערב יום טוב\u0004 — הרי הכלי \u0003כרגלי השואל,\u0004 ולא כרגלי בעל הכלי, כיון שבשעת כניסת השבת קנה הכלי שביתה אצלו. אבל אם שאלו \u0003ביום טוב\u0004 עצמו — הרי זה \u0003כרגלי המשאיל,\u0004 כיון שבשעת כניסת החג היה הכלי עדיין ברשות המשאיל וקנה שביתה אצלו. \u0003וכן האשה ששאלה מחברתה תבלין ומים ומלח לעיסתה\u0004 — \u0003הרי אלו\u0004 כולם \u0003כרגלי שתיהן. ור' יהודה פוטר במים, מפני שאין בהן ממש\u0004 בתערובת ולכן אין מחשיבים אותם לבעליהם הראשונים.","ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו],\u0006"],["ש\u0003לא כ\u0004שיטת \u0003ר' דוסא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' דוסא אומר, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אבא שאול\u0004 הוא זה ש\u0003אומר\u0004 זאת; \u0003הלוקח בהמה מחברו מערב יום טוב, אף על פי שלא מסרה לו אלא ביום טוב\u0004 עצמו — \u0003הרי היא כרגלי הלוקח, והמוסר בהמה לרועה, אף על פי שלא מסרה לו אלא ביום טוב\u0004 — \u0003הרי היא כרגלי הרועה.\u0004 ואילו במשנתנו שנינו כי המוסר בהמה לרועה — הרי היא כרגלי הבעלים!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כי משנתנו כדעת \u0003ר' דוסא\u0004 היא, \u0003ו\u0004אף על פי כן \u0003לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003כאן\u0004 בדברי ר' דוסא מדובר \u0003ב\u0004שיש בעיר זו \u0003רועה אחד\u0004 בלבד, שכיון שיודע הבעלים מראש כי הוא הרועה אשר לו תימסר הבהמה לרעייה, הריהו מעמידה כבר ברשותו ונמצא שקנה הבהמה שביתה אצל הרועה ולכן היא כרגליו. אולם \u0003כאן\u0004 במשנתנו מדובר, שיש בעיר זו \u0003שני רועים\u0004 שונים ואינו יודע למי מהם ימסרנה לרעייה, וכיון שאין הדבר ברור, נשארת הבהמה כרגלי הבעלים. ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנה]\u0006 במשנתנו: \u0003לבנו או לרועה,\u0004 כלומר: משמע שלא ברור לו למי ימסרנה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: הלכה כר' דוסא.\u0004 ושואלים: \u0003ומי\u0004 \u0005[האם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן\u0004 הלכה כללית: \u0003הלכה כסתם משנה, ותנן\u0004 \u0005[ו\u0006הרי \u0005שנינו\u0006 במשנתנו\u0005]\u0006 \u0003הבהמה והכלים כרגלי הבעלים!\u0004","ומשיבים: \u0003ולאו אוקימנא\u0004 \u0005[ו\u0006האם \u0005לא העמדנו]\u0006 את ההבדל בין המשנה והברייתא ש\u0003כאן\u0004 בברייתא מדובר \u0003ברועה אחד\u0004 והלכה כר' דוסא, \u0003כאן בשני רועים\u0004 ובכך לא חלק ר' דוסא.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שנים ששאלו\u0004 מאחר \u0003חלוק אחד בשותפות, זה\u0004 שאלו כדי \u0003לילך בו שחרית לבית המדרש וזה\u0004 שאלו כדי \u0003ליכנס בו ערבית לבית המשתה\u0004 (לחתונה). \u0003זה,\u0004 אחד מהשואלים, \u0003ערב עליו לצפון,\u0004 שהמקום אליו הוא מעוניין לילך כשהוא לבוש בחלוק זה רחוק ממקום מושבו הקבוע, וצריך לעשות עירוב תחומים כדי שיוכל ללכת לשם בשבת, \u0003וזה,\u0004 השני, \u0003ערב עליו לדרום,\u0004 הרי \u0003זה שערב עליו לצפון\u0004 — \u0003מהלך לצפון\u0004 עם החלוק רק \u0003כרגלי מי שערב עליו לדרום.\u0004 שאסור לו להרחיק יותר ממה שמותר לשואל השני ללכת.","\u0003ו\u0004כן \u0003זה שערב עליו לדרום מהלך לדרום\u0004 רק \u0003כרגלי מי שערב עליו לצפון.\u0004 וכגון שהניח כל אחד מהם את עירובו במרחק אלף אמה ממקומו, זה לצפון וזה לדרום, כך שכל אחד מהם יכול להלך בעצמו שלושת אלפים אמה ממקומו (אותם אלף אמה ועוד מרחק תחום שבת שהוא אלפיים אמה ממקום הנחת העירוב). אולם את החלוק, כיון שהוא כרגלי שניהם, לא יוכל אף אחד מהם להוליכו אלא למרחק אלף אמה ממקומו (שהוא מקום הנחת עירובו) ונמצא שכל אחד מהם אינו יכול להוליך את החלוק עימו אלא עד למקום קניית שביתתו שהוא אלף אמה ממקומו, כיון שזהו סוף תחומו של חבירו שקנה שביתתו במרחק אלף אמה לצד האחר.","\u0003ואם מצעו את התחום,\u0004 שכל אחד מהם הניח עירובו וקנה שביתתו במרחק אלפיים אמה ממקומו, ונמצא שהמקום המרוחק ביותר אליו יכול כל אחד מהם ללכת ולהוליך את החלוק עימו, הוא מקום מושבם הקבוע ואף לא אמה אחת יותר לכיוון בו הניח השני את עירובו — \u0003הרי זה לא יזיזנה ממקומה.\u0004","\u0003אתמר\u0004 \u0005[נאמר],\u0006 שחלקו אמוראים בשאלה זו: \u0003שנים שלקחו\u0004 (קנו) מערב יום טוב \u0003חבית\u0004 או \u0003בהמה בשותפות\u0004 על מנת לחלקה ביניהם ביום טוב עצמו, מה יעשו? \u0003רב אמר: חבית מותרת\u0004 שכל אחד יטול את חלקו ויוליכנו למקומו ביום טוב \u0003ובהמה אסורה,\u0004 ואין מוליכים אותה אלא למקום ששניהם יכולים ללכת. \u0003ושמואל אמר: חבית נמי\u0004 \u0005[גם כן]\u0006 \u0003אסורה.\u0004","על שיטתו של רב שואלים: \u0003מאי קסבר\u0004 \u0005[מה סבר]\u0006 \u0003רב\u0004 ומה טעמו? \u0003אי קא סבר\u0004 \u0005[אם הוא סבור]\u0006 כי \u0003יש ברירה,\u0004 שאנו מקבלים את העיקרון, שלמפרע, לאחר מעשה, מתברר איזה חלק היה מיועד מראש לאותו אדם וקנה שביתה אצלו — אם כן \u0003אפילו בהמה תשתרי\u0004 \u0005[תהא מותרת]!\u0006 \u0003ואי קסבר\u0004 \u0005[ואם סבור הוא]\u0006 כי \u0003אין ברירה\u0004 ואין אומרים כי החלק שנטל זהו החלק שמלכתחילה היה שלו וקנה שביתה ברשותו — אם כן \u0003אפילו חבית נמי\u0004 \u0005[גם כן]\u0006 \u0003אסורה!\u0004","ומשיבים: \u0003לעולם\u0004 תפרש כי \u0003קסבר\u0004 \u0005[הוא סבר]\u0006 \u0003יש ברירה,\u0004 ומה שאסר רב בבהמה, כי \u0003שניא\u0004 \u0005[שונה]\u0006 \u0003בהמה דקא ינקי\u0004 \u0005[שיונקים]\u0006 ה\u0003תחומין מהדדי\u0004 \u0005[זה מזה],\u0006 שהרי הבהמה אינה מחולקת בחייה לשני חלקים, וכל חלק תלוי ויונק מחבירו ולכן אי אפשר לומר שמראש היה כל חלק שייך ומוגדר כשל אחד מהם וקנה שביתה במקומו. \u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 \u0003רב כהנא ורב אסי לרב:\u0004 אם לכך אתה חושש, אם כן יוצא מדבריך כי \u0003לאיסור מוקצה לא חששו,\u0004 שאין אומרים שכל אחד הקצה מדעתו את חלקו של חבירו ואסור להשתמש בו, ואילו \u0003לאיסור תחומין חששו?! שתיק\u0004 \u0005[שתק]\u0006 \u0003רב\u0004 ולא ענה.","ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]\u0006 על בעיה זו? \u0003ר' הושעיה אמר:\u0004 בכלל \u0003יש ברירה,\u0004 ולכן יכול כל אחד מהם להוליך גם את החבית וגם את הבהמה למקומו. \u0003ור' יוחנן אמר: אין ברירה,\u0004 ואין מוליכים לא את החבית ולא את הבהמה אלא למקום ששניהם מותרים בו.","ושואלים: \u0003ו\u0004כי \u0003סבר ר' הושעיא\u0004 כי \u0003יש ברירה? והתנן\u0004 \u0005[והלא\u0006 \u0005שנינו\u0006 במשנה\u0005]:\u0006 היה \u0003המת בבית, ולו\u0004 לבית \u0003פתחים\u0004 אשר לעת עתה הם סגורים \u0003הרבה\u0004 — \u0003כולן טמאים,\u0004 כי יש לחשוש שמא דרך כל אחד מהם יוציאו את המת מן הבית והרי הם נחשבים כחלק מחלל הבית. \u0003נפתח אחד מהן\u0004 מן הפתחים — \u0003הוא\u0004 אותו פתח \u0003טמא\u0004 בכל חללו, \u0003וכולן טהורים,\u0004 שהדבר ברור שיוציאו את המת דרך פתח זה. ואפילו לא נפתח אחד מהם בפועל, אלא ש\u0003חשב להוציאו באחד מהן או\u0004 להוציאו \u0003בחלון שיש בו ארבעה על ארבעה\u0004 טפחים — הרי מחשבה זו \u0003מצלת על הפתחים כולן\u0004 וכולן טהורים, חוץ מאותו פתח.","ונחלקו תנאים בפרטי הלכה זו, \u0003בית שמאי אומרים: והוא שחשב עליו עד שלא ימות המת\u0004 וכאשר מת היה ברור דרך איזה פתח מוציאים אותו. \u0003ובית הלל אומרים: אף\u0004 אם חשב עליו רק \u0003משימות המת.\u0004","\u0003ואתמר עלה\u0004 \u0005[ונאמר עליה]\u0006 על משנה זו, \u0003אמר ר' הושעיא:\u0004 מה שאמרו בית הלל שאף לאחר מיתה, משיחשוב להוציאו דרך פתח מסויים יטהרו שאר הפתחים — הרי זה \u0003לטהר את הפתחים מכאן ולהבא,\u0004 כלומר: משעת מחשבה ואילך שוב אין בהם טומאה, ונדייק: \u0003מכאן ולהבא — אין\u0004 \u0005[כן],\u0006 אין האחרים נטמאים, אולם \u0003למפרע\u0004 — \u0003לא.\u0004 משמע שאין אומרים שיש ברירה, שהרי אין המחשבה מטהרת את הפתחים למפרע.","את הסתירה הזו מתרצים: אם כן \u0003אפוך\u0004 \u0005[הפוך]\u0006 ואמור כך, \u0003ר' הושעיא אמר: אין ברירה, ור' יוחנן אמר: יש ברירה.\u0004","ושואלים: \u0003ומי אית ליה\u0004 \u0005[האם יש לו,\u0006 מקבל\u0005]\u0006 \u0003ר' יוחנן\u0004 את עיקרון ה\u0003ברירה? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב אסי אמר ר' יוחנן: האחין שחלקו\u0004 את רכוש אביהם — כ\u0003לקוחות\u0004 (קונים) \u0003הן\u0004 נחשבים, וכמו כל הלקוחות — \u0003מחזירין זה לזה ביובל\u0004 ואז הם חוזרים ומחלקים מחדש. הרי שהוא סבור שאין אומרים שהתברר למפרע שכל אחד קיבל את חלקו הראוי, אלא חוזרים וחולקים מחדש בכל פעם.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003כי לית ליה\u0004 \u0005[כאשר\u0006 \u0005אין לו\u0006 לא מקבל\u0005]\u0006 \u0003ר' יוחנן\u0004 את עקרון הברירה, הרי זה \u0003בדאורייתא\u0004 \u0005[ב\u0006דברים \u0005שמדברי תורה]\u0006 \u0003אבל בדרבנן אית ליה\u0004 \u0005[ב\u0006דברים שהם \u0005מדברי סופרים יש לו],\u0006 אולם","\u0003ובדרבנן מי אית ליה\u0004 \u0005[ובדברי סופרים האם יש לו]\u0006 ברירה? \u0003והתני\u0004 \u0005[והרי שנה]\u0006 החכם \u0003איו\u0004 לענין דיני עירובי תחומים, כאשר דובר באפשרות שיניח אדם בערב שבת שני עירובים לכיוונים שונים על תנאי שיחול העירוב שהניח באותו צד שיבוא החכם, ואם יבואו שנים משני כיוונים שונים — משעה שהחליט את דרשת איזה מהם רצונו לשמוע והולך לאותו כיוון בכך נתברר שמערב שבת קנה שביתה לאותו צד, ועל זה","\u0003ר' יהודה\u0004 חולק ו\u0003אומר: אין אדם מתנה על שני דברים כאחד,\u0004 וכגון באופן שעתידים לבוא שני חכמים, ואין תנאי זה מועיל \u0003אלא אם\u0004 יודע על חכם אחד שעתיד לבוא אלא שאינו יודע מאיזה צד עתיד הוא לבוא ובכך הוא רשאי להתנות שאם \u0003בא חכם למזרח\u0004 — \u0003ערובו למזרח,\u0004 ואם בא החכם \u0003למערב\u0004 — \u0003ערובו למערב, ואילו לכאן ולכאן\u0004 — \u0003לא,\u0004 ואי אפשר לומר שיתברר למחרת באיזה מן הצדדים חל העירוב."]]};
